"בפעם הבאה ננסה כך"]}, {"id": "i8", "name": "לרשום מה כבר יודע/ת", "what": "רשימה אישית של מיומנויות שנלמדו, ומוסיפים אליה.", "why": "רשימה שגדלה מראה כמה כבר הושג.", "freq": "מדי פעם, לסיכום", "approach": "טיפול נרטיבי", "targets": ["t5"], "sentences": ["בוא/י נוסיף לרשימה", "תראה/תראי כמה למדת", "מה הבא?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לעבור מפעילות לפעילות בלי סערה', 'להפסיק משהו אהוב ולעבור לדבר הבא, גם כשקשה', array['מעברים ושגרה']::text[], 'מעברים ושגרה', array['ARC', 'ויסות חושי', 'TBRI', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לקטוע פתאום בלי התראה, ולא לגרור בכוח", "strengths": ["גמישות", "שמחה", "שיתוף פעולה"], "skills": ["גמישות"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נגזר ממחקר על הכנה למעברים אצל ילדים צעירים (התראה מוקדמת, תמיכה חזותית) ומ-NMT ו-ARC. בסידור חוץ־ביתי זו התאמה יישומית שלא נבדקה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשמודיעים מראש שעוד מעט עוברים, מקבל/ת את ההודעה", "staff": "מקשיב/ה כשאומרים שעוד מעט עוברים", "scale": ["עדיין מתפרץ/ת מיד", "מתלונן/ת ונרגע/ת עם מבוגר", "מתלונן/ת ומקבל/ת", "מקבל/ת בשקט", "מזכיר/ה בעצמו/ה שעוד מעט עוברים"]}, {"id": "t2", "text": "במעבר, מסיים/ת את מה שעושה ועובר/ת עם עזרה קטנה", "staff": "עובר/ת לפעילות הבאה עם עזרה קטנה", "scale": ["עדיין מסרב/ת לעבור", "עובר/ת כשמבוגר מלווה צמוד", "עובר/ת עם שיר או משחק", "עובר/ת עם מילה", "עובר/ת לבד"]}, {"id": "t3", "text": "משתמש/ת בחפץ מעבר או בתפקיד כדי לעבור (להחזיק משהו, להוביל)", "staff": "עובר/ת עם תפקיד או חפץ", "scale": ["עדיין לא משתמש/ת", "לוקח/ת כשנותנים", "לוקח/ת ועובר/ת", "מבקש/ת תפקיד במעבר", "עוזר/ת לחבר לעבור"]}, {"id": "t4", "text": "כשהמעבר קשה, נרגע/ת תוך זמן קצר", "staff": "נרגע/ת מהר אחרי מעבר קשה", "scale": ["עדיין סוער/ת זמן ארוך", "נרגע/ת עם מבוגר לאט", "נרגע/ת עם מבוגר מהר", "נרגע/ת לבד מהר", "כמעט לא סוער/ת"]}, {"id": "t5", "text": "מצביע/ה בלוח התמונות על מה עכשיו ומה אחר כך", "staff": "מראה בלוח מה עכשיו ומה אחר כך", "scale": ["עדיין לא מתעניין/ת בלוח", "מסתכל/ת כשמראים", "מצביע/ה על ''עכשיו''", "מצביע/ה על ''עכשיו'' ו''אחר כך''", "בודק/ת בלוח מיוזמתו/ה"]}], "interventions": [{"id": "i1", "name": "להודיע מראש", "what": "כמה דקות לפני מעבר, מודיעים בגובה העיניים,