insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'המעבר בין המרכז לבית הספר', 'לצאת לבית הספר ולחזור ממנו בלב רגוע', array['מעברים ושגרה']::text[], 'מעברים ושגרה', array['מעגל הביטחון', 'ARC', 'DDP/PACE', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לחקור על כל היום מיד בכניסה, ולא לשתף את בית הספר בפרטים אישיים בלי המטפלת", "strengths": ["אומץ", "אחריות", "סקרנות"], "skills": ["פנייה למבוגר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נגזר ממחקר על חשיבות הקשר בין הבית לבית הספר לילדים בסידור חוץ־ביתי ומעקרונות ARC ו-TBRI. ההתערבויות הן התאמה יישומית שלא נבדקה."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "יוצא/ת לבית הספר בבוקר בלי סירוב או סערה", "staff": "יוצא/ת לבית הספר בבוקר", "scale": ["עדיין מסרב/ת או בסערה", "יוצא/ת עם מאמץ רב", "יוצא/ת עם עזרה", "יוצא/ת בזמן ברוב הימים", "יוצא/ת בזמן ובמצב רוח טוב"]}, {"id": "t2", "text": "בחזרה מבית הספר, נרגע/ת ומשתלב/ת אצלנו תוך זמן קצר", "staff": "נרגע/ת מהר אחרי בית הספר", "scale": ["עדיין סוער/ת זמן ארוך", "נרגע/ת עם מבוגר לאט", "נרגע/ת עם זמן שקט", "נרגע/ת מהר", "חוזר/ת ומספר/ת ברוגע"]}, {"id": "t3", "text": "מספר/ת למבוגר דבר אחד מהיום בבית הספר", "staff": "מספר/ת משהו מבית הספר", "scale": ["עדיין לא מספר/ת", "עונה במילה", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מספר/ת גם על דבר קשה"]}, {"id": "t4", "text": "יודע/ת למי לפנות בבית הספר כשקשה", "staff": "יודע/ת למי לפנות בבית הספר", "scale": ["עדיין לא יודע/ת", "יודע/ת כשמזכירים", "יודע/ת את השם", "פונה כשצריך", "פונה ומספר/ת לנו אחר כך"]}, {"id": "t5", "text": "לוקח/ת את מה שצריך לבית הספר (תיק, אוכל, מכתבים)", "staff": "לוקח/ת את מה שצריך לבית הספר", "scale": ["עדיין שוכח/ת הכל", "לוקח/ת עם מבוגר", "לוקח/ת עם תזכורת", "לוקח/ת לבד ברוב הימים", "בודק/ת לבד ומזכיר/ה"]}], "interventions": [{"id": "i1", "name": "לעשות טקס יציאה", "what": "טקס קבוע ביציאה: בדיקת תיק, משפט עידוד, מתי חוזרים.", "why": "יציאה צפויה מו