ם רק על מה שכבר ידוע, ולא מוסיפים פרטים.", "why": "מידע לא מתואם יוצר בלבול וחוסר אמון.", "freq": "לאורך כל התהליך", "approach": "ARC", "targets": ["t1"], "sentences": ["המטפלת תספר לך על זה", "אני כאן אם יש שאלות", "את מה שאני יודע/ת אגיד לך"], "avoid": "לא לספר פרטים לפני שהוחלט"}, {"id": "i2", "name": "לענות בכנות", "what": "עונים על שאלות בכנות ובפשטות, ומה שלא ידוע אומרים שלא ידוע.", "why": "כנות במעבר בונה אמון למקום הבא.", "freq": "בכל שאלה", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["זו שאלה חשובה", "את זה עוד לא יודעים", "נברר ביחד"]}, {"id": "i3", "name": "לפתוח מקום לרגשות", "what": "שיחות קצרות על מה מרגיש/ה: פחד, כעס, הקלה, ציפייה. כל רגש מקבל מקום.", "why": "רגשות מעורבים טבעיים במעבר.", "freq": "באופן קבוע לקראת המעבר", "approach": "DDP/PACE", "targets": ["t2"], "sentences": ["איך אתה/את מרגיש/ה עם המעבר?", "אפשר להרגיש כמה דברים יחד", "תודה ששיתפת"]}, {"id": "i4", "name": "לשתף בהכנות", "what": "נותנים תפקיד בהכנות: לארוז, לבחור מה לוקחים, להכין שאלות לביקור.", "why": "השתתפות מחזירה תחושת שליטה.", "freq": "בשבועות שלפני המעבר", "approach": "CPS", "targets": ["t3"], "sentences": ["מה חשוב לך לקחת?", "איזה שאלות נכין לביקור?", "אתה/את מוביל/ה את זה"]}, {"id": "i5", "name": "להכין ספר זיכרונות", "what": "מכינים יחד ספר או קופסה מהתקופה כאן: תמונות, מכתבים מהצוות ומחברים (בהנחיית המטפלת).", "why": "זיכרון מוחשי מחבר בין המקומות.", "freq": "לקראת המעבר", "approach": "טיפול נרטיבי", "targets": ["t5"], "sentences": ["מה תרצה/תרצי לשים בספר?", "כתבתי לך משהו", "זה שלך לקחת"]}, {"id": "i6", "name": "לתכנן פרידה", "what": "מתכננים יחד איך להיפרד: מסיבה קטנה, מכתבים, שיחה אישית.", "why": "פרידה מתוכננת סוגרת פרק בכבוד.", "freq": "לקראת המעבר", "approach": "מעגל הביטחון", "targets": ["t4"], "sentences": ["איך היית רוצה להיפרד?", "ממי חשוב לך להיפרד?", "נעשה את זה יחד"]}, {"id": "i7", "name": "לספר את הסיפור של התקופה", "what": "שיחה על מה למד/ה כאן, מה השתנה ומה לוקח/ת איתו/ה (בהנחיית המטפלת).", "why": "סיפור עם משמעות עוזר להמשיך הלאה.", "freq": "לקראת המעבר", "approach": "טיפול נרטיבי", "targets": ["t5", "t2"], "sentences": ["מה למדת כאן?", "מה השתנה בך?", "מה תיקח/תיקחי איתך?"]}, {"id": "i8", "name": "לא להבטיח מה שלא יקרה", "what": "מדברים בכנות על קשר אחרי המעבר, רק מה שהוחלט ואפשרי.", "why": "הבטחה שלא מתקיימת פוגעת באמון.", "freq": "תמיד", "approach": "ARC", "targets": ["t4"], "sentences": ["אני לא יודע/ת אם נתראה", "אבל אני אזכור אותך", "מה שהיה כאן נשאר שלך"], "avoid": "לא להבטיח לבקר או להתקשר אם זה לא אושר"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'לילה בטוח', 'להירדם ולחזור לישון בלילה עם תחושה שיש מי ששומר', array['שינה ואכילה']::text[], 'שינה ואכילה', array['ARC', 'מעגל הביטחון', 'ויסות חושי', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לבטל את שגרת ההשכבה בגלל התנהגות ביום, ולא להשאיר ילד לבכות לבד", "strengths": ["אמון", "שקט פנימי", "בקשת עזרה"], "skills": ["הרגעה עצמית"], "main": "2-5", "also": [], "evidence": {"level": "derived", "note": "הקשר בין שגרת שינה קבועה לשינה ולוויסות נבדק בילדים באוכלוסייה הכללית; ההמלצה לנוכחות ולהרגעה בלילה עולה מעבודה עם ילדים באומנה. במסגרות קבוצתיות עם מדריכים במשמרות זו התאמה שלא נבדקה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "ברגעי ההשכבה, משתתף/ת בשלבי השגרה הקבועה (צחצוח, פיג''מה, סיפור, אור קטן)", "staff": "משתתף/ת בשגרת ההשכבה", "scale": ["עדיין מתנגד/ת או נבהל/ת ברוב השלבים", "משתתף/ת כשמבוגר עושה איתו/ה כל שלב", "עובר/ת שלבים אחרי רמז", "מבקש/ת בעצמו/ה את השלב הבא", "משתתף/ת גם עם מבוגר פחות מוכר"]}, {"id": "t2", "text": "כשהמבוגר מתרחק בהשכבה, נשאר/ת במיטה עם החפץ האהוב ונרגע/ת", "staff": "נרגע/ת במיטה עם החפץ שלו/ה", "scale": ["עדיין לא נרגע/ת בלי מבוגר צמוד", "נרגע/ת כשמבוגר יושב ליד המיטה", "נרגע/ת כשהמבוגר ליד הדלת", "נרגע/ת עם החפץ והצצה קבועה", "נרגע/ת כך גם עם מבוגר אחר"]}, {"id": "t3", "text": "כשמתעורר/ת בלילה, קורא/ת למבוגר או מחבק/ת את החפץ במקום להסתובב לבד", "staff": "קורא/ת למבוגר כשמתעורר/ת", "scale": ["עדיין מסתובב/ת, בוכה הרבה או מסתגר/ת", "נרגע/ת כשמבוגר מגיע", "קורא/ת בדרך שסיכמנו", "חוזר/ת לישון אחרי הרגעה קצרה", "חוזר/ת לישון עם החפץ גם בלילות קשים"]}, {"id": "t4", "text": "מכיר/ה את מבוגר הלילה ומקבל/ת את הנוכחות שלו", "staff": "מקבל/ת את מבוגר הלילה", "scale": ["עדיין נבהל/ת ממבוגר הלילה", "מקבל/ת כשמדריך/ת היום מציג/ה אותו/ה", "מגיב/ה לברכה של מדריך/ת הלילה", "פונה למדריך/ת הלילה כשצריך", "נרגע/ת עם כל מדריך/ת לילה"]}, {"id": "t5", "text": "ישן/ה רוב הלילה ברוב הלילות", "staff": "ישן/ה רוב הלילה", "scale": ["עדיין מתעורר/ת הרבה פעמים", "מתעורר/ת כמה פעמים", "מתעורר/ת פעם אחת", "ישן/ה ברצף ברוב הלילות", "ישן/ה ברצף גם אחרי יום קשה"]}], "interventions": [{"id": "i1", "name": "לעבור על שלבי ההשכבה בלוח", "what": "אותם שלבים באותו סדר כל ערב, עם לוח תמונות קטן ליד המיטה.", "why": "ערב צפוי אומר לגוף שהלילה בטוח.", "freq": "כל ערב", "approach": "ARC", "targets": ["t1"], "sentences": ["עכשיו פיג''מה, אחר כך סיפור", "כמו כל ערב", "ועכשיו האור הקטן"], "avoid": "לא לקצר או לבטל את השגרה בגלל התנהגות ביום"}, {"id": "i2", "name": "לשמור על החפץ האהוב", "what": "בובה, שמיכה או חפץ אישי שנשאר אצלו/ה תמיד. אם צריך לכבס, מחזירים עוד באותו יום.", "why": "חפץ מוכר מרגיע כשהמבוגר רחוק.", "freq": "תמיד", "approach": "מעגל הביטחון", "targets": ["t2", "t3"], "sentences": ["הדובי שומר עליך", "הוא תמיד נשאר אצלך", "תחבק/י אותו חזק"], "avoid": "לא לקחת את החפץ כעונש"}, {"id": "i3", "name": "לבדוק יחד את החדר", "what": "אור עמום, שקט קבוע, ובודקים איתו/ה מה מפחיד בחדר (צל, ארון, דלת) ומסדרים.", "why": "חדר שבדקנו יחד מפחיד פחות.", "freq": "בקליטה וכשמשהו משתנה", "approach": "ויסות חושי", "targets": ["t1", "t5"], "sentences": ["בוא/י נבדוק ביחד", "הנה הארון, הוא סגור", "האור הקטן נשאר"]}, {"id": "i4", "name": "להתרחק מהמיטה בהדרגה (בהנחיית המטפלת)", "what": "המבוגר יושב ליד המיטה, ובמשך ימים זז לאט לכיוון הדלת, וחוזר להציץ כמו שאמר.", "why": "התרחקות איטית בונה ביטחון בלי לנטוש.", "freq": "כל ערב, בקצב שהמטפלת קובעת", "approach": "מעגל הביטחון", "targets": ["t2"], "sentences": ["אני יושב/ת פה ליד הדלת", "אני אבוא להציץ", "הנה, באתי להציץ"], "avoid": "לא לצאת בהחבא כשנרדם/ת"}, {"id": "i5", "name": "להציג את מדריך/ת הלילה", "what": "מבוגר הלילה מציג את עצמו לפני ההשכבה כשאפשר, ויודע מהכרטיס מה מרגיע את הילד/ה.", "why": "מבוגר לילה שמכיר את הילד הוא לא זר.", "freq": "בכל משמרת לילה", "approach": "TBRI", "targets": ["t4"], "sentences": ["הלילה אני כאן", "אני יודע/ת שאתה/את אוהב/ת את האור הקטן", "אם צריך, תקרא/י לי"]}, {"id": "i6", "name": "לבוא מהר ולהרגיע בשקט", "what": "בהתעוררות מגיעים מהר, קול נמוך, בלי אור חזק ובלי שיחה ארוכה, וחוזרים לשגרה הקצרה.", "why": "תגובה רגועה וקבועה מלמדת שהלילה בטוח.", "freq": "בכל התעוררות", "approach": "TBRI", "targets": ["t3", "t5"], "sentences": ["אני פה", "אתה/את בטוח/ה", "זה לילה, ישנים"], "avoid": "לא להעביר למיטה של מבוגר או של ילד אחר"}, {"id": "i7", "name": "לגעת רק לפי מה שסוכם (בהנחיית המטפלת)", "what": "המטפלת קובעת איזה מגע מתאים בלילה (יד על השמיכה, בלי מגע). בילדים שנפגעו בלילה מעדיפים קול ונוכחות.", "why": "מגע שלא מתאים יכול להפחיד במקום להרגיע.", "freq": "תמיד", "approach": "TBRI", "targets": ["t3"], "sentences": ["אני כאן לידך", "אני לא נוגע/ת, רק יושב/ת", "תגיד/י לי מה עוזר"]}, {"id": "i8", "name": "להחליף בשקט אחרי הרטבה", "what": "בגיל הזה הרטבה היא לרוב חלק רגיל מההתפתחות. מחליפים בשקט ובלי הערות. הרטבה חדשה או עם כאב מעבירים לצוות הרפואי.", "why": "החלפה שקטה שומרת על כבוד ועל השינה.", "freq": "בכל הרטבה", "approach": "TBRI", "targets": ["t5"], "sentences": ["זה קורה, נחליף", "הנה בגדים יבשים", "חוזרים לישון"], "avoid": "לא להעיר, לא להעניש ולא לספר לאחרים"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'שולחן רגוע', 'לאכול בשקט, ולטעום דברים חדשים בלי לחץ', array['שינה ואכילה']::text[], 'שינה ואכילה', array['ARC', 'TBRI', 'ויסות חושי']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא ללחוץ לאכול, לא לאיים בקינוח ולא לשבח על כמות", "strengths": ["סקרנות", "אמון", "שיתוף פעולה"], "skills": ["הבעת צורך"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "חשיפה חוזרת בלי לחץ נבדקה ונמצאה יעילה בילדים באוכלוסייה הכללית. חלוקת האחריות בהאכלה והאכלה מותאמת טראומה הן גישות מקצועיות מקובלות שלא נבדקו במסגרות חוץ־ביתיות."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "בזמני ארוחה, יושב/ת לשולחן זמן שמתאים לגיל ומשתתף/ת בטקס הארוחה", "staff": "יושב/ת לשולחן ומשתתף/ת בארוחה", "scale": ["עדיין לא יושב/ת או נמנע/ת מהשולחן", "יושב/ת כשמבוגר לידו/ה", "מצטרף/ת אחרי תזכורת", "מגיע/ה לשולחן מיוזמתו/ה", "משתתף/ת גם בארוחה חריגה (טיול, חג)"]}, {"id": "t2", "text": "כשמוגש מזון חדש, מסכים/ה שיהיה בצלחת, נוגע/ת, מריח/ה או טועם/ת", "staff": "מסכים/ה לראות או לטעום מזון חדש", "scale": ["עדיין נסער/ת כשהמזון קרוב", "מסכים/ה שיהיה על השולחן", "מסכים/ה שיהיה בצלחת ונוגע/ת", "טועם/ת טעימה קטנה מיוזמתו/ה", "טועם/ת חדש גם במקום אחר"]}, {"id": "t3", "text": "כשרעב/ה או שבע/ה, מראה זאת במילה, בתמונה או בתנועה", "staff": "אומר/ת או מראה רעב או שובע", "scale": ["עדיין לא מבחין/ה או לא מראה", "מגיב/ה לשאלה ''עוד או מספיק?''", "מראה בכרטיס אחרי רמז", "מבקש/ת עוד או אומר/ת מספיק לבד", "אומר/ת גם עם מבוגרים אחרים"]}, {"id": "t4", "text": "יודע/ת מתי הארוחה הבאה ונרגע/ת כשמזכירים", "staff": "יודע/ת שתהיה עוד ארוחה", "scale": ["עדיין נלחץ/ת שלא יהיה אוכל", "נרגע/ת כשמראים בלוח", "שואל/ת מתי אוכלים ומקבל/ת", "יודע/ת לבד מתי הבאה", "מזכיר/ה לחבר שתמיד יש עוד"]}, {"id": "t5", "text": "משתתף/ת בפעילות עם אוכל מחוץ לארוחה (שטיפת ירקות, הגשה)", "staff": "נהנה/נהנית לעזור עם אוכל", "scale": ["עדיין לא מתקרב/ת", "מסתכל/ת", "נוגע/ת עם מבוגר", "משתתף/ת בהנאה", "מציע/ה לעזור"]}], "interventions": [{"id": "i1", "name": "לתלות לוח ''מתי אוכלים''", "what": "ארוחות וביניים בשעות קבועות, ותמונה שמראה מתי אוכלים בפעם הבאה.", "why": "כשיודעים שתמיד יש עוד, האוכל פחות מלחיץ.", "freq": "כל יום", "approach": "ARC", "targets": ["t4"], "sentences": ["אחרי המשחק יש פירות", "תמיד יש עוד ארוחה", "תראה/תראי בלוח"]}, {"id": "i2", "name": "לאכול יחד עם הילדים", "what": "מבוגר יושב לשולחן, אוכל את אותו אוכל, מדבר בנעימות ומראה טעימה בלי לבקש.", "why": "ילדים טועמים כשהם רואים מבוגר רגוע שאוכל.", "freq": "בכל ארוחה שאפשר", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["אני טועם/ת את הגזר", "הוא כתום ופריך", "נעים לאכול ביחד"], "avoid": "לא לומר ''רק עוד ביס'' או ''בלי זה אין קינוח''"}, {"id": "i3", "name": "להגיש חדש שוב ושוב, בלי לחץ", "what": "מנה קטנה של מזון חדש ליד מזון מוכר, שוב לאורך ימים, בלי דרישה לטעום.", "why": "היכרות חוזרת הופכת חדש למוכר.", "freq": "באופן קבוע", "approach": "ויסות חושי", "targets": ["t2"], "sentences": ["זה פה אם תרצה/תרצי", "מותר רק להריח", "אפשר להשאיר בצד"], "avoid": "לא להסתיר אוכל בתוך אוכל, ולא להכריח"}, {"id": "i4", "name": "לשים תמיד ''מזון בטוח''", "what": "בכל ארוחה יש לפחות דבר אחד שהוא/היא מכיר/ה ואוכל/ת (לחם, אורז, פרי).", "why": "מזון מוכר מרגיע את השולחן.", "freq": "בכל ארוחה", "approach": "TBRI", "targets": ["t1", "t4"], "sentences": ["יש פה גם לחם, כמו שאתה/את אוהב/ת", "אפשר להתחיל ממה שמוכר", "יש מספיק"]}, {"id": "i5", "name": "לפתוח ולסגור את הארוחה בטקס", "what": "שיר קצר או משפט קבוע בהתחלה, והודעה מראש לפני הסוף.", "why": "התחלה וסוף ברורים מרגיעים את הגוף.", "freq": "בכל ארוחה", "approach": "ARC", "targets": ["t1"], "sentences": ["שרים ומתחילים לאכול", "עוד מעט מסיימים", "אפשר לסיים את מה שבצלחת"]}, {"id": "i6", "name": "לשאול ''עוד או מספיק?''", "what": "שואלים בפשטות, עם כרטיס תמונה אם צריך, ומכבדים את התשובה.", "why": "ילד שמקשיבים לבטן שלו לומד לסמוך עליה.", "freq": "בכל ארוחה", "approach": "ARC", "targets": ["t3"], "sentences": ["עוד או מספיק?", "הבטן אומרת מספיק? בסדר", "אם תרעב/י, יש עוד"]}, {"id": "i7", "name": "לשחק עם אוכל מחוץ לארוחה", "what": "שוטפים ירקות, מערבבים, מסדרים פירות בצלחת, משחקים בשוק.", "why": "משחק עם אוכל הופך אותו למוכר בלי לחץ.", "freq": "מדי פעם", "approach": "ויסות חושי", "targets": ["t5", "t2"], "sentences": ["בוא/י נרגיש, חלק או מחוספס?", "איזה צבע יפה", "נגיש את זה לכולם?"]}, {"id": "i8", "name": "לרשום ולדווח על סימני אזהרה", "what": "מתעדים בקצרה מה אוכל/ת, ומדווחים למטפלת או לצוות הרפואי על הקאות, היחנקות באוכל, ירידה במשקל או אכילה עד כאב.", "why": "קושי אכילה קיצוני צריך בירור מקצועי.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t3"], "sentences": ["איך הבטן?", "אני רואה שזה קשה לך", "נשאל את האחות, היא יודעת לעזור"], "avoid": "לא לנסות לטפל לבד בבררנות קיצונית"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'כשהלילה מפחיד', 'לדעת מה עושים כשמתעוררים בפחד בלילה', array['שינה ואכילה']::text[], 'שינה ואכילה', array['ARC', 'TBRI', 'TF-CBT', 'NMT', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לחקור על הסיוט, לא להבטיח שזה לא יקרה שוב, ולא לכעוס על התעוררות", "strengths": ["אומץ", "בקשת עזרה", "אמון"], "skills": ["הרגעה עצמית"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "סיוטים ופחד מהלילה שכיחים אחרי טראומה; עבודה על תוכן הסיוטים נבדקה בטיפול מקצועי ולא אצל מדריכים. ההתערבויות לצוות הן התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "לפני השינה, עושה עם מבוגר בדיקת ביטחון קצרה (דלת, אור, איפה המבוגר)", "staff": "עושה בדיקת ביטחון לפני השינה", "scale": ["עדיין מסרב/ת להיכנס למיטה", "עושה עם מבוגר בכל שלב", "עושה עם תזכורת", "עושה לבד ומספר/ת", "לא צריך/ה בדיקה ברוב הלילות"]}, {"id": "t2", "text": "כשמתעורר/ת מסיוט, קורא/ת למבוגר או משתמש/ת בכלי שלו/ה", "staff": "קורא/ת למבוגר או משתמש/ת בכלי", "scale": ["עדיין צורח/ת או מסתובב/ת לבד", "נרגע/ת כשמבוגר מגיע", "קורא/ת למבוגר", "משתמש/ת בכלי ואז קורא/ת", "משתמש/ת בכלי וחוזר/ת לישון"]}, {"id": "t3", "text": "אחרי הרגעה, חוזר/ת לישון תוך זמן קצר", "staff": "חוזר/ת לישון אחרי הרגעה", "scale": ["עדיין ער/ה זמן ארוך", "חוזר/ת לישון עם מבוגר צמוד", "חוזר/ת לישון אחרי הרגעה קצרה", "חוזר/ת לישון עם הכלי", "חוזר/ת לישון לבד"]}, {"id": "t4", "text": "בבוקר, מספר/ת מה עזר לו/ה בלילה", "staff": "מספר/ת בבוקר מה עזר", "scale": ["עדיין לא מדבר/ת על הלילה", "מקשיב/ה כשמבוגר מזכיר", "אומר/ת מילה על מה עזר", "מספר/ת מיוזמתו/ה", "מציע/ה מה לנסות בלילה הבא"]}, {"id": "t5", "text": "נכנס/ת למיטה בערב בלי סערה ארוכה", "staff": "נכנס/ת למיטה בלי סערה", "scale": ["עדיין סוער/ת זמן ארוך", "נרגע/ת עם מבוגר לאט", "נרגע/ת עם השגרה", "נכנס/ת בשקט ברוב הערבים", "נכנס/ת בשקט גם אחרי יום קשה"]}], "interventions": [{"id": "i1", "name": "לעשות בדיקת ביטחון", "what": "סיבוב קצר יחד לפני השינה: הדלת, החלון, איפה המבוגר בלילה ואיך קוראים לו.", "why": "מי שבדק בעצמו מרגיש בטוח יותר.", "freq": "כל ערב", "approach": "ARC", "targets": ["t1", "t5"], "sentences": ["בוא/י נבדוק ביחד", "הנה איפה המדריך/ה בלילה", "ככה קוראים לנו"]}, {"id": "i2", "name": "לענות להתעוררות במשפט קבוע", "what": "מגיעים מהר, בגובה העיניים, קול נמוך, אותו משפט כל פעם, בלי חקירה.", "why": "תגובה קבועה מורידה את הפחד מהר.", "freq": "בכל התעוררות", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["אני פה, אתה/את בטוח/ה", "זה היה חלום, עכשיו אתה/את פה", "נושמים ביחד"], "avoid": "לא לשאול על פרטי הסיוט"}, {"id": "i3", "name": "לבנות כלי לילה", "what": "בוחרים יחד כלי לרגע של פחד: פנס קטן, חפץ, נשימה, מוזיקה שקטה.", "why": "כלי משלי נותן שליטה ברגע מפחיד.", "freq": "בתחילת המטרה ולפי הצורך", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["מה יעזור לך כשמתעוררים?", "הפנס פה לידך", "נשתמש בו הלילה?"]}, {"id": "i4", "name": "לשבח בבוקר בלי לשאול על החלום", "what": "בבוקר משבחים שקרא/ה למבוגר או השתמש/ה בכלי, בלי להיכנס לתוכן הסיוט.", "why": "שבח על ההתמודדות מחזק את מה שעבד.", "freq": "בבוקר אחרי לילה קשה", "approach": "TBRI", "targets": ["t4"], "sentences": ["קראת לי בלילה, וזה בדיוק נכון", "מה עזר לך?", "בלילה הבא ננסה שוב ככה"]}, {"id": "i5", "name": "להקשיב קצר ולהעביר למטפלת (בהנחיית המטפלת)", "what": "אם רוצה לספר על הסיוט, מקשיבים בקצרה ומעבירים למטפלת. אם עולה תוכן של פגיעה, פועלים לפי הנוהל.", "why": "עבודה על תוכן הסיוט היא חלק מהטיפול.", "freq": "כשמספר/ת", "approach": "TF-CBT", "targets": ["t4"], "sentences": ["תודה שסיפרת לי", "נספר גם למטפלת, היא יודעת לעזור", "עכשיו אתה/את בטוח/ה"], "avoid": "לא לבקש לצייר או ''לשנות את החלום'' בלי הנחיה"}, {"id": "i6", "name": "לשמור על ערב שקט", "what": "בשעה שלפני השינה: אור עמום, פעילות רגועה, בלי מסכים מלהיבים או מפחידים.", "why": "ערב שקט מכין את הגוף לשינה.", "freq": "כל ערב", "approach": "NMT", "targets": ["t5"], "sentences": ["עכשיו זמן שקט", "נקרא משהו רגוע", "עוד מעט לישון"]}, {"id": "i7", "name": "לרשום לילות קשים", "what": "מתעדים בקצרה מתי התעורר/ה ומה עזר, ומעבירים למטפלת כדי לזהות דפוס.", "why": "דפוס שרואים מאפשר לעזור בזמן.", "freq": "אחרי לילה קשה", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["איך הלילה?", "אני רושם/ת מה עזר", "ככה נדע מה לעשות"]}, {"id": "i8", "name": "לומר ''זה בסדר להתעורר''", "what": "מסבירים בפשטות שהרבה ילדים מתעוררים בפחד, ושאף אחד לא כועס על זה.", "why": "בלי בושה, קל יותר לקרוא לעזרה.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t2", "t4"], "sentences": ["הרבה ילדים מתעוררים בפחד", "אף אחד לא כועס", "תמיד אפשר לקרוא לנו"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תמיד יהיה אוכל', 'להרגיש בטוח/ה שיהיה אוכל, בלי צורך לאגור ולהסתיר', array['שינה ואכילה']::text[], 'שינה ואכילה', array['TBRI', 'ARC']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לחפש באופן עונשי, לא להאשים ולא לקחת אוכל כעונש", "strengths": ["אמון", "אחריות", "עזרה לאחרים"], "skills": ["הבעת צורך"], "main": "6-9", "also": ["2-5", "10-12"], "evidence": {"level": "derived", "note": "אגירת מזון מתוארת בקרב ילדים שחוו הזנחה; עקרונות האכלה מותאמת טראומה הם עמדה מקצועית מקובלת ולא תוצאה של ניסויים. בסידור חוץ־ביתי זו התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "כשרעב/ה בין ארוחות, מבקש/ת במקום לקחת בסתר", "staff": "מבקש/ת אוכל במקום לקחת בסתר", "scale": ["עדיין לוקח/ת ומסתיר/ה", "מבקש/ת כשמבוגר מציע", "מבקש/ת לפעמים", "מבקש/ת ברוב הפעמים", "מבקש/ת ויודע/ת שתמיד יש"]}, {"id": "t2", "text": "משתמש/ת בקופסת האוכל האישית במקום לאגור בחדר", "staff": "משתמש/ת בקופסה שלו/ה", "scale": ["עדיין אוגר/ת הרבה בחדר", "אוגר/ת וגם משתמש/ת בקופסה", "שם/ה בקופסה עם תזכורת", "משתמש/ת בעיקר בקופסה", "כמעט לא אוגר/ת"]}, {"id": "t3", "text": "בארוחה, אוכל/ת בקצב רגוע יותר", "staff": "אוכל/ת בקצב רגוע", "scale": ["עדיין אוכל/ת מהר מאוד או עד כאב", "מאט/ה כשמבוגר מזכיר", "מאט/ה לבד לפעמים", "אוכל/ת ברוגע ברוב הארוחות", "אוכל/ת ברוגע גם כשיש מעט"]}, {"id": "t4", "text": "מצביע/ה על סולם הרעב לפני ואחרי האוכל", "staff": "מראה כמה רעב/ה בסולם", "scale": ["עדיין לא מבחין/ה", "מצביע/ה עם עזרה", "מצביע/ה לבד לפעמים", "מצביע/ה ומבקש/ת לפיו", "אומר/ת לבד אם רעב/ה או שבע/ה"]}, {"id": "t5", "text": "עוזר/ת בתפקיד קבוע סביב האוכל (הגשה, סידור)", "staff": "עוזר/ת בתפקיד סביב האוכל", "scale": ["עדיין לא משתתף/ת", "עוזר/ת עם מבוגר", "עוזר/ת עם תזכורת", "עוזר/ת לבד", "עוזר/ת ומציע/ה רעיונות"]}], "interventions": [{"id": "i1", "name": "לתת קופסת אוכל אישית (בהנחיית המטפלת)", "what": "קופסה עם השם שלו/ה וחטיפים שלא מתקלקלים, ממלאים אותה שוב באופן קבוע.", "why": "אוכל שתמיד שם מוריד את הצורך לאגור.", "freq": "באופן קבוע", "approach": "TBRI", "targets": ["t2", "t1"], "sentences": ["הקופסה הזו שלך", "אפשר לקחת ממנה כשרעב/ה", "נמלא אותה שוב"], "avoid": "לא לרוקן או לקחת את הקופסה כעונש"}, {"id": "i2", "name": "לפנות אוכל מוסתר בלי להאשים", "what": "כשמוצאים אוכל מוסתר, מוציאים בעדינות רק מה שעלול להתקלקל, ומזכירים שיש עוד.", "why": "בלי אשמה, אין צורך להסתיר.", "freq": "כשמוצאים", "approach": "TBRI", "targets": ["t2"], "sentences": ["את זה נזרוק כי זה מתקלקל", "יש לך את הקופסה", "תמיד יש עוד אוכל"], "avoid": "לא לחפש בחדר באופן עונשי ולא לשאול ''למה גנבת''"}, {"id": "i3", "name": "להראות שיש עוד", "what": "בארוחה מראים את הסיר והלחם, ואומרים שאפשר לקבל עוד.", "why": "לראות שיש מספיק מרגיע את הפחד שלא יהיה אוכל.", "freq": "בכל ארוחה", "approach": "TBRI", "targets": ["t3"], "sentences": ["תראה/תראי, יש עוד בסיר", "אפשר לקבל עוד", "לא ייגמר"]}, {"id": "i4", "name": "לתלות לוח ''מתי אוכלים''", "what": "לוח ברור עם שעות הארוחות והביניים, ובמיוחד מה יש בערב ובלילה.", "why": "לדעת מתי האוכל הבא מוריד את הדאגה.", "freq": "כל יום", "approach": "ARC", "targets": ["t1"], "sentences": ["בעוד שעה יש ביניים", "בערב יש עוד ארוחה", "בוא/י נסתכל בלוח"]}, {"id": "i5", "name": "להשתמש בסולם רעב פשוט", "what": "כרטיס עם 3 תמונות (בטן ריקה, קצת, מלאה), מצביעים לפני האוכל ואחריו.", "why": "סולם עוזר להבחין בין רעב לדאגה.", "freq": "בארוחות", "approach": "ARC", "targets": ["t4", "t3"], "sentences": ["איפה הבטן עכשיו?", "ואחרי האוכל?", "יפה שבדקת"]}, {"id": "i6", "name": "לתת תפקיד באוכל", "what": "תפקיד קבוע בהגשה, בסידור השולחן או בקנייה קטנה.", "why": "מעורבות באוכל נותנת תחושת שליטה.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t5"], "sentences": ["היום אתה/את מגיש/ה את הלחם", "תודה, עזרת", "בזכותך כולם אכלו"]}, {"id": "i7", "name": "לאכול לאט ביחד", "what": "מבוגר יושב לידו/ה, אוכל לאט ומדבר בנעימות, בלי להעיר על הקצב.", "why": "ליד מבוגר רגוע, גם הגוף מאט.", "freq": "בארוחות", "approach": "TBRI", "targets": ["t3"], "sentences": ["יש לנו זמן", "טעים לך?", "אפשר לנוח רגע ולהמשיך"]}, {"id": "i8", "name": "לדווח על סימני אזהרה", "what": "מדווחים למטפלת או לצוות הרפואי על אגירה שלא פוחתת, אכילה עד כאב או אכילה של דברים שאינם אוכל.", "why": "קושי שנמשך צריך בירור מקצועי.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["איך הבטן מרגישה?", "אני רואה שזה עוד קשה", "נבקש עזרה מהאחות ומהמטפלת"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'בוקר בלי בושה', 'להתמודד עם הרטבה בלילה בכבוד ובפרטיות', array['שינה ואכילה']::text[], 'שינה ואכילה', array['CPS', 'TBRI', 'ARC', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעניש, לא לתגמל על לילה יבש, לא להעיר בלילה בלי הנחיה, ולא לדבר על זה ליד ילדים", "strengths": ["אומץ", "אחריות", "עצמאות"], "skills": ["עצמאות"], "main": "10-12", "also": ["6-9", "13-15"], "evidence": {"level": "derived", "note": "ההנחיות הרפואיות להרטבה (כמו NICE) ממליצות לא להעניש ולא לתגמל על לילה יבש, ולבדוק סיבה רפואית. ההתאמה לצוות במסגרת חוץ־ביתית היא יישומית. כל הטיפול הרפואי בתיאום עם הצוות הרפואי."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "בבוקר אחרי הרטבה, מטפל/ת לפי התוכנית הקבועה (מצעים, מקלחת) בלי להסתיר", "staff": "מטפל/ת בבוקר לפי התוכנית", "scale": ["עדיין מסתיר/ה או לא קם/ה", "מטפל/ת עם מבוגר צמוד", "מטפל/ת עם תזכורת שקטה", "מטפל/ת לבד ברוב הבקרים", "מטפל/ת לבד ובשקט"]}, {"id": "t2", "text": "מספר/ת למבוגר מוכר בשקט כשצריך משהו (מצעים, בגדים)", "staff": "מבקש/ת בשקט מה שצריך", "scale": ["עדיין לא מבקש/ת", "מבקש/ת כשמבוגר שואל", "מבקש/ת בסימן שסיכמנו", "מבקש/ת מיוזמתו/ה", "מבקש/ת גם מכל מבוגר אחר"]}, {"id": "t3", "text": "כשילד מקניט, משתמש/ת במשפט ההגנה או פונה למבוגר", "staff": "משתמש/ת במשפט הגנה מול הקנטה", "scale": ["עדיין מתפרץ/ת או בורח/ת", "נרגע/ת עם מבוגר", "פונה למבוגר", "אומר/ת את המשפט ופונה", "אומר/ת את המשפט ונשאר/ת רגוע/ה"]}, {"id": "t4", "text": "משתתף/ת בטיול או בלינה מחוץ למרכז עם תוכנית מוכנה", "staff": "יוצא/ת ללינה עם תוכנית", "scale": ["עדיין מסרב/ת לצאת ללינה", "מתלבט/ת", "יוצא/ת עם הכנה רבה", "יוצא/ת עם תוכנית קצרה", "יוצא/ת בביטחון"]}, {"id": "t5", "text": "מדבר/ת על ההרטבה בלי בושה עם המבוגר המוכר", "staff": "מדבר/ת על זה בלי בושה", "scale": ["עדיין לא מוכן/ה לדבר", "מקשיב/ה כשמבוגר מדבר", "אומר/ת מילה", "מדבר/ת ברוגע", "מציע/ה מה יעזור לו/ה"]}], "interventions": [{"id": "i1", "name": "לסכם תוכנית בוקר בשקט", "what": "בשיחה פרטית מסכמים: איפה שמים מצעים, מתי מתקלחים, מי עוזר, ומה הסימן לבקשת עזרה.", "why": "תוכנית ברורה מורידה בושה ובלגן.", "freq": "בתחילת המטרה", "approach": "CPS", "targets": ["t1", "t2"], "sentences": ["בוא/י נתכנן את הבוקר בשקט", "רק אנחנו יודעים את הסימן", "מה יעזור לך?"]}, {"id": "i2", "name": "להכין הגנה מעשית", "what": "מגן מזרן, בגדים ומצעים להחלפה ליד המיטה, ושק כביסה פרטי, בתיאום עם הצוות הרפואי.", "why": "כשהכל מוכן, הבוקר קצר ופרטי.", "freq": "תמיד", "approach": "TBRI", "targets": ["t1"], "sentences": ["הכל מוכן ליד המיטה", "הילדים האחרים לא צריכים לדעת", "אתה/את מסתדר/ת"]}, {"id": "i3", "name": "לא להעניש ולא לתגמל", "what": "לא מענישים, לא מבטלים פעילות ולא נותנים פרס על לילה יבש, כי זה לא בשליטה.", "why": "מה שלא בשליטה לא נפתר בעונש או בפרס.", "freq": "תמיד", "approach": "TBRI", "targets": ["t5"], "sentences": ["זה לא באשמתך", "הגוף עוד לומד", "אנחנו איתך"], "avoid": "לא להעיר בלילה ולא להגביל שתייה בלי הנחיה רפואית"}, {"id": "i4", "name": "לתרגל משפט הגנה", "what": "מתרגלים משפט קצר מול הקנטה, והצוות עוצר כל הקנטה מיד, בלי לומר במה מדובר.", "why": "משפט מוכן והגנה של הצוות שומרים על הכבוד.", "freq": "בזמן רגוע, ובכל הקנטה", "approach": "ARC", "targets": ["t3"], "sentences": ["אפשר לומר: זה לא עניינך", "אצלנו לא צוחקים על גוף", "אני עוצר/ת את זה עכשיו"]}, {"id": "i5", "name": "לתכנן לינה בחוץ", "what": "לפני טיול או לינה מתכננים בשקט: מה לוקחים, איפה מחליפים, מי המבוגר שיודע (בתיאום עם המטפלת).", "why": "תוכנית מראש מאפשרת לא לוותר על חוויות.", "freq": "לפני כל לינה", "approach": "CPS", "targets": ["t4"], "sentences": ["בוא/י נתכנן את הטיול", "רק המבוגר שמלווה את הטיול יודע", "יש לך תוכנית"]}, {"id": "i6", "name": "לדבר על זה בפשטות", "what": "מסבירים במילים פשוטות שהרטבה קורה להרבה ילדים בגיל הזה ושהגוף לומד.", "why": "הסבר פשוט מוריד בושה.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["זה קורה להרבה ילדים בגיל שלך", "זה לא אומר שמשהו לא בסדר בך", "אפשר לשאול אותי הכל"]}, {"id": "i7", "name": "לשמור על פרטיות מול הקבוצה", "what": "לא מדברים על זה ליד ילדים, והכביסה נעשית בלי לחשוף.", "why": "פרטיות שומרת על המקום שלו/ה בקבוצה.", "freq": "תמיד", "approach": "TBRI", "targets": ["t3", "t1"], "sentences": ["זה נשאר בינינו ובין הצוות", "הילדים האחרים לא יודעים", "אני שומר/ת על זה"]}, {"id": "i8", "name": "לבדוק עם הצוות הרפואי", "what": "הרטבה חדשה, כאב או שינוי פתאומי מעבירים לצוות הרפואי ולמטפלת.", "why": "לפעמים יש סיבה גופנית שאפשר לטפל בה.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t5"], "sentences": ["נבדוק עם האחות שהכל בסדר", "זו בדיקה רגילה", "תגיד/י לי אם משהו כואב"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'אוכל, רגש ואני', 'להבין מתי אני אוכל/ת מרעב ומתי מרגש, ולנהל אוכל בעצמי', array['שינה ואכילה']::text[], 'שינה ואכילה', array['DDP/PACE', 'ARC', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעיר על משקל או גוף, לא להשוות, ולא לנעול אוכל כעונש", "strengths": ["כנות", "עצמאות", "אחריות"], "skills": ["ויסות עצמי"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "נגזר מעקרונות אכילה קשובה ומניעת הפרעות אכילה אצל מתבגרים (בלי הערות על משקל), ומ-ARC. סימנים להפרעת אכילה מועברים לצוות המקצועי בלבד. במסגרות חוץ־ביתיות זו התאמה יישומית."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "בשיחה, מבחין/ה בין רעב לבין אכילה מרגש (שעמום, כעס, עצב)", "staff": "מבחין/ה בין רעב לרגש", "scale": ["עדיין לא מבחין/ה", "מקשיב/ה כשמבוגר שואל", "מבחין/ה בדיעבד", "מבחין/ה לפעמים בזמן", "מבחין/ה ובוחר/ת מה לעשות"]}, {"id": "t2", "text": "מגיע/ה לרוב הארוחות הקבועות", "staff": "מגיע/ה לארוחות", "scale": ["עדיין מדלג/ת על הרבה ארוחות", "מגיע/ה כשמזכירים", "מגיע/ה לחלק מהארוחות", "מגיע/ה לרובן", "מגיע/ה גם בימים קשים"]}, {"id": "t3", "text": "מכין/ה ארוחה או נשנוש פשוט ומזין בעצמו/ה", "staff": "מכין/ה לעצמו/ה אוכל פשוט", "scale": ["עדיין לא מכין/ה", "מכין/ה עם מבוגר", "מכין/ה עם הדרכה", "מכין/ה לבד", "מתכנן/ת ומכין/ה לבד"]}, {"id": "t4", "text": "כשקשה, משתמש/ת בדרך הרגעה נוספת לצד או במקום אוכל", "staff": "מוצא/ת עוד דרך להירגע מלבד אוכל", "scale": ["עדיין רק אוכל", "מנסה כשמבוגר מציע", "מנסה לפעמים", "בוחר/ת דרך אחרת לפעמים", "יש לו/ה כמה דרכים"]}, {"id": "t5", "text": "אחרי אכילה מרגש, מדבר/ת על זה בלי להאשים את עצמו/ה", "staff": "לא מאשים/ה את עצמו/ה אחרי אכילה", "scale": ["עדיין מאשים/ה את עצמו/ה קשות", "שותק/ת אחרי אכילה כזו", "אומר/ת משפט פחות קשה", "אומר/ת מה הרגיש/ה לפני", "אומר/ת מה יעזור בפעם הבאה"]}], "interventions": [{"id": "i1", "name": "לדבר על אוכל בלי משקל ובלי שיפוט", "what": "מדברים על מה האוכל עושה בשבילו/ה, ולא על כמה אכל/ה או איך הוא/היא נראה/נראית.", "why": "שיחה בלי שיפוט פותחת, ביקורת סוגרת.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t1", "t5"], "sentences": ["מה האוכל עושה לך כשקשה?", "אין פה תשובה נכונה", "תודה שסיפרת"], "avoid": "לא להעיר על משקל ולא להשוות"}, {"id": "i2", "name": "לשאול ''רעב או קשה?''", "what": "משפט קבוע ועדין, בלי לעצור את האוכל, ומציעים גם משהו אחר אם רוצה.", "why": "שאלה עדינה עוזרת לשים לב.", "freq": "בהזדמנות", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["רעב או קשה?", "אפשר גם וגם", "רוצה גם לדבר?"]}, {"id": "i3", "name": "להכין יחד אוכל מזין", "what": "מכינים יחד נשנוש או ארוחה פשוטה ומזינה לרגע שבו רעבים.", "why": "כשיש אוכל טוב בהישג יד, פחות אוכלים מתוך רגש.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t3"], "sentences": ["מה נכין עכשיו?", "זה ממלא לאורך זמן", "יצא טעים"]}, {"id": "i4", "name": "לשמור מקום בארוחה", "what": "ארוחות קבועות נשמרות גם כשמסרב/ת לבוא, ומשאירים צלחת בלי ויכוח.", "why": "שולחן שתמיד מחכה הוא מסר של שייכות.", "freq": "בכל ארוחה", "approach": "TBRI", "targets": ["t2"], "sentences": ["שמרתי לך צלחת", "המקום שלך פה", "אפשר לבוא מתי שתרצה/תרצי"]}, {"id": "i5", "name": "לבנות עוד דרכי הרגעה", "what": "מוצאים יחד 2-3 דרכים נוספות לרגע קשה: הליכה, מוזיקה, שיחה, מקלחת.", "why": "עוד כלים נותנים בחירה.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t4"], "sentences": ["מה עוד עוזר לך כשקשה?", "ננסה הפעם הליכה?", "איך היה?"]}, {"id": "i6", "name": "לא להעיר על גוף", "what": "הצוות לא מעיר על גוף, משקל או מנות, ועוצר הערות כאלה מילדים.", "why": "הערות על גוף מגבירות סיכון לאכילה לא בריאה.", "freq": "תמיד", "approach": "TBRI", "targets": ["t5"], "sentences": ["אצלנו לא מעירים על גוף", "הגוף שלך שלך", "בוא/י נדבר על משהו אחר"]}, {"id": "i7", "name": "לדווח על סימני אזהרה", "what": "דילוג חוזר על ארוחות, עיסוק רב במשקל, הקאות או אכילה בסתר מדווחים למטפלת ולצוות הרפואי בלבד.", "why": "הפרעת אכילה דורשת טיפול מקצועי מוקדם.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t2", "t5"], "sentences": ["שמתי לב שקשה לך עם האוכל", "אני רוצה שתקבל/י עזרה", "נדבר עם המטפלת ביחד"], "avoid": "לא לשכנע או לעקוב צמוד בלי הנחיה"}, {"id": "i8", "name": "לשבח בחירה טובה", "what": "כשבחר/ה דרך הרגעה אחרת או הכין/ה אוכל לבד, אומרים בקצרה ובפרטיות.", "why": "חיזוק פרטי מכבד בני נוער.", "freq": "בהזדמנות", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["ראיתי שהכנת לבד", "בחרת דרך חדשה להירגע", "זה לא פשוט"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'ידיים שומרות', 'להראות כעס בלי להכות, לנשוך או לזרוק', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['TBRI', 'ARC', 'ויסות חושי']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לאחוז בכוח, לא לנעול, לא להשאיר לבד ולא להעניש אחר כך", "strengths": ["שליטה עצמית", "אמון", "בקשת עזרה"], "skills": ["ויסות"], "main": "2-5", "also": [], "evidence": {"level": "derived", "note": "נגזר מוויסות משותף (ARC, TBRI) ומעבודה עם התפרצויות בגיל הרך. גישות להורים כמו PCIT נבדקו, אך ההתאמה למדריכים במשמרות היא יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "ברגע של כעס, משתמש/ת בתחליף הבטוח (כרית, רקיעה, לחיצה) במקום להכות", "staff": "משתמש/ת בתחליף במקום להכות", "scale": ["עדיין מכה, נושך/ת או זורק/ת", "נעצר/ת כשמבוגר מתקרב", "משתמש/ת בתחליף עם עזרה", "משתמש/ת בתחליף לבד לפעמים", "משתמש/ת בתחליף ברוב הפעמים"]}, {"id": "t2", "text": "כשמבוגר מזהה סימן מוקדם, מצטרף/ת לפינת ההרגעה איתו", "staff": "בא/ה עם מבוגר לפינה כשמתחיל", "scale": ["עדיין מתפרץ/ת לפני שאפשר לעזור", "נרגע/ת אחרי שהתפרץ/ה", "מצטרף/ת לפינה עם מבוגר", "מצטרף/ת לפני שמתפרץ/ת", "הולך/ת לפינה מיוזמתו/ה"]}, {"id": "t3", "text": "אחרי התפרצות, נרגע/ת תוך זמן קצר יותר", "staff": "נרגע/ת מהר יותר", "scale": ["עדיין סוער/ת זמן ארוך", "נרגע/ת עם מבוגר לאט", "נרגע/ת עם מבוגר מהר", "נרגע/ת עם הכלי שלו/ה", "נרגע/ת מהר כמעט לבד"]}, {"id": "t4", "text": "כשרגוע/ה, משתתף/ת בתיקון קטן (עזרה, מגע מוסכם, ציור לחבר)", "staff": "עושה תיקון קטן כשרגוע/ה", "scale": ["עדיין לא משתתף/ת", "מסתכל/ת כשמבוגר מתקן", "עושה תיקון עם מבוגר", "בוחר/ת תיקון", "מציע/ה תיקון בעצמו/ה"]}, {"id": "t5", "text": "אומר/ת או מראה שהוא/היא כועס/ת במילה או בסימן", "staff": "אומר/ת ''אני כועס/ת'' במילה או סימן", "scale": ["עדיין רק דרך הגוף", "מסכים/ה כשמבוגר נותן שם", "מראה בסימן שלמד/ה", "אומר/ת במילה", "אומר/ת מה הכעיס"]}], "interventions": [{"id": "i1", "name": "לשמור על בטיחות קודם", "what": "מרחיקים בשקט ילדים אחרים וחפצים מסוכנים, נותנים מרחב ונשארים קרוב ורגועים.", "why": "קודם כולם בטוחים, אחר כך מרגיעים.", "freq": "בכל התפרצות", "approach": "TBRI", "targets": ["t3"], "sentences": ["אני שומר/ת שכולם בטוחים", "אני כאן", "אני לא הולך/ת"], "avoid": "לא לאחוז, לא לנעול חדר ולא להשאיר לבד"}, {"id": "i2", "name": "לדבר מעט, בקול נמוך", "what": "משפט אחד שחוזר, בלי הסברים, בלי ''למה'' ובלי איומים.", "why": "בסערה, מעט מילים נשמעות יותר.", "freq": "בכל התפרצות", "approach": "ARC", "targets": ["t3"], "sentences": ["אני כאן, אתה/את בטוח/ה", "הידיים שומרות", "נושמים ביחד"]}, {"id": "i3", "name": "לתרגל תחליף בטוח", "what": "בזמן רגוע מתרגלים תחליף קבוע לכעס: להכות בכרית, לרקוע, ללחוץ כדור.", "why": "מה שתורגל ברוגע זמין ברגע הכעס.", "freq": "באופן קבוע", "approach": "ויסות חושי", "targets": ["t1"], "sentences": ["כשכועסים, מכים בכרית", "בוא/י נתאמן", "יפה, השתמשת בכרית"]}, {"id": "i4", "name": "לזהות סימן מוקדם (בהנחיית המטפלת)", "what": "המטפלת רושמת בכרטיס את הסימנים המוקדמים של הילד/ה, והמבוגר מתקרב ומציע עזרה לפני הפיצוץ.", "why": "עזרה מוקדמת חוסכת התפרצות.", "freq": "לאורך היום", "approach": "ARC", "targets": ["t2"], "sentences": ["אני רואה שזה מתחיל להיות קשה", "בוא/י נלך לפינה ביחד", "אני איתך"]}, {"id": "i5", "name": "ללכת לפינת ההרגעה ביחד", "what": "פינה רכה שהמבוגר נמצא בה עם הילד/ה, ולא מקום של עונש.", "why": "ילד נרגע ליד מבוגר רגוע.", "freq": "לפי הצורך", "approach": "ויסות חושי", "targets": ["t2", "t3"], "sentences": ["הולכים לפינה ביחד", "פה נרגעים", "נחזור כשתהיה/תהיי מוכן/ה"], "avoid": "לא לשלוח לבד לפינה"}, {"id": "i6", "name": "לתקן ביחד אחרי", "what": "כשרגוע/ה: מילה חמה, שם קצר למה שקרה, ותיקון קטן ביחד.", "why": "תיקון מלמד שאפשר לחזור לקשר.", "freq": "אחרי כל התפרצות", "approach": "TBRI", "targets": ["t4"], "sentences": ["הכעס היה גדול", "בוא/י נעזור לחבר לבנות שוב", "אנחנו בסדר"], "avoid": "לא לחייב סליחה ולא להרצות"}, {"id": "i7", "name": "לתת מילה לכעס", "what": "בזמן רגוע ובזמן כעס מלמדים מילה או סימן לכעס.", "why": "מה שאפשר לומר, לא צריך להכות.", "freq": "לאורך היום", "approach": "ARC", "targets": ["t5"], "sentences": ["אתה/את כועס/ת", "אפשר לומר: אני כועס/ת", "תראה/תראי לי בסימן"]}, {"id": "i8", "name": "לרשום ולהעביר למטפלת", "what": "אחרי אירוע משמעותי רושמים בקצרה מה היה לפני, מה עזר ומה לא, ומעבירים למטפלת.", "why": "רישום עוזר למצוא מה מקפיץ ומה מרגיע.", "freq": "אחרי אירוע", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["איך אתה/את עכשיו?", "אני רושם/ת מה עזר", "ככה נדע לעזור"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', '''לא'' רגוע וברור', 'לקבל גבול בלי מאבק כוח', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['סמכות חדשה', 'DDP/PACE', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לאיים, לא לספור באיום, ולא להציב גבול שמונע אוכל, שינה, חפץ אהוב או קשר", "strengths": ["גמישות", "שיתוף פעולה", "אמון"], "skills": ["גמישות"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "נגזר מעקרונות סמכות חדשה (נוכחות בלי מאבק), CPS ו-TBRI. בגיל הרך ובמסגרת חוץ־ביתית זו התאמה יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשאומרים לא ומציעים חלופה, עובר/ת לחלופה", "staff": "עובר/ת לחלופה אחרי ''לא''", "scale": ["עדיין מתפרץ/ת בכל ''לא''", "עובר/ת אחרי זמן ועזרה", "עובר/ת עם עזרה קצרה", "עובר/ת לבד ברוב הפעמים", "מציע/ה חלופה בעצמו/ה"]}, {"id": "t2", "text": "כשמאוכזב/ת, נרגע/ת כשמבוגר נותן שם לרגש", "staff": "נרגע/ת כשנותנים שם לאכזבה", "scale": ["עדיין לא נרגע/ת", "נרגע/ת לאט עם מבוגר", "נרגע/ת כשנותנים שם", "נרגע/ת מהר", "אומר/ת בעצמו/ה שהוא/היא מאוכזב/ת"]}, {"id": "t3", "text": "אחרי גבול, חוזר/ת לשחק עם המבוגר שהציב אותו", "staff": "חוזר/ת לקשר אחרי גבול", "scale": ["עדיין נאבק/ת בכל מעבר", "עובר/ת עם הרבה עזרה", "עובר/ת עם שיר או טיימר", "עובר/ת עם תזכורת", "עובר/ת לבד"]}, {"id": "t4", "text": "בבעיה שחוזרת, משתף/ת פעולה בפתרון שמצאנו יחד", "staff": "משתף/ת פעולה בפתרון שמצאנו", "scale": ["עדיין מסרב/ת", "מנסה כשמבוגר עוזר", "מנסה את הפתרון", "משתמש/ת בפתרון", "מזכיר/ה את הפתרון בעצמו/ה"]}, {"id": "t5", "text": "מקבל/ת גבול בטיחותי מיד (כביש, אש, גובה)", "staff": "מקבל/ת גבול בטיחותי מיד", "scale": ["עדיין לא עוצר/ת", "עוצר/ת כשמבוגר מחזיק", "עוצר/ת אחרי מילה", "עוצר/ת מיד", "מזכיר/ה לחבר"]}], "interventions": [{"id": "i1", "name": "לומר גבול במשפט אחד עם חלופה", "what": "אומרים מה כן ולא רק מה לא, בקול רגוע ובגובה העיניים.", "why": "חלופה ברורה מורידה מאבק.", "freq": "בכל גבול", "approach": "סמכות חדשה", "targets": ["t1"], "sentences": ["על הספה לא קופצים, על המזרן כן", "המספריים לא, הנה עפרון", "את זה לא, ואת זה כן"], "avoid": "לא להרצות, לא לאיים ולא לספור ''אחת, שתיים''"}, {"id": "i2", "name": "לבחור מעט גבולות", "what": "מתעקשים רק על גבולות בטיחות. על השאר אפשר לוותר או לדחות.", "why": "פחות מאבקים משאירים כוח לגבולות החשובים.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t5", "t1"], "sentences": ["בסדר, את זה אפשר", "את זה לא, כי זה מסוכן", "אני שומר/ת עליך"]}, {"id": "i3", "name": "לחזור לקשר אחרי גבול", "what": "אחרי שהגבול נגמר, המבוגר חוזר לשחק איתו/ה, בחום ובלי להזכיר את מה שהיה.", "why": "חזרה לקשר מראה שגבול לא מנתק.", "freq": "אחרי כל גבול", "approach": "סמכות חדשה", "targets": ["t3"], "sentences": ["אני עדיין כאן איתך", "רוצה לבנות איתי מגדל?", "הגבול נגמר, אנחנו בסדר"]}, {"id": "i4", "name": "לתת שם לאכזבה", "what": "לא מבטלים את הגבול, אבל מכירים בתסכול.", "why": "רגש שמכירים בו נרגע מהר יותר.", "freq": "בכל אכזבה", "approach": "DDP/PACE", "targets": ["t2"], "sentences": ["אתה/את מאוכזב/ת, רצית עוד", "זה מבאס", "אני כאן איתך"]}, {"id": "i5", "name": "לבדוק מה עומד מאחורי הסירוב", "what": "בבעיה שחוזרת (נעליים, מקלחת) מחפשים סיבה: חושים, פחד, עייפות, ומנסים פתרון יחד.", "why": "סירוב חוזר הוא לרוב בעיה שאפשר לפתור.", "freq": "בבעיה שחוזרת", "approach": "CPS", "targets": ["t4"], "sentences": ["מה קשה בנעליים?", "בוא/י ננסה אחרת", "עבד!"]}, {"id": "i6", "name": "לא להציב גבול על צרכים", "what": "לעולם לא מציבים גבול שמונע אוכל, שינה, חפץ אהוב, קשר עם מבוגר או קשר עם המשפחה.", "why": "גבול על צורך בסיסי מערער את הביטחון.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2"], "sentences": ["אוכל מקבלים תמיד, גם כשכועסים", "הדובי נשאר איתך", "גם כשכועסים, אני כאן"]}, {"id": "i7", "name": "לעצור מיד בגבול בטיחות", "what": "בגבול בטיחות עוצרים מיד, בגוף רגוע, ומסבירים במילה אחת.", "why": "בטיחות קודמת לשיחה.", "freq": "בכל סכנה", "approach": "סמכות חדשה", "targets": ["t5"], "sentences": ["עצור/י, כביש", "זה חם, לא נוגעים", "עכשיו בטוח"]}, {"id": "i8", "name": "לשבח שיתוף פעולה", "what": "כשקיבל/ה גבול או עבר/ה לחלופה, אומרים את זה מיד ובקצרה.", "why": "מה שרואים ומשבחים, חוזר.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t1", "t3"], "sentences": ["עברת למזרן, יופי", "זה היה קשה, והצלחת", "תודה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'כללי גוף ופרטיות (בהנחיית המטפלת)', 'ללמוד כללי גוף ופרטיות, כשיש התנהגות מינית שלא מתאימה לגיל', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['סמכות חדשה', 'ARC', 'מעגל הביטחון', 'TBRI', 'ויסות חושי']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא לצעוק, לא לבייש, לא לחקור, ולא לדבר על זה מול ילדים. דיווח לפי הנוהל תמיד", "strengths": ["אמון", "שייכות", "בקשת עזרה"], "skills": ["גבולות גוף"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "טיפול ממוקד בהתנהגות מינית לא מותאמת גיל (PSB-CBT) נבדק ונמצא יעיל, והוא נעשה בידי המטפלת. התפקיד של המדריכים כאן (עצירה רגועה, תיעוד ודיווח, השגחה וכללי בית) הוא עקרון בטיחות ולא התערבות שנבדקה בנפרד."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "מכיר/ה ואומר/ת את כללי הגוף של המקום (ידיים לעצמי, בגדים בחדר משותף, דלת סגורה בשירותים)", "staff": "יודע/ת את כללי הגוף", "scale": ["עדיין לא מכיר/ה", "חוזר/ת על כלל עם מבוגר", "אומר/ת כללים כששואלים", "אומר/ת ושומר/ת ברוב הזמן", "שומר/ת גם בלי תזכורת"]}, {"id": "t2", "text": "כשמבוגר עוצר, מפסיק/ה ועובר/ת לפעילות אחרת", "staff": "מפסיק/ה כשעוצרים ועובר/ת לפעילות", "scale": ["עדיין ממשיך/ה", "מפסיק/ה עם מבוגר צמוד", "מפסיק/ה במילה", "מפסיק/ה ועובר/ת לבד", "כמעט לא צריך/ה עצירה"]}, {"id": "t3", "text": "יודע/ת למי מהמבוגרים אפשר לספר כשמשהו מבלבל או מפחיד", "staff": "יודע/ת למי לספר", "scale": ["עדיין לא יודע/ת", "מזכיר/ה כשמבוגר שואל", "אומר/ת שם אחד", "אומר/ת כמה שמות", "פונה כשצריך"]}, {"id": "t4", "text": "משתתף/ת בפעילויות ובקבוצה עם השגחה, בלי להיות מבודד/ת", "staff": "משתתף/ת בקבוצה עם השגחה", "scale": ["עדיין מבודד/ת או נמנע/ת", "משתתף/ת קצת", "משתתף/ת עם מבוגר קרוב", "משתתף/ת ברוב הפעילויות", "משתתף/ת ונהנה/נהנית"]}, {"id": "t5", "text": "שומר/ת על מרחק גוף מתאים מילדים אחרים", "staff": "שומר/ת מרחק מתאים מילדים", "scale": ["עדיין לא שומר/ת", "שומר/ת עם תזכורת צמודה", "שומר/ת עם תזכורת", "שומר/ת לבד", "שומר/ת גם במשחק סוער"]}], "interventions": [{"id": "i1", "name": "לעצור ברוגע, בלי בושה", "what": "מתקרבים בשקט ועוצרים בקול רגיל, בלי צעקה ובלי הבעת גועל, ומפנים לפעילות אחרת.", "why": "בושה מסתירה, רוגע מאפשר לעזור.", "freq": "בכל אירוע", "approach": "סמכות חדשה", "targets": ["t2"], "sentences": ["עוצרים. אצלנו הגוף פרטי", "בוא/י נעשה משהו אחר", "אתה/את לא בצרות"], "avoid": "לא לצעוק, לא לחקור ולא לדבר על זה מול ילדים"}, {"id": "i2", "name": "לתעד ולדווח מיד לפי הנוהל", "what": "רושמים בדיוק מה ראו ושמעו, בלי פרשנות, ומדווחים מיד לאחראי המשמרת ולמטפלת לפי הנוהל.", "why": "התנהגות כזו יכולה להעיד על פגיעה, וחובה לדווח.", "freq": "בכל אירוע", "approach": "ARC", "targets": ["t2"], "sentences": ["תודה שעצרת", "אני ממשיך/ה לשמור עליך", "הכל בסדר איתך"], "avoid": "לא לשאול ''מי עשה לך את זה'' ולא לבקש להדגים"}, {"id": "i3", "name": "ללמד כללי גוף לכל הילדים (בהנחיית המטפלת)", "what": "המטפלת מנסחת כללים פשוטים לכל הילדים במרכז, והצוות מלמד אותם לכולם, לא רק לו/לה.", "why": "כללים לכולם מלמדים בלי לסמן.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1"], "sentences": ["אצלנו הידיים לעצמנו", "בשירותים סוגרים דלת", "את הבגדים מחליפים בחדר"]}, {"id": "i4", "name": "לשמור על השגחה וסידורים (בהנחיית המטפלת)", "what": "המטפלת קובעת סידור שינה, השגחה במקלחת ובמשחק, והצוות שומר עליהם בלי לסמן את הילד/ה מול אחרים.", "why": "השגחה שומרת על כל הילדים.", "freq": "תמיד", "approach": "ARC", "targets": ["t5", "t4"], "sentences": ["אני משחק/ת לידכם", "כאן כולם משחקים בבטחה", "בוא/י תעזור/י לי"], "avoid": "לא להפוך השגחה לבידוד או לעונש"}, {"id": "i5", "name": "לבנות ''יד של מבוגרים''", "what": "מכינים יחד ציור של יד עם חמישה מבוגרים שאפשר לספר להם כשמשהו מבלבל או מפחיד.", "why": "מי שיודע/ת למי לספר, מספר/ת.", "freq": "פעם אחת ומעדכנים", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["למי אפשר לספר?", "גם לי אפשר", "תמיד מותר לספר"]}, {"id": "i6", "name": "להמשיך לתת חום ושייכות", "what": "ממשיכים משחק, חום ותפקידים. ההתנהגות היא חלק אחד ממנו/ה, לא כולו/ה.", "why": "ילד שמרגיש שייך מקבל עזרה טוב יותר.", "freq": "תמיד", "approach": "TBRI", "targets": ["t4"], "sentences": ["רוצה לשחק איתי?", "שמח/ה שאתה/את פה", "אתה/את חלק מאיתנו"]}, {"id": "i7", "name": "לתרגל מרחק גוף במשחק", "what": "משחק ''חישוק אישי'': כל אחד והמרחב שלו, מתרגלים מרחק נעים.", "why": "מרחק שתורגל במשחק נשמר יותר בקלות.", "freq": "מדי פעם", "approach": "ויסות חושי", "targets": ["t5"], "sentences": ["זה המרחב שלך", "וזה של החבר", "שמרת מרחק, יופי"]}, {"id": "i8", "name": "לעבוד לפי תוכנית המטפלת", "what": "הטיפול עצמו נעשה אצל המטפלת. הצוות שומר על הכללים, מעדכן ומקבל הנחיות.", "why": "תוכנית אחת שכולם עובדים לפיה עוזרת יותר.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["המטפלת עובדת איתך על זה", "אנחנו עוזרים לך לשמור על הכללים", "אתה/את מתקדם/ת"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'נשאר/ת בטוח/ה כשרוצה לברוח', 'כשבא לברוח, לבחור במקום בטוח ובמבוגר', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['CPS', 'ARC', 'TBRI', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא לרדוף בריצה, לא לחכות שיחזור/תחזור לבד בלי לדווח, ולא לאיים או להעניש בחזרה", "strengths": ["אומץ", "בקשת עזרה", "אמון"], "skills": ["פנייה למבוגר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "נגזר ממחקר על בריחה מסידור חוץ־ביתי (קשורה לגעגוע ולמצוקה) ומ-CPS ו-ARC. ההתערבויות הן התאמה יישומית; פעולות בזמן בריחה תמיד לפי נוהל המסגרת."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "כשבא לו/ה לברוח, משתמש/ת בסימן המוסכם או הולך/ת למקום הבטוח שסיכמנו", "staff": "הולך/ת למקום הבטוח במקום לברוח", "scale": ["עדיין יוצא/ת בלי רשות", "יוצא/ת וחוזר/ת מהר", "עוצר/ת כשמבוגר מזכיר את הסימן", "משתמש/ת בסימן לבד", "מספר/ת למבוגר מראש שקשה"]}, {"id": "t2", "text": "אחרי בריחה, חוזר/ת ומקבל/ת את הטיפול והשיחה", "staff": "חוזר/ת ומקבל/ת את השיחה", "scale": ["עדיין מסרב/ת לדבר", "חוזר/ת ושותק/ת", "מקשיב/ה בשיחה", "מספר/ת מה קרה", "מציע/ה מה יעזור בפעם הבאה"]}, {"id": "t3", "text": "מספר/ת למבוגר כשמתגעגע/ת למשפחה במקום לברוח אליה", "staff": "מספר/ת על געגוע במקום לברוח", "scale": ["עדיין שומר/ת בפנים", "מראה בהתנהגות", "אומר/ת כששואלים", "אומר/ת מיוזמתו/ה", "מבקש/ת דרך מותרת לקשר"]}, {"id": "t4", "text": "ברגעים קשים צפויים (ביקור, דיון), נשאר/ת קרוב/ה למבוגר", "staff": "נשאר/ת קרוב ברגעים קשים", "scale": ["עדיין מתרחק/ת או נעלם/ת", "נשאר/ת כשמבוגר צמוד", "נשאר/ת עם תזכורת", "נשאר/ת לבד", "מבקש/ת בעצמו/ה מבוגר"]}, {"id": "t5", "text": "יודע/ת את כללי הבטיחות מחוץ למרכז (כביש, זרים, טלפון)", "staff": "יודע/ת כללי בטיחות בחוץ", "scale": ["עדיין לא יודע/ת", "חוזר/ת אחרי מבוגר", "אומר/ת כששואלים", "אומר/ת לבד", "מזכיר/ה לחבר"]}], "interventions": [{"id": "i1", "name": "לסכם סימן ומקום בטוח", "what": "ברגע רגוע, ובתיאום עם המטפלת, מסכמים סימן לבקשת יציאה ומקום בטוח בתוך המרכז.", "why": "דרך מותרת לצאת מורידה את הצורך לברוח.", "freq": "בתחילת המטרה, ומרעננים", "approach": "CPS", "targets": ["t1"], "sentences": ["מה יהיה הסימן שלך?", "לאן אפשר ללכת כשקשה?", "שם תמיד אפשר להירגע"]}, {"id": "i2", "name": "לפעול לפי הנוהל כשיוצא/ת", "what": "לא רודפים בריצה. שומרים קשר עין אם אפשר, מדווחים מיד לפי הנוהל, ומבוגר אחד הולך בקצב רגוע.", "why": "רדיפה מסכנת והופכת למשחק.", "freq": "בכל יציאה", "approach": "ARC", "targets": ["t2"], "sentences": ["אני הולך/ת לידך, לא רודף/ת", "אני דואג/ת לך", "בוא/י נחזור ביחד"], "avoid": "לא לאיים ולא לחכות בלי לדווח"}, {"id": "i3", "name": "לקבל בחום בחזרה", "what": "כשחוזר/ת: אוכל, שתייה, בדיקה שהכל בסדר ומשפט חם. השיחה מחכה לאחר כך.", "why": "קבלה חמה מלמדת שתמיד אפשר לחזור.", "freq": "בכל חזרה", "approach": "TBRI", "targets": ["t2"], "sentences": ["טוב שחזרת", "קודם תאכל/י ותנוח/י", "נדבר אחר כך"]}, {"id": "i4", "name": "לשוחח אחרי בלי עונש (בהנחיית המטפלת)", "what": "שיחה רגועה: ממה ברחת, לאן, מה קרה בדרך, ומה יעזור בפעם הבאה.", "why": "שיחה בלי עונש מגלה את הסיבה.", "freq": "אחרי כל בריחה", "approach": "CPS", "targets": ["t2", "t3"], "sentences": ["מה קרה לפני שיצאת?", "לאן רצית להגיע?", "מה יעזור בפעם הבאה?"], "avoid": "אם עולה פגיעה, מקשיבים ברוגע, מודים ומדווחים לפי הנוהל, בלי שאלות מנחות"}, {"id": "i5", "name": "לתת מקום לגעגוע (בהנחיית המטפלת)", "what": "אם הבריחה היא אל המשפחה, המטפלת בודקת מה אפשר: שיחה, מכתב, תמונה, ביקור מתוכנן.", "why": "געגוע שמקבל מענה לא צריך לברוח.", "freq": "לפי הצורך", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["אתה/את מתגעגע/ת למשפחה", "זה מובן", "בוא/י נבדוק מה אפשר"]}, {"id": "i6", "name": "להיות קרוב ברגעים קשים צפויים", "what": "לפני ביקור, דיון או חזרה מיום רע נותנים יותר נוכחות ופחות דרישות.", "why": "רגע קשה צפוי הוא רגע של סיכון.", "freq": "ברגעים צפויים", "approach": "ARC", "targets": ["t4"], "sentences": ["היום יום קשה, אני קרוב/ה", "אפשר לבוא אליי", "נעבור את זה ביחד"]}, {"id": "i7", "name": "ללמד כללי בטיחות בחוץ", "what": "במשחק ובשיחה מתרגלים: כביש, זרים, איך מתקשרים למרכז.", "why": "ילד שיודע כללים בטוח יותר גם כשיוצא.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t5"], "sentences": ["מה עושים בכביש?", "אם מישהו זר פונה?", "זה המספר של המרכז"]}, {"id": "i8", "name": "לשבח שימוש בסימן", "what": "כשהשתמש/ה בסימן או הלך/ה למקום הבטוח, משבחים בשקט.", "why": "בחירה בטוחה שמקבלת חיזוק חוזרת.", "freq": "בכל שימוש", "approach": "TBRI", "targets": ["t1"], "sentences": ["השתמשת בסימן, זה היה חכם", "בחרת להישאר בטוח/ה", "אני גאה בך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מתקנים ביחד', 'לתקן אחרי שפגעתי במישהו, ולחזור לקבוצה', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['ARC', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לקיים שיחת תיקון בשיא הסערה, לא לכפות מפגש, ולא לתקן על חשבון מי שנפגע", "strengths": ["אחריות", "כנות", "הוגנות"], "skills": ["פתרון בעיות"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "נגזר מפרקטיקה משקמת בבתי ספר (Restorative Practice, עם ממצאים מעורבים) ומ-CPS. במסגרות חוץ־ביתיות זו התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "אחרי שנרגע/ה, עונה בשיחה על מה קרה ומי נפגע", "staff": "מספר/ת מה קרה ומי נפגע", "scale": ["עדיין מסרב/ת או מאשים/ה", "שותק/ת אבל נשאר/ת", "מספר/ת חלק", "מספר/ת ומודה במה שעשה/תה", "מבין/ה איך החבר הרגיש"]}, {"id": "t2", "text": "בוחר/ת דרך לתקן מתוך רשימה ומבצע/ת", "staff": "בוחר/ת דרך לתקן ומבצע/ת", "scale": ["עדיין לא בוחר/ת", "בוחר/ת עם עזרה", "בוחר/ת ומתחיל/ה", "בוחר/ת ומבצע/ת", "מציע/ה תיקון בעצמו/ה"]}, {"id": "t3", "text": "חוזר/ת לפעילות עם הקבוצה אחרי התיקון", "staff": "חוזר/ת לקבוצה אחרי תיקון", "scale": ["עדיין מתבודד/ת", "חוזר/ת עם מבוגר", "חוזר/ת לחלק מהפעילות", "חוזר/ת לגמרי", "מתנהג/ת כרגיל"]}, {"id": "t4", "text": "מקבל/ת תיקון ממבוגר כשמבוגר טעה", "staff": "מקבל/ת תיקון ממבוגר", "scale": ["עדיין לא מקבל/ת", "מקשיב/ה", "אומר/ת בסדר", "מקבל/ת וממשיך/ה", "מתקן/ת בעצמו/ה באותה דרך"]}, {"id": "t5", "text": "בפעם הבאה, משתמש/ת במה שלמד/ה בשיחה", "staff": "משתמש/ת במה שלמד/ה", "scale": ["עדיין חוזר/ת על אותו דבר", "נעצר/ת באמצע", "משתמש/ת עם תזכורת", "משתמש/ת לבד", "מלמד/ת חבר"]}], "interventions": [{"id": "i1", "name": "לחכות לרוגע לפני שיחה", "what": "לא מקיימים שיחת תיקון בשיא הסערה. מחכים שעה או עד הערב.", "why": "רק ראש רגוע יכול לתקן.", "freq": "בכל אירוע", "approach": "ARC", "targets": ["t1"], "sentences": ["נדבר כשתהיה/תהיי רגוע/ה", "נחזור לזה כשיהיה רגוע", "נשב לדבר אחר כך, כשיהיה רגוע"]}, {"id": "i2", "name": "לשאול ארבע שאלות", "what": "מה קרה? מה חשבת והרגשת? מי נפגע ואיך? מה צריך כדי לתקן?", "why": "שאלות פתוחות מובילות לאחריות בלי בושה.", "freq": "בשיחת תיקון", "approach": "CPS", "targets": ["t1", "t2"], "sentences": ["מה קרה?", "מי נפגע?", "מה יעזור לתקן?"], "avoid": "לא להפוך את השיחה לחקירה או להרצאה"}, {"id": "i3", "name": "לתת רשימת דרכי תיקון", "what": "רשימה שאפשר לבחור ממנה: מכתב, עזרה לתקן, פעולה טובה, שיחה.", "why": "בחירה הופכת תיקון לשלו/ה.", "freq": "בשיחת תיקון", "approach": "CPS", "targets": ["t2"], "sentences": ["איזו דרך מתאימה לך?", "מתי תעשה/תעשי את זה?", "ראיתי שתיקנת"]}, {"id": "i4", "name": "לתווך מפגש תיקון (בהנחיית המטפלת)", "what": "מפגש קצר בין הצדדים, רק אם שניהם מסכימים ומבוגר מנחה.", "why": "מפגש בטוח יכול לסגור את הפגיעה.", "freq": "בפגיעה משמעותית", "approach": "CPS", "targets": ["t2", "t3"], "sentences": ["שניכם רוצים לדבר?", "כל אחד בתורו", "מה סיכמתם?"], "avoid": "לא לקיים מפגש כשיש פער כוחות או כשהנפגע/ת לא רוצה"}, {"id": "i5", "name": "לתקן בעצמי כמבוגר", "what": "אם המבוגר צעק או טעה, הוא מתקן מול הילד/ה.", "why": "מבוגר שמתקן מלמד שתיקון אפשרי.", "freq": "אחרי טעות של מבוגר", "approach": "TBRI", "targets": ["t4"], "sentences": ["צעקתי, וזה לא היה בסדר", "אני מצטער/ת", "בוא/י נתחיל מחדש"]}, {"id": "i6", "name": "לשמור קודם על מי שנפגע", "what": "הילד/ה שנפגע מקבל/ת קודם טיפול, נוכחות והגנה.", "why": "תיקון לא בא על חשבון הנפגע.", "freq": "בכל פגיעה", "approach": "ARC", "targets": ["t3"], "sentences": ["אני איתך עכשיו", "אתה/את בטוח/ה", "נטפל בזה"]}, {"id": "i7", "name": "להחזיר לקבוצה", "what": "אחרי התיקון מחזירים לפעילות כרגיל, בלי להזכיר שוב.", "why": "חזרה רגילה אומרת שהעניין נסגר.", "freq": "אחרי תיקון", "approach": "TBRI", "targets": ["t3"], "sentences": ["בוא/י, ממשיכים", "סגרנו את זה", "שמח/ה שחזרת"]}, {"id": "i8", "name": "לבדוק מה למד/ה", "what": "כמה ימים אחרי, שואלים בקצרה מה יעזור אם זה יקרה שוב.", "why": "חזרה קצרה מקבעת את הלמידה.", "freq": "כמה ימים אחרי", "approach": "CPS", "targets": ["t5"], "sentences": ["זוכר/ת את השיחה?", "מה תעשה/תעשי אם זה יקרה שוב?", "יש לך תוכנית"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תוכנית בטיחות שלי (בהנחיית המטפלת)', 'כשקשה מאוד, יש לי תוכנית שאני יודע/ת ומבוגרים שיודעים אותה', array['התנהגות מסכנת וגבולות']::text[], 'התנהגות מסכנת וגבולות', array['ARC', 'TBRI', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להבטיח לשמור סוד, לא לנהל הערכה לבד, לא להגיב בכעס או בבהלה, ולא לחפש באופן עונשי", "strengths": ["אומץ", "כנות", "תקווה"], "skills": ["בקשת עזרה"], "main": "13-15", "also": ["10-12"], "evidence": {"level": "derived", "note": "תוכנית בטיחות (Safety Planning) והנחיות הטיפול בפגיעה עצמית (כמו NICE) מבוססות מחקר. התפקיד של המדריכים (זיהוי, תגובה ראשונה רגועה, הכרת התוכנית ודיווח) הוא עקרון בטיחות; ההערכה והתוכנית בידי המטפלת."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "מכיר/ה את תוכנית הבטיחות שלו/ה ויודע/ת לומר את הצעד הראשון", "staff": "יודע/ת את הצעד הראשון בתוכנית", "scale": ["עדיין לא מכיר/ה", "מכיר/ה כשמראים", "אומר/ת צעד אחד", "אומר/ת כמה צעדים", "משתמש/ת בתוכנית"]}, {"id": "t2", "text": "כשקשה מאוד, פונה למבוגר מהרשימה", "staff": "פונה למבוגר כשקשה מאוד", "scale": ["עדיין מסתיר/ה", "מסכים/ה לדבר כשמבוגר מתקרב", "פונה אחרי שקרה", "פונה בזמן", "פונה מוקדם, לפני שמחמיר"]}, {"id": "t3", "text": "משתמש/ת בדרך הרגעה מהתוכנית ברגע קשה", "staff": "משתמש/ת בדרך מהתוכנית", "scale": ["עדיין לא", "משתמש/ת כשמבוגר מזכיר", "משתמש/ת לפעמים", "משתמש/ת ברוב הפעמים", "יש לו/ה כמה דרכים"]}, {"id": "t4", "text": "אחרי אירוע, ממשיך/ה בשגרה ובפעילויות", "staff": "ממשיך/ה בשגרה אחרי אירוע", "scale": ["עדיין מסתגר/ת", "חוזר/ת לחלק מהשגרה", "חוזר/ת עם עזרה", "חוזר/ת לשגרה", "משתתף/ת ונהנה/נהנית"]}, {"id": "t5", "text": "כשבא לו/ה לברוח, פונה למבוגר במקום לצאת", "staff": "פונה למבוגר במקום לברוח", "scale": ["עדיין יוצא/ת בלי רשות", "יוצא/ת וחוזר/ת", "מתלבט/ת ופונה", "פונה ברוב הפעמים", "מספר/ת מראש שקשה"]}], "interventions": [{"id": "i1", "name": "לזהות סימנים", "what": "שמים לב לסימנים: פצעים מוסתרים, שרוולים ארוכים בחום, הסתגרות, נתינת חפצים, דיבור על כך שאין טעם, ומעבירים למטפלת.", "why": "זיהוי מוקדם מציל.", "freq": "תמיד", "approach": "ARC", "targets": ["t2"], "sentences": ["שמתי לב שאתה/את נראה/נראית עצוב/ה", "אני כאן אם תרצה/תרצי לדבר", "אכפת לי ממך"], "avoid": "לא להתעלם ''כי רק מחפש/ת תשומת לב''"}, {"id": "i2", "name": "להגיב ברוגע לפגיעה עצמית", "what": "שומרים על רוגע וקול נמוך, בודקים אם צריך עזרה רפואית ופועלים לפי הנוהל, ומדווחים מיד למטפלת.", "why": "תגובה רגועה שומרת על הקשר ועל הבטיחות.", "freq": "בכל אירוע", "approach": "TBRI", "targets": ["t2"], "sentences": ["אני כאן איתך", "קודם נדאג שאתה/את בסדר", "אני צריך/ה לספר למטפלת כדי לשמור עליך"], "avoid": "לא לכעוס, לא להיבהל ולא להבטיח לשמור סוד"}, {"id": "i3", "name": "להעביר חשש מיד למטפלת", "what": "שאלה ישירה על מחשבות לפגוע בעצמו/ה שואלת רק המטפלת. הצוות שם לב, נשאר קרוב, ומעביר מיד למטפלת לפי הנוהל.", "why": "המטפלת יודעת לשאול ולהעריך את הסיכון.", "freq": "כשיש חשש", "approach": "ARC", "targets": ["t2"], "sentences": ["אני רואה שקשה לך מאוד", "אני נשאר/ת איתך", "נבקש מהמטפלת לדבר איתך עכשיו"], "avoid": "לא לשאול בעצמך על פגיעה עצמית ולא לנהל הערכה לבד"}, {"id": "i4", "name": "להכיר את התוכנית (בהנחיית המטפלת)", "what": "התוכנית כוללת סימנים מקדימים, מה הוא/היא עושה, למי פונים ומה הצוות עושה. כל צוות המשמרת מכיר אותה.", "why": "תוכנית שכולם מכירים עובדת בכל משמרת.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1", "t3"], "sentences": ["מה הצעד הראשון בתוכנית שלך?", "אני מכיר/ה את התוכנית", "אני כאן לעזור לך בה"]}, {"id": "i5", "name": "לשמור על אמצעים מסוכנים (בהנחיית המטפלת)", "what": "שומרים חפצים חדים ותרופות לפי התוכנית, בכבוד, ובלי שזה ירגיש כמו עונש.", "why": "פחות גישה לאמצעים מורידה סיכון.", "freq": "תמיד", "approach": "ARC", "targets": ["t1"], "sentences": ["אנחנו שומרים את זה בשבילך", "זה חלק מהתוכנית שלך", "זה לא עונש"], "avoid": "לא לקחת את כל החפצים האישיים בלי תוכנית"}, {"id": "i6", "name": "לפעול לפי הנוהל בבריחה", "what": "אם יוצא/ת בלי רשות: דיווח מיידי לפי הנוהל, ניסיון קשר, ובחזרה קבלה חמה ושיחה עם המטפלת.", "why": "בריחה של נער/ה במצוקה היא מצב סיכון.", "freq": "בכל יציאה", "approach": "ARC", "targets": ["t5"], "sentences": ["טוב שחזרת", "דאגנו לך", "בוא/י נדבר כשתהיה/תהיי מוכן/ה"]}, {"id": "i7", "name": "להמשיך שגרה וקשר", "what": "אחרי אירוע ממשיכים בשגרה ובפעילויות, ונותנים יותר נוכחות.", "why": "שגרה וקשר שומרים על הנער/ה.", "freq": "אחרי אירוע", "approach": "TBRI", "targets": ["t4"], "sentences": ["רוצה להצטרף לפעילות?", "שמח/ה שאתה/את פה", "אני ממשיך/ה להיות כאן"]}, {"id": "i8", "name": "לבנות יחד רשימת מבוגרים", "what": "רושמים מי המבוגרים שאפשר לפנות אליהם בכל משמרת, וגם קווי סיוע מחוץ למרכז: ער\"ן בטלפון 1201 וסה\"ר בצ''אט. מעדכנים מדי פעם.", "why": "תמיד יש מישהו לפנות אליו.", "freq": "מדי פעם", "approach": "מעגל הביטחון", "targets": ["t2", "t5"], "sentences": ["למי תוכל/י לפנות הלילה?", "גם אני ברשימה", "ויש גם את ער\"ן, 1201, בכל שעה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'המבוגרים שלי', 'לפנות למבוגרים המוכרים שלי, ולא לכל מבוגר שעובר', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['מעגל הביטחון', 'ARC', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לנזוף על התקרבות לזרים, ולא להגיב בקרירות לחיבוק כדי לחנך", "strengths": ["פתיחות", "אמון", "שמחה"], "skills": ["פנייה למבוגר"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "היקשרות לא מובחנת (נצמדות לכל מבוגר) מתוארת אצל ילדים שגדלו עם הזנחה או ריבוי מטפלים. עבודה דרך מבוגרים קבועים נגזרת ממעגל הביטחון ו-ARC; במסגרות קבוצתיות זו התאמה יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "כשצריך עזרה או נחמה, פונה קודם למבוגר מוכר מהצוות", "staff": "פונה קודם למבוגר מוכר", "scale": ["עדיין פונה לכל מבוגר שעובר", "פונה למוכר כשהוא קרוב מאוד", "פונה למוכר כשמכוונים", "פונה למוכר ברוב הפעמים", "מחפש/ת מבוגר מוכר גם כשהוא רחוק"]}, {"id": "t2", "text": "כשמבוגר לא מוכר נכנס, מחכה ליד מבוגר מוכר במקום לרוץ אליו", "staff": "נשאר/ת ליד מוכר כשנכנס זר", "scale": ["עדיין רץ/ה ונצמד/ת לזר", "נעצר/ת כשמבוגר מוכר קורא", "מתקרב/ת עם מבוגר מוכר", "מסתכל/ת על מוכר לפני שמתקרב/ת", "מחכה ליד מוכר לבד"]}, {"id": "t3", "text": "מכיר/ה בתמונות את המבוגרים הקבועים ויודע/ת מי כאן היום", "staff": "מכיר/ה את המבוגרים שלו/ה בתמונות", "scale": ["עדיין לא מבחין/ה", "מצביע/ה על מבוגר אחד", "מצביע/ה על כמה", "יודע/ת מי כאן היום", "שואל/ת על מי שלא כאן"]}, {"id": "t4", "text": "בפרידה ובאיחוד עם המבוגר הקבוע, מגיב/ה לטקס הקבוע", "staff": "מגיב/ה לפרידה ולאיחוד", "scale": ["עדיין לא מגיב/ה", "מגיב/ה לרגע", "משתתף/ת בטקס", "מחכה לטקס", "מספר/ת מה עשה/תה כשהמבוגר לא היה"]}, {"id": "t5", "text": "מחוץ למרכז (גינה, מרפאה, טיול), נשאר/ת קרוב/ה למבוגר שלו/ה", "staff": "נשאר/ת קרוב בחוץ", "scale": ["עדיין הולך/ת עם כל מבוגר", "נשאר/ת כשמחזיקים יד", "נשאר/ת עם תזכורת", "נשאר/ת לבד", "חוזר/ת לבדוק איפה המבוגר"]}], "interventions": [{"id": "i1", "name": "להחזיר בעדינות, בלי לדחות", "what": "כשניגש/ת לזר, המבוגר הקבוע מתקרב, מחזיר בחום ומשתף במשחק.", "why": "הכוונה חמה מלמדת למי פונים בלי לבייש.", "freq": "בכל פעם", "approach": "מעגל הביטחון", "targets": ["t2", "t1"], "sentences": ["בוא/י אליי, אני שומר/ת עליך היום", "רוצה לשחק איתי?", "אני כאן"], "avoid": "לא לנזוף או לומר ''אסור''"}, {"id": "i2", "name": "לעשות טקס פרידה ואיחוד", "what": "המבוגר הקבוע תמיד נפרד ואומר מתי יחזור, ובחזרה מברך באותו טקס.", "why": "פרידה צפויה מלמדת שמבוגרים חוזרים.", "freq": "בכל פרידה ואיחוד", "approach": "מעגל הביטחון", "targets": ["t4"], "sentences": ["אני הולך/ת עכשיו, ובלוח רואים מתי אני חוזר/ת", "הנה חזרתי", "חיכיתי לראות אותך"]}, {"id": "i3", "name": "לתלות לוח ''מי שומר עליי''", "what": "לוח עם תמונות של המבוגרים הקבועים, ומסמנים מי נמצא היום.", "why": "לראות מי כאן מקטין את הצורך לחפש בכל מקום.", "freq": "כל יום", "approach": "ARC", "targets": ["t3"], "sentences": ["מי שומר עליך היום?", "הנה אני בתמונה", "בלוח רואים מי יבוא מחר"]}, {"id": "i4", "name": "לשמור קרוב מחוץ למרכז", "what": "בגינה, במרפאה ובטיול שומרים עליו/ה קרוב יותר, כי הוא/היא עלול/ה ללכת עם כל אחד.", "why": "בחוץ, הנטייה לזרים היא סיכון.", "freq": "בכל יציאה", "approach": "ARC", "targets": ["t5"], "sentences": ["בחוץ נשארים לידי", "נחזיק יד", "בדקת איפה אני, יופי"]}, {"id": "i5", "name": "לתת זמן אחד על אחד קבוע", "what": "זמן קצר וקבוע עם המבוגר הקבוע, שהילד/ה מוביל/ה.", "why": "קשר מיוחד אחד מלמד מה זה מבוגר שלי.", "freq": "כל יום", "approach": "TBRI", "targets": ["t1"], "sentences": ["עכשיו הזמן שלנו", "במה נשחק?", "כיף לי איתך"]}, {"id": "i6", "name": "לבקש מאורחים לשמור מרחק", "what": "מבקשים מאורחים ומבוגרים חדשים לא לחבק ולא להרים, ולברך מרחוק.", "why": "כשזרים לא מתקרבים, הילד לומד את ההבדל.", "freq": "בכל ביקור", "approach": "ARC", "targets": ["t2"], "sentences": ["זה אורח, אומרים שלום מכאן", "אני לידך", "נעים להכיר"]}, {"id": "i7", "name": "לשבח פנייה למוכר", "what": "כשפנה/תה למבוגר מוכר, מגיבים בחום ומשבחים.", "why": "פנייה שמקבלת חום חוזרת.", "freq": "בכל פנייה", "approach": "TBRI", "targets": ["t1"], "sentences": ["באת אליי, איזה יופי", "אני שמח/ה שבאת", "מה צריך?"]}, {"id": "i8", "name": "לעבוד לפי תוכנית המטפלת", "what": "המטפלת קובעת מי המבוגרים הקבועים ואיך עובדים, והצוות שומר על אותה דרך בכל משמרת.", "why": "כשכל המבוגרים עושים אותו דבר, הילד/ה לומד/ת לסמוך עליהם.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["אנחנו המבוגרים שלך", "כולנו עושים אותו דבר", "אתה/את לא לבד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'יודע/ת מי איתי', 'להרגיש שכל המבוגרים מכירים אותי ומדברים איתי באותה שפה', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['ARC', 'מעגל הביטחון', 'DDP/PACE', 'TBRI', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להיעלם בלי להיפרד, ולא לומר ''עוד מעט'' כשמדובר בשבוע", "strengths": ["אמון", "גמישות", "פתיחות"], "skills": ["התמודדות עם שינוי"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "עקביות בין מטפלים היא עקרון מרכזי במערכות מותאמות טראומה (TIC, ARC). מסירת מידע בין משמרות והכנה להיעדרות הן התאמה יישומית שלא נבדקה במחקר ישיר."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "נרגע/ת עם המשפטים הקבועים גם כשהם נאמרים ממבוגר אחר", "staff": "נרגע/ת מהמשפטים הקבועים", "scale": ["עדיין נרגע/ת רק עם מבוגר אחד", "נרגע/ת לאט עם אחרים", "נרגע/ת עם אחרים שמשתמשים במשפטים", "נרגע/ת ברוב הפעמים", "נרגע/ת עם כל מבוגר מהצוות"]}, {"id": "t2", "text": "כשמבוגר קבוע לא בא כמה ימים, מקבל/ת את ההסבר ואת מה שהשאיר", "staff": "מקבל/ת היעדרות של מבוגר קבוע", "scale": ["עדיין מתפרק/ת או מסתגר/ת", "נרגע/ת לאט עם עזרה", "מקבל/ת עם החפץ שהשאיר", "שואל/ת ומקבל/ת", "מחכה בשקט לחזרה"]}, {"id": "t3", "text": "כשהמבוגר חוזר, מגיב/ה ומתחבר/ת שוב, גם אחרי כעס", "staff": "מתחבר/ת שוב כשהמבוגר חוזר", "scale": ["עדיין מתעלם/ת זמן ארוך", "כועס/ת ואז מתקרב/ת", "מתקרב/ת עם עזרה", "מתקרב/ת מהר", "מספר/ת שהתגעגע/ה"]}, {"id": "t4", "text": "מקבל/ת ברכה ממבוגר שמכיר אותו/ה מהכרטיס", "staff": "מקבל/ת ברכה ממבוגר חדש", "scale": ["עדיין נבהל/ת", "מסתכל/ת", "מגיב/ה לברכה", "מגיב/ה ומחייך/ת", "פונה למבוגר החדש"]}, {"id": "t5", "text": "בסוף משמרת, מקבל/ת את המעבר בין המבוגרים", "staff": "מקבל/ת את חילופי המשמרת", "scale": ["עדיין נצמד/ת ובוכה", "נרגע/ת עם הרבה עזרה", "נרגע/ת עם הטקס", "מקבל/ת את המעבר", "מספר/ת למבוגר החדש מה היה"]}], "interventions": [{"id": "i1", "name": "לכתוב כרטיס ''מה עוזר לי''", "what": "כרטיס קצר במערכת: מה מרגיע, איך אוהב/ת שמברכים, מה מפחיד. כל משמרת קוראת.", "why": "מבוגר שיודע מה עוזר הוא לא זר.", "freq": "מתעדכן באופן קבוע", "approach": "ARC", "targets": ["t4", "t1"], "sentences": ["אני יודע/ת שאתה/את אוהב/ת את השיר הזה", "שמעתי שהדובי עוזר לך", "בוא/י נעשה כמו שאתה/את אוהב/ת"]}, {"id": "i2", "name": "לדבר באותם משפטים", "what": "כל המבוגרים משתמשים באותם משפטים קבועים להרגעה, להשכבה ולפרידה.", "why": "שפה אחת יוצרת ביטחון גם כשמחליפים מבוגר.", "freq": "תמיד", "approach": "ARC", "targets": ["t1"], "sentences": ["אני פה, אתה/את בטוח/ה", "כמו תמיד", "עכשיו נושמים"]}, {"id": "i3", "name": "להעביר משמרת יד ביד", "what": "המבוגר היוצא אומר שלום, מציג את הנכנס ומספר לו דבר אחד טוב מהיום, ליד הילד/ה.", "why": "מעבר שרואים הוא לא נטישה.", "freq": "בכל חילוף משמרת", "approach": "מעגל הביטחון", "targets": ["t5"], "sentences": ["עכשיו באה דנה, והיא יודעת עליך", "סיפרתי לה כמה עזרת היום", "בלוח רואים מתי נתראה"]}, {"id": "i4", "name": "להכין להיעדרות", "what": "לפני חופש מספרים מראש, מסמנים בלוח מתי חוזרים ומשאירים משהו (תמונה, ציור).", "why": "היעדרות מוכנה לא מרגישה כמו היעלמות.", "freq": "לפני כל היעדרות", "approach": "מעגל הביטחון", "targets": ["t2"], "sentences": ["אני נוסע/ת לכמה ימים", "תראה/תראי בלוח מתי אני חוזר/ת", "השארתי לך את הציור הזה"], "avoid": "לא להיעלם בלי לומר"}, {"id": "i5", "name": "לקבל את התגובה באיחוד", "what": "בחזרה מכירים בהיעדרות ומקבלים כל תגובה, גם כעס או התעלמות.", "why": "קבלה של הכעס שומרת על הקשר.", "freq": "אחרי כל היעדרות", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["לא הייתי כמה ימים", "אולי כעסת, וזה בסדר", "אני שמח/ה לראות אותך"]}, {"id": "i6", "name": "להציג את המבוגר החדש", "what": "מבוגר חדש מוצג בשם ובתמונה, ומבלה זמן קצר עם הילד/ה ליד מבוגר מוכר.", "why": "היכרות דרך מבוגר מוכר מורידה פחד.", "freq": "בכל מבוגר חדש", "approach": "TBRI", "targets": ["t4"], "sentences": ["זה יוסי, הוא חדש אצלנו", "נשחק כולנו ביחד", "הוא יודע מה אתה/את אוהב/ת"]}, {"id": "i7", "name": "לשמור על אותו סדר יום בכל משמרת", "what": "אותם טקסים, אותם זמנים ואותם כללים, לא משנה מי במשמרת.", "why": "סדר זהה מחזיק את הילד גם כשהמבוגר משתנה.", "freq": "תמיד", "approach": "NMT", "targets": ["t1", "t5"], "sentences": ["כמו תמיד, עכשיו ארוחה", "גם אצלי זה ככה", "אתה/את כבר יודע/ת"]}, {"id": "i8", "name": "לשתף את המטפלת בשינויים", "what": "כשמבוגר משמעותי עוזב או נעדר הרבה, מעדכנים את המטפלת כדי שתכין את הילד/ה.", "why": "שינוי גדול בצוות משפיע על הקשר של הילד/ה למבוגרים.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t2"], "sentences": ["נדבר על זה גם עם המטפלת", "אנחנו נמשיך לשמור עליך", "אפשר לשאול אותי הכל"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מותר להתקרב לאט', 'לבנות קשר עם מבוגר בקצב שלי, גם כשקרבה מפחידה', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['TBRI', 'DDP/PACE', 'Theraplay', 'ARC']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להיעלב, לא להגיב ''אז לא אעזור לך'', ולא לכפות קרבה או מגע", "strengths": ["אומץ", "עצמאות", "סקרנות"], "skills": ["קבלת עזרה"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "דחיית קרבה אצל ילדים עם היסטוריה של פגיעה מתוארת בספרות ההיקשרות; עבודה דרך PACE (DDP) ו-TBRI נבדקה בעיקר עם הורים מאמצים. אצל מדריכים זו התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "נשאר/ת ליד מבוגר בפעילות משותפת (בנייה, ציור, משחק) כמה דקות", "staff": "נשאר/ת ליד מבוגר בפעילות", "scale": ["עדיין מתרחק/ת", "נשאר/ת רגע קצר", "נשאר/ת כמה דקות", "נשאר/ת עד סוף הפעילות", "מזמין/ה מבוגר לפעילות"]}, {"id": "t2", "text": "מקבל/ת עזרה קטנה ממבוגר בלי לדחות", "staff": "מקבל/ת עזרה קטנה", "scale": ["עדיין דוחה כל עזרה", "מקבל/ת עזרה בלי מילים", "מקבל/ת עזרה כשמציעים", "מבקש/ת עזרה קטנה", "מבקש/ת ומודה"]}, {"id": "t3", "text": "אחרי שדחה/תה, חוזר/ת לקשר עם המבוגר", "staff": "חוזר/ת לקשר אחרי שדחה/תה", "scale": ["עדיין נשאר/ת מרוחק/ת", "חוזר/ת אחרי זמן ארוך", "חוזר/ת כשמבוגר מזמין", "חוזר/ת מהר", "חוזר/ת מיוזמתו/ה"]}, {"id": "t4", "text": "משתף/ת מבוגר בדבר קטן שקרה לו/ה", "staff": "מספר/ת למבוגר דבר קטן", "scale": ["עדיין לא משתף/ת", "עונה במילה", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מספר/ת גם על דבר קשה"]}, {"id": "t5", "text": "מראה הנאה ברגע משותף עם מבוגר (חיוך, צחוק)", "staff": "נהנה/נהנית ברגע משותף", "scale": ["עדיין לא מראה", "מחייך/ת לרגע", "צוחק/ת במשחק", "מחפש/ת את הרגעים האלה", "מזמין/ה עוד"]}], "interventions": [{"id": "i1", "name": "להיות קרוב צד אל צד", "what": "במקום שיחה פנים מול פנים, עושים משהו ביחד: בונים, מציירים, מבשלים.", "why": "קרבה ליד, ולא מול, מפחידה פחות.", "freq": "באופן קבוע", "approach": "TBRI", "targets": ["t1", "t5"], "sentences": ["אני בונה פה לידך", "צריך עוד קובייה?", "יצא לנו יפה"]}, {"id": "i2", "name": "לא להיעלב מדחייה", "what": "כשאומר/ת ''לך ממני'', נשארים רגועים, מכבדים מרחק ונשארים זמינים.", "why": "מבוגר שלא נעלב מלמד שהקשר עמיד.", "freq": "בכל דחייה", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["בסדר, אני פה בצד", "כשתרצה/תרצי, אני כאן", "אני לא כועס/ת"], "avoid": "לא להיעלב ולא לוותר על הילד/ה"}, {"id": "i3", "name": "לדבר בסקרנות שקטה", "what": "אומרים בקול מה אולי קורה, בלי לדרוש תשובה.", "why": "סקרנות בלי לחץ מראה שמנסים להבין.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t4"], "sentences": ["אולי קשה לסמוך על מבוגרים", "מעניין אותי מה קורה לך", "לא חייבים לענות"]}, {"id": "i4", "name": "לקיים כל הבטחה קטנה", "what": "מבטיחים מעט, ומקיימים כל מה שהבטחנו.", "why": "אמון נבנה מהבטחות קטנות שמתקיימות.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["אמרתי שאבוא, והנה אני", "אני עושה מה שאמרתי", "אפשר לסמוך עליי בזה"], "avoid": "לא להבטיח מה שלא בטוח"}, {"id": "i5", "name": "להציע עזרה קטנה מאוד", "what": "מציעים עזרה קטנה ומעשית (להחזיק, להביא), ומקבלים גם ''לא''.", "why": "עזרה קטנה קלה לקבל.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t2"], "sentences": ["להחזיק לך?", "אפשר גם בלי", "בסדר, אם תצטרך/תצטרכי, אני פה"]}, {"id": "i6", "name": "לשחק משחק משותף קצר (בהשראת Theraplay)", "what": "משחק קצר ומשמח שהמבוגר מוביל, בלי מגע או עם מגע מוסכם בלבד.", "why": "הנאה משותפת בונה קשר בלי מילים.", "freq": "באופן קבוע", "approach": "Theraplay", "targets": ["t5"], "sentences": ["רוצה לשחק משהו מצחיק?", "תורך!", "צחקנו ביחד"]}, {"id": "i7", "name": "להזמין שוב אחרי דחייה", "what": "אחרי זמן, המבוגר מזמין שוב לפעילות, בלי להזכיר את הדחייה.", "why": "הזמנה חוזרת אומרת: אני לא מוותר/ת עליך.", "freq": "אחרי דחייה", "approach": "TBRI", "targets": ["t3"], "sentences": ["רוצה להצטרף עכשיו?", "שמרתי לך מקום", "שמח/ה שבאת"]}, {"id": "i8", "name": "לזכור פרטים קטנים", "what": "זוכרים מה סיפר/ה וחוזרים לזה: איך היה החוג, מה עם הציור.", "why": "מבוגר שזוכר הוא מבוגר שאכפת לו.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t4"], "sentences": ["איך היה בחוג?", "זכרתי שסיפרת", "ספר/י עוד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הקשר מחזיק', 'לגלות שהקשר עם המבוגר נשאר, גם כשאני בודק/ת אותו', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['TBRI', 'סמכות חדשה', 'ARC', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להתנות את הקשר בהתנהגות, ולא להבטיח ''תמיד אהיה פה'' אם זה לא נכון", "strengths": ["כנות", "אמון", "אומץ"], "skills": ["תיקון קשר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "בדיקת גבולות הקשר מתוארת אצל ילדים שחוו נטישה. הפרדה בין התנהגות לקשר ותיקון יזום של המבוגר נגזרים מ-TBRI ו-DDP/PACE; בהקשר של מדריכים זו התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "אחרי אירוע קשה עם מבוגר, מקבל/ת את התיקון וחוזר/ת לקשר", "staff": "חוזר/ת לקשר אחרי אירוע", "scale": ["עדיין מתרחק/ת זמן ארוך", "מקבל/ת תיקון ושותק/ת", "חוזר/ת אחרי זמן", "חוזר/ת מהר", "מתקן/ת גם בעצמו/ה"]}, {"id": "t2", "text": "מבין/ה שהגבול הוא על ההתנהגות ולא על הקשר", "staff": "מבין/ה שהקשר נשאר גם בגבול", "scale": ["עדיין שומע/ת כל גבול כדחייה", "נרגע/ת כשמזכירים שהקשר נשאר", "שואל/ת אם הקשר נשאר ונרגע/ת מהתשובה", "מקבל/ת גבול בלי לנתק", "מקבל/ת גבול ברוגע"]}, {"id": "t3", "text": "בודק/ת את הקשר פחות בדרכים מסוכנות", "staff": "בודק/ת את הקשר בדרכים פחות קשות", "scale": ["עדיין בודק/ת בהתנהגות קשה", "בודק/ת ונרגע/ת עם מבוגר", "בודק/ת במילים", "שואל/ת ישירות", "כמעט לא צריך/ה לבדוק"]}, {"id": "t4", "text": "מספר/ת למבוגר דברים ומחכה שיזכור", "staff": "משתף/ת ומחכה שנזכור", "scale": ["עדיין לא משתף/ת", "משתף/ת מעט", "משתף/ת כששואלים", "משתף/ת מיוזמתו/ה", "שמח/ה כשזוכרים"]}, {"id": "t5", "text": "כשכועס/ת על מבוגר, אומר/ת במילים במקום לנתק", "staff": "אומר/ת כעס במילים", "scale": ["עדיין מנתק/ת או פוגע/ת", "שותק/ת", "אומר/ת מילה", "אומר/ת מה כועס", "אומר/ת ומחכה לתיקון"]}], "interventions": [{"id": "i1", "name": "לומר ''אני עדיין כאן''", "what": "משפט קבוע אחרי אירוע קשה, בלי תנאים, ובמילים שהן אמת (למשל ''כל עוד אני עובד/ת כאן'').", "why": "מבוגר שנשאר מלמד שהקשר עמיד.", "freq": "אחרי אירוע קשה", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["אני עדיין כאן, גם אחרי מה שקרה", "כל עוד אני כאן, אני כאן בשבילך", "גם כשכועסים"], "avoid": "לא להבטיח ''תמיד'' אם זה לא נכון"}, {"id": "i2", "name": "להפריד בין התנהגות לקשר", "what": "הגבול הוא על מה שעשה/תה, והקשר לא בסכנה. אומרים את זה במפורש.", "why": "ילד שיודע שהקשר נשאר מקבל גבול בקלות.", "freq": "בכל גבול", "approach": "סמכות חדשה", "targets": ["t2"], "sentences": ["את זה לא מקבלים, ואותך כן", "אכפת לי ממך, ומה שעשית לא בסדר", "אנחנו בסדר"]}, {"id": "i3", "name": "ליזום תיקון כמבוגר", "what": "אחרי אירוע, המבוגר מגיע, מציע משחק או אומר מילה טובה, ולא מחכה שהילד/ה יבוא/תבוא.", "why": "תיקון שבא מהמבוגר מראה שהקשר חשוב לו.", "freq": "אחרי אירוע", "approach": "TBRI", "targets": ["t1"], "sentences": ["באתי לראות מה שלומך", "רוצה לשחק?", "אני עדיין פה"]}, {"id": "i4", "name": "לחזור למה שסיפר/ה גם אחרי ריב", "what": "גם אחרי אירוע קשה, חוזרים לפרט שסיפר/ה, כדי להראות שהקשר לא נמחק.", "why": "חזרה לפרט קטן מראה שהקשר נשאר.", "freq": "אחרי אירוע קשה", "approach": "ARC", "targets": ["t4"], "sentences": ["גם אחרי מה שהיה אתמול, רציתי לשאול על המבחן", "אני זוכר/ת מה סיפרת לי", "זה לא נמחק"]}, {"id": "i5", "name": "לשאול בסקרנות על הבדיקה (בהנחיית המטפלת)", "what": "בשיחה רגועה אומרים בקול מה אולי קורה: אולי אתה/את בודק/ת אם אשאר?", "why": "כשנותנים שם לבדיקה, אפשר לענות עליה.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["אולי אתה/את בודק/ת אם אשאר", "זו שאלה הגיונית", "אני עדיין פה"]}, {"id": "i6", "name": "לקבל כעס במילים", "what": "כשאומר/ת כעס במילים, מקשיבים, מכירים ולא מענישים.", "why": "כעס שמותר לומר לא צריך להתפרץ.", "freq": "בכל פעם", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["אתה/את כועס/ת עליי, ספר/י", "אני מקשיב/ה", "טוב שאמרת"]}, {"id": "i7", "name": "להישאר קרוב ביום קשה", "what": "ביום שהוא/היא בודק/ת הרבה את הקשר, נותנים יותר נוכחות ופחות דרישות.", "why": "נוכחות בזמן קשה עונה על השאלה בלי מילים.", "freq": "בימים קשים", "approach": "TBRI", "targets": ["t3", "t1"], "sentences": ["היום אני קרוב/ה אליך", "אני רואה שקשה", "נעבור את זה"]}, {"id": "i8", "name": "לשמור על תגובה צפויה", "what": "כל המבוגרים מגיבים לבדיקות באותה דרך רגועה, לפי תוכנית המטפלת.", "why": "תגובה צפויה מורידה את הצורך לבדוק.", "freq": "תמיד", "approach": "ARC", "targets": ["t3", "t2"], "sentences": ["כמו תמיד, אני רגוע/ה", "זה לא משנה את הקשר", "ממשיכים"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'קרוב/ה במידה', 'לדעת מה זה קשר בטוח עם מבוגר, ומה סימן שמשהו לא בסדר', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['ARC', 'TBRI', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להבטיח סודיות מלאה, ולא לקיים קשר פרטי עם ילד/ה מחוץ למסגרת", "strengths": ["כנות", "אומץ", "אמון"], "skills": ["גבולות בקשר"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "נגזר מתוכניות מניעה ובטיחות אישית (ללמד מה קשר בטוח ומה סימני אזהרה) ומקודים מקצועיים לצוותים. במסגרות חוץ־ביתיות זו התאמה יישומית; כל חשד מועבר לפי הנוהל."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "מבחין/ה בין קשר בטוח עם מבוגר לבין סימני אזהרה (סודות, מתנות, בידוד)", "staff": "מבחין/ה בין קשר בטוח לסימני אזהרה", "scale": ["עדיין לא מבחין/ה", "מבחין/ה כשמבוגר מראה", "אומר/ת סימן אחד", "אומר/ת כמה סימנים", "מסביר/ה לחבר"]}, {"id": "t2", "text": "יודע/ת שמבוגר לא שומר סוד מסוכן, ובכל זאת משתף/ת", "staff": "משתף/ת גם כשיודע/ת שמבוגר יספר", "scale": ["עדיין לא משתף/ת בכלום", "משתף/ת דברים קטנים", "משתף/ת ושואל/ת מה יקרה", "משתף/ת גם דבר קשה", "משתף/ת מוקדם"]}, {"id": "t3", "text": "מכין/ה מפה של מבוגרים בטוחים בחייו/ה", "staff": "יודע/ת מי המבוגרים הבטוחים שלו/ה", "scale": ["עדיין אין לו/ה מבוגר בטוח", "אומר/ת אחד כשמבוגר שואל", "אומר/ת שניים", "אומר/ת כמה, גם מחוץ למרכז", "פונה אליהם כשצריך"]}, {"id": "t4", "text": "מקבל/ת גבול מקצועי (בלי קשר ברשת פרטית, בלי מתנות אישיות) בלי להיעלב", "staff": "מקבל/ת גבולות מקצועיים", "scale": ["עדיין נעלב/ת או כועס/ת", "מקבל/ת עם הסבר", "מקבל/ת ושואל/ת", "מקבל/ת בשקט", "מבין/ה למה זה שומר עליו/ה"]}, {"id": "t5", "text": "מספר/ת למבוגר כשמבוגר אחר מבקש ממנו/ה סוד או נותן מתנות", "staff": "מספר/ת כשמבוגר מבקש סוד", "scale": ["עדיין שומר/ת סוד כזה", "מרמז/ת", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מספר/ת מיד"]}], "interventions": [{"id": "i1", "name": "לדבר על קשר בטוח מול סימני אזהרה", "what": "שיחה או משחק קלפים לפי מה שהמטפלת אישרה: מה מבוגר בטוח עושה, ומה סימן אזהרה.", "why": "מי שמכיר סימנים מזהה סכנה מוקדם.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t1"], "sentences": ["מה מבוגר בטוח עושה?", "ומה זה סימן אזהרה?", "תמיד אפשר לשאול"]}, {"id": "i2", "name": "לומר מראש ''אני לא שומר/ת סוד מסוכן''", "what": "אומרים בכנות ובתחילת הקשר מה המבוגר חייב להעביר הלאה, ולמה.", "why": "כנות על גבולות הסוד בונה אמון אמיתי.", "freq": "בתחילת הקשר ולפי הצורך", "approach": "ARC", "targets": ["t2"], "sentences": ["אני לא מספר/ת לילדים אחרים מה שסיפרת לי", "אבל אם משהו מסוכן, אני חייב/ת לספר למטפלת", "זה כדי לשמור עליך"], "avoid": "לא להבטיח סודיות מלאה"}, {"id": "i3", "name": "לשמור על גבולות מקצועיים", "what": "בלי קשר ברשתות פרטיות, בלי מתנות אישיות לילד/ה מסוים/ת, בלי פגישות לבד מחוץ למסגרת. הצוות וההנהלה שומרים יחד.", "why": "גבולות ברורים מגינים על הילד ועל הקשר.", "freq": "תמיד", "approach": "ARC", "targets": ["t4"], "sentences": ["אני לא יכול/ה להיות איתך בקשר בטלפון הפרטי", "זה כלל ששומר על כל הילדים", "אבל כאן אני בשבילך"]}, {"id": "i4", "name": "לשמור על חום לצד הגבול", "what": "לצד הגבול: מילה טובה, זמן יחד בתוך המסגרת, וזיכרון של מה שחשוב לו/ה.", "why": "גבול בלי חום מרגיש כמו דחייה.", "freq": "באופן קבוע", "approach": "TBRI", "targets": ["t4"], "sentences": ["אכפת לי ממך", "בוא/י נעשה משהו ביחד פה", "זכרתי שזה חשוב לך"]}, {"id": "i5", "name": "להכין מפת מבוגרים", "what": "מכינים יחד רשימה או מפה של מבוגרים בטוחים, בתוך המסגרת ומחוצה לה.", "why": "מפה של מבוגרים מראה שיש למי לפנות.", "freq": "פעם אחת ומעדכנים", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["מי המבוגרים הבטוחים שלך?", "מי עוד?", "אלה האנשים שלך"]}, {"id": "i6", "name": "להקשיב לחשד ולפעול לפי הנוהל", "what": "אם מספר/ת על מבוגר שמבקש סודות או נותן מתנות, מקשיבים ברוגע ומעבירים מיד למטפלת ולפי הנוהל.", "why": "סודות ומתנות ממבוגר הם סימן לפיתוי.", "freq": "בכל פעם", "approach": "ARC", "targets": ["t5"], "sentences": ["תודה שסיפרת", "עשית בדיוק נכון", "אני צריך/ה לספר כדי לשמור עליך"], "avoid": "לא לחקור ולא לשאול שאלות מנחות"}, {"id": "i7", "name": "להסביר את ההבדל בין הפתעה לסוד", "what": "מסבירים: הפתעה שמחה היא סוד טוב, סוד שמרגיש לא נעים צריך לספר.", "why": "ההבחנה עוזרת לדעת מתי לספר.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t5", "t1"], "sentences": ["הפתעה נגמרת ומשמחת את כולם", "סוד שמרגיש לא נעים, או שמבוגר ביקש לשמור, מספרים", "תמיד אפשר לספר לי"]}, {"id": "i8", "name": "לשבח כשסיפר/ה", "what": "כשסיפר/ה משהו קשה, אומרים שזה היה אמיץ ונכון.", "why": "חיזוק לסיפור מעודד לספר שוב.", "freq": "בכל פעם", "approach": "TBRI", "targets": ["t2", "t5"], "sentences": ["זה היה אמיץ", "טוב שסיפרת", "אתה/את לא בצרות"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'פרידה טובה', 'להיפרד ממבוגר משמעותי שעוזב, ולהשאיר את מה שהיה', array['היקשרות וקשר עם מבוגר']::text[], 'היקשרות וקשר עם מבוגר', array['מעגל הביטחון', 'טיפול נרטיבי', 'TF-CBT', 'ARC', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להיעלם בלי פרידה, ולא להבטיח קשר שלא אושר", "strengths": ["כנות", "תקווה", "אומץ"], "skills": ["התמודדות עם פרידה"], "main": "13-15", "also": ["10-12"], "evidence": {"level": "derived", "note": "תחלופת צוות פוגעת בילדים במסגרות חוץ־ביתיות, ופרידה מתוכננת מומלצת בספרות המקצועית. ההתערבויות נגזרות מהטיפול הנרטיבי ומעגל הביטחון ומהוות התאמה יישומית."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "כשמספרים שמבוגר עוזב, מדבר/ת על מה שמרגיש/ה", "staff": "מדבר/ת על העזיבה של המבוגר", "scale": ["עדיין מתנתק/ת או כועס/ת בלי מילים", "מראה בהתנהגות", "אומר/ת מילה", "מדבר/ת על הרגש", "מדבר/ת גם על מה שהיה טוב"]}, {"id": "t2", "text": "בוחר/ת דרך להיפרד (מכתב, פעילות, שיחה)", "staff": "בוחר/ת דרך להיפרד", "scale": ["עדיין מסרב/ת להיפרד", "מסכים/ה לפרידה קצרה", "בוחר/ת דרך עם עזרה", "בוחר/ת ומתכנן/ת", "מוביל/ה את הפרידה"]}, {"id": "t3", "text": "שומר/ת משהו מהקשר (מכתב, רשימת חוזקות)", "staff": "שומר/ת זיכרון מהקשר", "scale": ["עדיין לא רוצה כלום", "מקבל/ת כשנותנים", "שומר/ת", "חוזר/ת לקרוא", "מספר/ת מה זה אומר לו/ה"]}, {"id": "t4", "text": "בשבועות שאחרי, ממשיך/ה בשגרה ופונה למבוגר אחר", "staff": "ממשיך/ה בשגרה ופונה למבוגר אחר", "scale": ["עדיין מסתגר/ת או בורח/ת", "חוזר/ת לחלק מהשגרה", "חוזר/ת לשגרה", "פונה למבוגר אחר לפעמים", "בונה קשר עם מבוגר אחר"]}, {"id": "t5", "text": "מקשר/ת בין הפרידה לפרידות קודמות, עם המטפלת", "staff": "מדבר/ת עם המטפלת על פרידות", "scale": ["עדיין לא מדבר/ת", "מקשיב/ה", "אומר/ת שזה מזכיר משהו", "מדבר/ת על פרידות קודמות", "מבין/ה מה שונה הפעם"]}], "interventions": [{"id": "i1", "name": "לספר מוקדם ובכנות", "what": "מבוגר שעוזב מספר בעצמו, מוקדם ככל האפשר, למה ומתי.", "why": "פרידה שיודעים עליה היא לא נטישה.", "freq": "כשהעזיבה ידועה", "approach": "מעגל הביטחון", "targets": ["t1"], "sentences": ["רציתי שתשמע/תשמעי ממני", "אני עוזב/ת בעוד חודש", "זה לא בגללך"], "avoid": "לא להיעלם בלי פרידה"}, {"id": "i2", "name": "לבחור יחד טקס פרידה", "what": "הנער/ה בוחר/ת: מכתב הדדי, תמונה משותפת לפי הנוהל, פעילות אחרונה.", "why": "פרידה שבחרתי סוגרת בכבוד.", "freq": "לקראת העזיבה", "approach": "טיפול נרטיבי", "targets": ["t2"], "sentences": ["איך תרצה/תרצי שניפרד?", "מה חשוב לך?", "נעשה את זה ביחד"]}, {"id": "i3", "name": "לכתוב מה נשאר", "what": "המבוגר העוזב כותב לנער/ה מה הוא רואה בו/ה: חוזקות וזיכרונות.", "why": "מילים שנשארות ממשיכות לחזק.", "freq": "לקראת העזיבה", "approach": "טיפול נרטיבי", "targets": ["t3"], "sentences": ["כתבתי לך מה אני רואה בך", "זה שלך לשמור", "אלה דברים אמיתיים"]}, {"id": "i4", "name": "לעבד פרידות קודמות (בהנחיית המטפלת)", "what": "המטפלת עובדת עם הנער/ה על פרידות מהעבר שהפרידה הזו מזכירה.", "why": "פרידה חדשה מעוררת פרידות ישנות.", "freq": "לפי תוכנית המטפלת", "approach": "TF-CBT", "targets": ["t5"], "sentences": ["זה מזכיר לך משהו?", "נדבר על זה עם המטפלת", "הפעם זה שונה, כי אמרו לך"]}, {"id": "i5", "name": "לשים לב בשבועות שאחרי", "what": "שמים לב לסימני מצוקה: הסתגרות, בריחה, פגיעה עצמית, ומעבירים למטפלת לפי הנוהל.", "why": "התקופה שאחרי פרידה היא תקופת סיכון.", "freq": "בשבועות שאחרי", "approach": "ARC", "targets": ["t4"], "sentences": ["איך אתה/את מאז העזיבה?", "אני שם/ה לב שקשה", "אני כאן"]}, {"id": "i6", "name": "לחבר למבוגר אחר", "what": "מבוגר אחר מהצוות לוקח חלק גדול יותר בקשר, בהדרגה ובלי להחליף.", "why": "קשר חדש עוזר לא להישאר לבד.", "freq": "אחרי העזיבה", "approach": "מעגל הביטחון", "targets": ["t4"], "sentences": ["אני לא מחליף/ה אף אחד", "אבל אני כאן בשבילך", "נבנה את הקשר שלנו"]}, {"id": "i7", "name": "לומר את האמת על קשר אחרי", "what": "אומרים רק מה שאושר לגבי קשר אחרי העזיבה.", "why": "הבטחה שלא מתקיימת פוגעת שוב.", "freq": "תמיד", "approach": "ARC", "targets": ["t1"], "sentences": ["לא בטוח שנהיה בקשר", "אבל אזכור אותך", "מה שהיה בינינו אמיתי"], "avoid": "לא להבטיח קשר שלא אושר"}, {"id": "i8", "name": "לשמור על שגרה", "what": "אחרי העזיבה ממשיכים בשגרה ובפעילויות הקבועות, עם יותר נוכחות.", "why": "שגרה מחזיקה כשמשהו נשבר.", "freq": "אחרי העזיבה", "approach": "TBRI", "targets": ["t4"], "sentences": ["ממשיכים כרגיל", "רוצה להצטרף לפעילות?", "אנחנו פה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הלילה הראשון', 'לעבור את השעות והלילות הראשונים בתחושה שמישהו שומר', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['מעגל הביטחון', 'NMT', 'ARC', 'ויסות חושי', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להתחיל בקליטה בירוקרטית, לא להמציא הסבר, ולא לסכם ''מסתגל/ת יפה'' רק כי הילד/ה שקט/ה", "strengths": ["אומץ", "אמון", "שקט פנימי"], "skills": ["פנייה למבוגר"], "main": "2-5", "also": [], "evidence": {"level": "derived", "note": "ילדים מתארים את הכניסה לסידור כבלבול וחוסר מידע. עקרונות הקליטה כאן (מבוגר אחד, צרכים קודם, חפץ מוכר) נגזרים מ-TIC ו-NMT; זו התאמה יישומית שלא נבדקה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "בשעות הראשונות, נשאר/ת קרוב/ה למבוגר המקבל ומקבל/ת ממנו עזרה", "staff": "נשאר/ת קרוב למבוגר המקבל", "scale": ["עדיין קופא/ת או מתנגד/ת לכל מגע", "מסתכל/ת על המבוגר", "מקבל/ת אוכל או שתייה ממנו", "נשאר/ת לידו ומקבל/ת עזרה", "פונה אליו כשצריך"]}, {"id": "t2", "text": "אוכל/ת, שותה ונח/ה ביום הראשון", "staff": "אוכל/ת ושותה ביום הראשון", "scale": ["עדיין לא אוכל/ת ולא שותה", "שותה מעט", "אוכל/ת מעט", "אוכל/ת ונח/ה", "אוכל/ת ונח/ה כמעט כרגיל"]}, {"id": "t3", "text": "מחזיק/ה את החפץ המוכר שהגיע איתו/ה ונרגע/ת בעזרתו", "staff": "נרגע/ת עם החפץ שהביא/ה", "scale": ["עדיין אין חפץ או לא נרגע/ת", "מחזיק/ה אותו", "מחפש/ת אותו כשקשה", "נרגע/ת איתו", "נרגע/ת איתו גם בלילה"]}, {"id": "t4", "text": "מראה רגשות (בכי, כעס, שאלה) ולא רק שקט וציות", "staff": "מראה רגש ולא רק שקט", "scale": ["עדיין שקט/ה מאוד וקפוא/ה", "מראה רגש לרגע", "בוכה או כועס/ת ונרגע/ת", "שואל/ת שאלות", "משחק/ת ומראה רגשות שונים"]}, {"id": "t5", "text": "בלילות הראשונים, ישן/ה חלק מהלילה עם מבוגר בהישג יד", "staff": "ישן/ה בלילות הראשונים", "scale": ["עדיין לא נרדם/ת", "נרדם/ת מאוחר מאוד", "ישן/ה חלק מהלילה", "ישן/ה רוב הלילה", "ישן/ה כמעט כרגיל"]}], "interventions": [{"id": "i1", "name": "לתת מבוגר מקבל אחד", "what": "מבוגר אחד מקבל את הילד/ה, ובשעות הראשונות רק הוא מטפל בו/ה ומציג את עצמו בשם.", "why": "מבוגר אחד מוכר מוריד את הבלבול.", "freq": "בשעות הראשונות", "approach": "מעגל הביטחון", "targets": ["t1"], "sentences": ["שלום, אני דנה, אני איתך היום", "אני נשאר/ת לידך", "אני פה"]}, {"id": "i2", "name": "לדאוג לצרכים קודם", "what": "אוכל, שתייה, שירותים, בגדים נקיים ומקום לנוח. בדיקות ושאלות מחכות.", "why": "גוף שקיבל מה שצריך יכול להירגע.", "freq": "בשעות הראשונות", "approach": "NMT", "targets": ["t2"], "sentences": ["אתה/את רעב/ה?", "הנה מים", "אפשר לנוח פה"], "avoid": "לא להתחיל בטפסים ובשאלות"}, {"id": "i3", "name": "לשמור על החפץ המוכר", "what": "שומרים כל חפץ שהגיע איתו/ה, גם אם מלוכלך. מכבסים בתיאום ומחזירים באותו יום.", "why": "חפץ מהבית הוא חוט של ביטחון.", "freq": "תמיד", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["זה שלך, הוא נשאר איתך", "נשמור עליו", "הנה, חזר נקי"], "avoid": "לא לזרוק או לקחת חפץ מוכר"}, {"id": "i4", "name": "לומר משפט הסבר אחד (בהנחיית המטפלת)", "what": "המטפלת מנסחת משפט קצר ואמיתי על למה הוא/היא כאן, וכל המבוגרים אומרים אותו.", "why": "משפט אחד ואמיתי מרגיע יותר מהרבה מילים.", "freq": "בכל שאלה", "approach": "ARC", "targets": ["t4"], "sentences": ["אתה/את פה כדי שישמרו עליך", "המבוגרים מטפלים בזה", "זה לא באשמתך"], "avoid": "לא להמציא, כמו ''המשפחה בחופש''"}, {"id": "i5", "name": "לשמור על סביבה שקטה", "what": "חדר עם מעט גירויים, אור לילה, ומבוגר בהישג יד. בלי הרבה ילדים ופנים חדשות בבת אחת.", "why": "פחות גירויים, פחות הצפה.", "freq": "בימים הראשונים", "approach": "ויסות חושי", "targets": ["t5", "t1"], "sentences": ["פה שקט", "האור הקטן דולק", "אני ממש קרוב/ה"]}, {"id": "i6", "name": "ללמוד את הילד/ה ולרשום", "what": "רושמים מה מרגיע, מה אוכל/ת ואיך נרדם/ת, ומעבירים לכרטיס כדי שכל משמרת תדע.", "why": "מה שלמדנו לא הולך לאיבוד בין משמרות.", "freq": "בימים הראשונים", "approach": "ARC", "targets": ["t2", "t5"], "sentences": ["מה אתה/את אוהב/ת לאכול?", "ככה נוח לך לישון?", "אני זוכר/ת"]}, {"id": "i7", "name": "לשים לב לקפיאה", "what": "אם ילד/ה שקט/ה מאוד, צייתן/ית מדי, לא בוכה ולא משחק/ת, מספרים למטפלת.", "why": "שקט מוחלט יכול להיות קפיאה, לא הסתגלות.", "freq": "בימים הראשונים", "approach": "ARC", "targets": ["t4"], "sentences": ["מותר לבכות כאן", "אפשר לשאול אותי הכל", "אני כאן איתך"], "avoid": "לא לסכם ''מסתגל/ת יפה'' רק כי שקט/ה"}, {"id": "i8", "name": "להיות בהישג יד בלילה", "what": "בלילות הראשונים מבוגר נשאר קרוב, בודק הרבה ומגיע מהר.", "why": "לילה ראשון במקום זר הוא הכי מפחיד.", "freq": "בלילות הראשונים", "approach": "TBRI", "targets": ["t5"], "sentences": ["בלילה הראשון אני נשאר/ת קרוב/ה", "אם תקרא/י, אני שומע/ת", "הנה אני"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מה קורה עכשיו', 'לדעת מה ידוע ומה לא, בשבועות הראשונים', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['ARC', 'NMT', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא לסמן ''אולי'' ולא להבטיח ביקור לפני שנקבע", "strengths": ["אמון", "גמישות", "סקרנות"], "skills": ["התמודדות עם אי ודאות"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "צפיות היא עקרון מרכזי בטיפול מותאם טראומה. סימון רק של מה שנקבע בוודאות, ומעט כללים בהתחלה, הם התאמה יישומית למרכזי חירום."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "מסתכל/ת בלוח המפגשים עם המשפחה ומקבל/ת את מה שמסומן", "staff": "בודק/ת בלוח מתי פוגשים את המשפחה", "scale": ["עדיין שואל/ת בבהלה כל הזמן", "נרגע/ת כשמראים בלוח", "מצביע/ה על הלוח", "בודק/ת לבד", "מחכה בשקט לתאריך"]}, {"id": "t2", "text": "כשאין עדיין מועד, מקבל/ת את התשובה ''עוד לא יודעים''", "staff": "מקבל/ת ''עוד לא יודעים''", "scale": ["עדיין מתפרק/ת", "בוכה ונרגע/ת עם מבוגר", "מתלונן/ת ומקבל/ת", "מקבל/ת", "שואל/ת מתי ידעו"]}, {"id": "t3", "text": "מכיר/ה ושומר/ת על שלושת כללי הבטיחות", "staff": "שומר/ת על שלושת הכללים", "scale": ["עדיין לא מכיר/ה", "חוזר/ת אחרי מבוגר", "שומר/ת עם תזכורת", "שומר/ת לבד", "מזכיר/ה לחבר"]}, {"id": "t4", "text": "משתתף/ת בשגרת היום יותר בכל שבוע", "staff": "משתתף/ת יותר בשגרה", "scale": ["עדיין לא משתתף/ת", "משתתף/ת בחלק קטן", "משתתף/ת בחצי", "משתתף/ת ברובה", "משתתף/ת כרגיל"]}, {"id": "t5", "text": "חוזר/ת על המשפט הקבוע שמסביר למה הוא/היא כאן", "staff": "יודע/ת את המשפט למה הוא/היא כאן", "scale": ["עדיין לא יודע/ת", "מקשיב/ה כשאומרים", "חוזר/ת על חלק", "חוזר/ת על כולו", "שואל/ת שאלה נוספת"]}], "interventions": [{"id": "i1", "name": "לסמן בלוח רק מה שבטוח (בהנחיית המטפלת)", "what": "בלוח המפגשים מסמנים רק מה שנקבע בוודאות. אם אין מועד, אומרים שעוד לא יודעים.", "why": "הבטחה שלא מתקיימת פוגעת יותר מ''לא יודעים''.", "freq": "בכל שינוי", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["פה מסומן מתי תראה/תראי את המשפחה", "את זה עוד לא יודעים", "כשנדע, נספר לך"], "avoid": "לא לסמן ''אולי'' ולא להבטיח"}, {"id": "i2", "name": "ללמד רק שלושה כללים", "what": "בשבוע הראשון מלמדים שלושה כללי בטיחות בלבד, בתמונות: נשארים ליד מבוגר, ידיים שומרות, קוראים למבוגר כשצריך.", "why": "מעט כללים נקלטים, הרבה כללים מפחידים.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t3"], "sentences": ["אצלנו יש שלושה כללים", "הנה בתמונה", "את השאר נלמד לאט"]}, {"id": "i3", "name": "לחזור על משפט ההסבר (בהנחיית המטפלת)", "what": "כל הצוות חוזר על אותו משפט קצר שהמטפלת ניסחה, בכל שאלה.", "why": "תשובה זהה מכל מבוגר בונה ביטחון.", "freq": "בכל שאלה", "approach": "ARC", "targets": ["t5"], "sentences": ["אתה/את פה כדי שישמרו עליך", "המבוגרים מטפלים בזה", "זה לא באשמתך"]}, {"id": "i4", "name": "להוסיף שגרה בהדרגה", "what": "בכל שבוע מוסיפים חלק מהשגרה: קודם אוכל ושינה, אחר כך פעילויות.", "why": "שגרה הדרגתית לא מציפה.", "freq": "בשבועות הראשונים", "approach": "NMT", "targets": ["t4"], "sentences": ["השבוע נצטרף גם לשיר בבוקר", "לאט לאט", "הצטרפת, יופי"]}, {"id": "i5", "name": "לתת לשאול שוב ושוב", "what": "עונים בסבלנות על אותה שאלה פעמים רבות, באותה תשובה.", "why": "חזרה על שאלה היא דרך להירגע.", "freq": "בכל שאלה", "approach": "TBRI", "targets": ["t2", "t5"], "sentences": ["שאלה טובה", "כמו שאמרתי, עוד לא יודעים", "אפשר לשאול כמה שרוצים"]}, {"id": "i6", "name": "להכין לפני מפגש עם המשפחה", "what": "יום לפני ובבוקר מספרים מה יקרה, איפה ועם מי, ומה אחרי.", "why": "מפגש מוכן מפחיד פחות.", "freq": "לפני כל מפגש", "approach": "ARC", "targets": ["t1"], "sentences": ["מחר תראה/תראי את המשפחה", "זה יהיה בחדר הזה", "אחר כך חוזרים לפה"]}, {"id": "i7", "name": "להראות מה נשאר קבוע", "what": "מראים מה קבוע כל יום: מי בבוקר, מתי אוכלים, מה לפני השינה.", "why": "מה שקבוע הוא עוגן כשהרבה לא ידוע.", "freq": "כל יום", "approach": "NMT", "targets": ["t4", "t2"], "sentences": ["כל בוקר יש שיר", "כל ערב סיפור", "את זה אתה/את כבר יודע/ת"]}, {"id": "i8", "name": "לעדכן את המטפלת", "what": "שאלות שחוזרות או פחד גדול סביב המשפחה מעבירים למטפלת.", "why": "המטפלת יודעת מה אפשר לומר ומתי.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t2"], "sentences": ["נשאל את המטפלת", "היא יודעת מה אפשר לספר", "אני כאן איתך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'למה אני פה', 'לקבל הסבר כן על למה הגעתי, ולשאול את מה שמטריד אותי', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['ARC', 'TBRI', 'טיפול נרטיבי', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להוסיף פרטים, לא לשער, לא לדבר רע על המשפחה ולא להמציא תשובה מרגיעה", "strengths": ["סקרנות", "כנות", "אומץ"], "skills": ["שאילת שאלות"], "main": "6-9", "also": [], "evidence": {"level": "derived", "note": "ילדים בסידור חוץ־ביתי מתארים שחסר להם הסבר. עבודה על סיפור הכניסה (Life Story) נבדקה במידה מוגבלת; כאן ההסבר בידי המטפלת והצוות שומר עליו. התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "אומר/ת במילים שלו/ה את ההסבר הקצר למה הוא/היא כאן", "staff": "יודע/ת למה הוא/היא כאן במילים שלו/ה", "scale": ["עדיין לא יודע/ת", "מקשיב/ה כשאומרים", "חוזר/ת על חלק", "אומר/ת במילים שלו/ה", "אומר/ת ושואל/ת עוד"]}, {"id": "t2", "text": "שואל/ת שאלות במקום לשמור אותן בפנים", "staff": "שואל/ת את מה שמטריד", "scale": ["עדיין לא שואל/ת", "שואל/ת דרך התנהגות", "שם/ה שאלה בקופסה", "שואל/ת מבוגר", "שואל/ת ומקבל/ת את התשובה"]}, {"id": "t3", "text": "אומר/ת שזה לא באשמתו/ה, או מסכים/ה כשאומרים", "staff": "מבין/ה שזה לא באשמתו/ה", "scale": ["עדיין אומר/ת שהוא/היא אשם/ה", "שותק/ת כשאומרים", "מסכים/ה כשאומרים", "אומר/ת בעצמו/ה", "אומר/ת גם כשקשה"]}, {"id": "t4", "text": "יודע/ת מה קורה עם מה שהשאיר/ה מאחור (אחים, חיה, בית ספר)", "staff": "יודע/ת מה עם מה שהשאיר/ה", "scale": ["עדיין לא יודע/ת ודואג/ת", "שואל/ת שוב ושוב", "יודע/ת חלק", "יודע/ת ונרגע/ת", "שואל/ת על עדכון"]}, {"id": "t5", "text": "משתמש/ת בספרון הכניסה שלו/ה כדי לספר על עצמו/ה", "staff": "מראה את ספרון הכניסה", "scale": ["עדיין לא מתעניין/ת", "מסתכל/ת עם מבוגר", "מראה עמוד", "מראה ומספר/ת", "מוסיף/ה בעצמו/ה"]}], "interventions": [{"id": "i1", "name": "לשמור על הסבר אחד (בהנחיית המטפלת)", "what": "המטפלת נותנת את ההסבר הראשון ושומרת אותו במערכת, וכל הצוות משתמש באותן מילים.", "why": "הסבר אחד מכל המבוגרים מונע בלבול.", "freq": "תמיד", "approach": "ARC", "targets": ["t1"], "sentences": ["כמו שהמטפלת אמרה לך", "אתה/את כאן כדי שישמרו עליך", "יש עוד שאלות?"], "avoid": "לא להוסיף פרטים או לשער"}, {"id": "i2", "name": "לומר ''זה לא באשמתך'' (בהנחיית המטפלת)", "what": "משפט שהמטפלת מאשרת, וכל הצוות חוזר עליו, במיוחד כשמאשים/ה את עצמו/ה.", "why": "ילדים רבים חושבים שהם אשמים.", "freq": "לפי הצורך", "approach": "TBRI", "targets": ["t3"], "sentences": ["זה לא באשמתך", "ילדים לא אשמים בזה", "המבוגרים צריכים לפתור"]}, {"id": "i3", "name": "לתת קופסת שאלות", "what": "כותב/ת או מצייר/ת שאלות ושם/ה בקופסה, והמטפלת עונה בפגישה.", "why": "שאלה שאפשר לשים בקופסה לא צריכה לחכות לרגע מתאים.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t2"], "sentences": ["יש שאלה? אפשר לשים בקופסה", "המטפלת תענה", "כל שאלה מותרת"]}, {"id": "i4", "name": "לענות ''אני לא יודע/ת, ואבדוק''", "what": "כשאין תשובה, אומרים בכנות ומעבירים למטפלת.", "why": "כנות מרגיעה יותר מתשובה מומצאת.", "freq": "בכל שאלה", "approach": "ARC", "targets": ["t2", "t4"], "sentences": ["אני לא יודע/ת", "אבדוק עם המטפלת", "אחזור אליך"], "avoid": "לא להמציא תשובה מרגיעה"}, {"id": "i5", "name": "להכין ספרון כניסה (בהנחיית המטפלת)", "what": "ספרון עם תמונות: איפה הייתי, למה באתי, מי פה, מה הלאה.", "why": "סיפור מסודר עוזר להבין מה קורה.", "freq": "בשבועות הראשונים", "approach": "טיפול נרטיבי", "targets": ["t5", "t1"], "sentences": ["בוא/י נוסיף עמוד", "מי פה בתמונה?", "זה הסיפור שלך"]}, {"id": "i6", "name": "לעדכן על מה שנשאר מאחור (בהנחיית המטפלת)", "what": "המטפלת מעדכנת מה קורה עם אחים, חיית מחמד, בית ספר וחפצים.", "why": "דאגה לאחרים לא נרגעת בלי מידע.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t4"], "sentences": ["המטפלת בודקת מה עם האחים", "נספר לך מה שידוע", "אפשר לשאול שוב"]}, {"id": "i7", "name": "לשים לב כשמספר/ת על פגיעה", "what": "שאלות על ''למה'' יכולות להוביל לגילוי של פגיעה. מקשיבים ברוגע ומעבירים מיד לפי הנוהל.", "why": "גילוי צריך תגובה נכונה מהרגע הראשון.", "freq": "בכל שיחה", "approach": "ARC", "targets": ["t2"], "sentences": ["תודה שסיפרת לי", "עשית נכון", "אני צריך/ה לספר כדי לשמור עליך"], "avoid": "לא לשאול שאלות מנחות ולא להבטיח סוד"}, {"id": "i8", "name": "לא לדבר רע על המשפחה", "what": "מדברים על המשפחה בכבוד, גם כשקשה.", "why": "ביקורת על המשפחה פוגעת בילד.", "freq": "תמיד", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["המשפחה שלך חשובה", "אפשר להרגיש הרבה דברים", "אני כאן לשמוע"], "avoid": "לא להאשים את המשפחה מול הילד/ה"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'להתחבר בשבוע הראשון', 'למצוא חבר ומשהו שאני טוב/ה בו כבר בימים הראשונים', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['ARC', 'DDP/PACE', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא לבחור כמלווה ילד/ה שבסיכון להשפיע, ולא להעמיס הרבה כללים ופעילויות בבת אחת", "strengths": ["פתיחות", "חברות", "סקרנות"], "skills": ["פנייה לחבר"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "תמיכת עמיתים וחוויית הצלחה מוקדמת נגזרות ממחקר על הסתגלות למסגרות חדשות ומ-ARC (מסוגלות). במרכזי חירום זו התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "משתתף/ת בפעילות עם החבר המלווה", "staff": "משתתף/ת עם החבר המלווה", "scale": ["עדיין לא מצטרף/ת", "מסתכל/ת", "מצטרף/ת עם מבוגר", "מצטרף/ת עם החבר", "מצטרף/ת גם לילדים אחרים"]}, {"id": "t2", "text": "משתתף/ת בפעילות שהוא/היא טוב/ה בה ומראה הנאה", "staff": "נהנה/נהנית בפעילות שטוב/ה בה", "scale": ["עדיין לא מצטרף/ת", "מנסה", "משתתף/ת", "נהנה/נהנית", "מבקש/ת שוב"]}, {"id": "t3", "text": "ממלא/ת עם מבוגר את שאלון ''על עצמי''", "staff": "מספר/ת על עצמו/ה בשאלון", "scale": ["עדיין מסרב/ת", "עונה על שאלה אחת", "עונה על חלק", "עונה על רובו", "מוסיף/ה דברים מיוזמתו/ה"]}, {"id": "t4", "text": "יודע/ת את שמות הילדים בקבוצה ומישהו לפנות אליו", "staff": "יודע/ת שמות של ילדים", "scale": ["עדיין לא יודע/ת", "יודע/ת שם אחד", "יודע/ת כמה", "פונה לילד", "יש לו/ה חבר"]}, {"id": "t5", "text": "אומר/ת דבר אחד טוב על המקום או על היום", "staff": "אומר/ת משהו טוב על היום", "scale": ["עדיין רק דברים קשים", "שותק/ת", "מסכים/ה כשמבוגר מזכיר", "אומר/ת לבד", "מחכה לפעילות מחר"]}], "interventions": [{"id": "i1", "name": "להצמיד חבר מלווה", "what": "ילד ותיק ורגיש מהקבוצה מלווה את החדש/ה בכמה פעילויות, באישור הצוות ובפיקוח.", "why": "חבר ראשון מקל על הכניסה לקבוצה.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["זה יוני, הוא יראה לך", "רוצה להצטרף אליו?", "איך היה איתו?"], "avoid": "לא לבחור מלווה שבסיכון להשפיע"}, {"id": "i2", "name": "לתת הצלחה ראשונה", "what": "פעילות שהוא/היא טוב/ה בה (כדור, ציור, בישול) כבר בימים הראשונים.", "why": "הצלחה מוקדמת אומרת: יש לי מקום פה.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t2"], "sentences": ["שמעתי שאתה/את אוהב/ת כדורגל", "בוא/י נשחק", "איזה יופי, אתה/את טוב/ה בזה"]}, {"id": "i3", "name": "למלא שאלון ''על עצמי''", "what": "שאלון קצר וחווייתי: מה אוהב/ת לאכול, מה מרגיע, מה לא אוהב/ת. התוצאה עוברת לכרטיס.", "why": "כשהצוות יודע מה חשוב לילד, הוא מרגיש שרואים אותו.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t3"], "sentences": ["מה הכי כיף לך?", "מה מרגיע אותך?", "נכתוב את זה לכל הצוות"]}, {"id": "i4", "name": "להציג את הקבוצה", "what": "משחק שמות קצר בקבוצה, וכל ילד אומר משהו שהוא אוהב.", "why": "שמות ותחביבים יוצרים נקודות חיבור.", "freq": "ביום הראשון או השני", "approach": "ARC", "targets": ["t4"], "sentences": ["בוא/י נכיר את כולם", "מי עוד אוהב כדורגל?", "יש לך שותף"]}, {"id": "i5", "name": "להתחיל בכללי בטיחות בלבד", "what": "מלמדים רק את כללי הבטיחות ולמה, ואת השאר בהדרגה.", "why": "מעט כללים בהתחלה מורידים עומס.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t5"], "sentences": ["יש רק כמה כללים חשובים", "את השאר נלמד לאט", "שאלות?"]}, {"id": "i6", "name": "לשאול מה היה טוב", "what": "בערב שואלים שאלה אחת: מה היה טוב היום?", "why": "שאלה על הטוב עוזרת לראות גם אותו.", "freq": "כל ערב בשבוע הראשון", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["מה היה טוב היום?", "ומה היה קשה?", "מחר יש כדורגל בחצר"]}, {"id": "i7", "name": "לבדוק את החבר המלווה", "what": "בודקים עם שני הילדים איך הולך, ומחליפים אם לא מתאים.", "why": "ליווי צריך להתאים לשניהם.", "freq": "כמה פעמים בשבוע הראשון", "approach": "CPS", "targets": ["t1"], "sentences": ["איך הולך עם יוני?", "רוצה להמשיך איתו?", "תודה שעזרת לו"]}, {"id": "i8", "name": "לשבח הצטרפות", "what": "כל הצטרפות, גם קטנה, מקבלת מילה טובה.", "why": "חיזוק מוקדם מעודד להמשיך.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["הצטרפת, יופי", "זה לא קל ביום הראשון", "שמח/ה שאתה/את פה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הקול שלי בקליטה', 'להשתתף בהחלטות עליי כבר מהיום הראשון', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['ARC', 'DDP/PACE', 'TBRI', 'CPS']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להציע בחירה שלא באמת קיימת, ולא לשתף בבית הספר פרטים בלי הסכמה ובלי המטפלת", "strengths": ["אחריות", "כנות", "עצמאות"], "skills": ["קבלת החלטות"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "שיתוף ילדים בהחלטות (עקרון מאמנת האו\"ם לזכויות הילד) קשור לתחושת שליטה ושביעות רצון במחקרי סידור חוץ־ביתי. הפרקטיקה כאן היא התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "ממלא/ת כרטיס היכרות ''מה חשוב לדעת עליי''", "staff": "ממלא/ת כרטיס היכרות", "scale": ["עדיין מסרב/ת", "עונה במילה", "ממלא/ת חלק", "ממלא/ת את כולו", "מעדכן/ת כשמשהו משתנה"]}, {"id": "t2", "text": "אומר/ת מה הכי מדאיג אותו/ה", "staff": "אומר/ת מה הכי מדאיג", "scale": ["עדיין לא אומר/ת", "רומז/ת", "אומר/ת כששואלים", "אומר/ת מיוזמתו/ה", "שואל/ת מה עושים עם זה"]}, {"id": "t3", "text": "מסדר/ת לעצמו/ה מקום אישי ושומר/ת עליו", "staff": "מסדר/ת ושומר/ת מקום אישי", "scale": ["עדיין לא מתעניין/ת", "מסדר/ת עם מבוגר", "מסדר/ת לבד", "שומר/ת עליו", "מוסיף/ה תמונות ודברים שלו/ה"]}, {"id": "t4", "text": "שומע/ת את התוכנית ואומר/ת מה דעתו/ה", "staff": "אומר/ת מה דעתו/ה על התוכנית", "scale": ["עדיין לא משתתף/ת", "מקשיב/ה", "אומר/ת מילה", "אומר/ת דעה", "מציע/ה שינוי"]}, {"id": "t5", "text": "מתכנן/ת עם מבוגר מה לומר בבית הספר", "staff": "מתכנן/ת מה לומר בבית הספר", "scale": ["עדיין נמנע/ת מלדבר על זה", "מקשיב/ה לתוכנית", "בוחר/ת משפט", "מתרגל/ת", "משתמש/ת בבית הספר"]}], "interventions": [{"id": "i1", "name": "למלא כרטיס היכרות", "what": "מה חשוב לדעת עליי: תחביבים, אוכל, מה מרגיע, מה מפחיד, מה אסור לעשות לי. הכרטיס עובר לצוות.", "why": "כרטיס בכתב ידי אומר שהדעה שלי נשמעת.", "freq": "בשבוע הראשון", "approach": "ARC", "targets": ["t1"], "sentences": ["מה חשוב שנדע עליך?", "אתה/את כותב/ת, אני רק עוזר/ת", "הצוות יקרא את זה"]}, {"id": "i2", "name": "לשאול מה הכי מדאיג", "what": "שאלה אחת פתוחה בימים הראשונים, ומעבירים את התשובה למטפלת.", "why": "דאגה שנאמרת אפשר לטפל בה.", "freq": "בימים הראשונים", "approach": "DDP/PACE", "targets": ["t2"], "sentences": ["מה הכי מדאיג אותך עכשיו?", "תודה שסיפרת", "נעביר את זה למטפלת"]}, {"id": "i3", "name": "לסדר מקום אישי", "what": "מסדרים יחד ארון, מגירה שננעלת ומקום לתמונות.", "why": "מקום משלי הוא בסיס בטוח.", "freq": "ביום הראשון והשני", "approach": "TBRI", "targets": ["t3"], "sentences": ["איפה תרצה/תרצי לשים את הדברים?", "המגירה הזו ננעלת", "זה המקום שלך"]}, {"id": "i4", "name": "לשתף בתכנון (בהנחיית המטפלת)", "what": "הילד/ה שומע/ת את התוכנית שנבנית ואומר/ת מה דעתו/ה, והדעה נרשמת.", "why": "מי שהשתתף/ה בתכנון משתף/ת פעולה עם התוכנית.", "freq": "בתכנון ובעדכונים", "approach": "CPS", "targets": ["t4"], "sentences": ["זו התוכנית שאנחנו חושבים עליה", "מה דעתך?", "רשמנו את מה שאמרת"]}, {"id": "i5", "name": "לתכנן את בית הספר", "what": "בתיאום עם המטפלת, מתכננים מה לומר בבית הספר ומי יודע מה.", "why": "שליטה על הסיפור שלי מגינה מפני בושה.", "freq": "לפני בית הספר", "approach": "CPS", "targets": ["t5"], "sentences": ["מה תרצה/תרצי שיידעו בבית הספר?", "אפשר לומר רק: אני גר/ה עכשיו במקום אחר", "מי עוד יודע?"], "avoid": "לא לשתף פרטים בלי הסכמה"}, {"id": "i6", "name": "לתת בחירות אמיתיות", "what": "בחירות קטנות שבאמת קיימות: מיטה, שעת מקלחת, פעילות.", "why": "בחירה אמיתית בונה אמון, בחירה מזויפת הורסת.", "freq": "לאורך היום", "approach": "TBRI", "targets": ["t3", "t4"], "sentences": ["איזו מיטה תעדיף/תעדיפי?", "מתי נוח לך להתקלח?", "בחרת, ככה נעשה"], "avoid": "לא להציע בחירה שלא באמת קיימת"}, {"id": "i7", "name": "להסביר מה בידיו/ה ומה לא", "what": "מסבירים בכנות מה הוא/היא יכול/ה להחליט, ומה מחליטים אחרים ולמה.", "why": "לדעת את הגבולות מוריד תסכול.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t4"], "sentences": ["את זה אתה/את מחליט/ה", "את זה מחליט בית המשפט", "ואת זה נחליט ביחד"]}, {"id": "i8", "name": "לבדוק שהקול נשמע", "what": "חוזרים אחרי כמה ימים ומראים מה השתנה בעקבות מה שאמר/ה.", "why": "לראות שהדעה השפיעה מעודד לדבר שוב.", "freq": "בשבועות הראשונים", "approach": "CPS", "targets": ["t1", "t4"], "sentences": ["אמרת שקשה לך עם הרעש", "אז העברנו אותך לחדר שקט יותר", "מה עוד?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'בין כאן לשם', 'לעבור את התקופה במרכז חירום כנער/ה, עם כבוד, מידע וקשר למה שחשוב לי', array['קליטה וימים ראשונים']::text[], 'קליטה וימים ראשונים', array['ARC', 'TBRI', 'DDP/PACE', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 1, "avoid": "לא להבטיח תוצאה, ולא לקחת טלפון כעונש", "strengths": ["עצמאות", "כנות", "תקווה"], "skills": ["התמודדות עם אי ודאות"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "נגזר ממחקרים על חוויית בני נוער בסידור חוץ־ביתי (חוסר מידע, אובדן שליטה, ניתוק מקשרים) ומעקרונות TIC ו-ARC. התאמה יישומית למרכזי חירום."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "יודע/ת מה ידוע ומה עוד לא לגבי ההמשך, ושואל/ת כשיש שאלה", "staff": "יודע/ת מה ידוע ושואל/ת", "scale": ["עדיין לא שואל/ת או מתפרץ/ת", "שואל/ת בכעס", "שואל/ת ומקשיב/ה", "יודע/ת מה ידוע", "שואל/ת על עדכונים בשקט"]}, {"id": "t2", "text": "שומר/ת על דבר אחד מהחיים הקודמים (בית ספר, חוג, תחביב)", "staff": "שומר/ת על משהו מהחיים הקודמים", "scale": ["עדיין התנתק/ה מהכל", "מדבר/ת על זה", "ממשיך/ה חלקית", "ממשיך/ה באופן קבוע", "ממשיך/ה ונהנה/נהנית"]}, {"id": "t3", "text": "מכיר/ה ושומר/ת את כללי הטלפון והקשר", "staff": "שומר/ת על כללי הטלפון", "scale": ["עדיין לא מקבל/ת את הכללים", "מקבל/ת עם ויכוח", "שומר/ת עם תזכורת", "שומר/ת לבד", "מבין/ה למה הם קיימים"]}, {"id": "t4", "text": "משתמש/ת בבחירות ובפרטיות שניתנו לו/ה באחריות", "staff": "משתמש/ת בפרטיות באחריות", "scale": ["עדיין לא", "משתמש/ת עם הרבה תזכורות", "משתמש/ת ברוב הזמן", "משתמש/ת באחריות", "מבקש/ת עוד ומקבל/ת"]}, {"id": "t5", "text": "מדבר/ת עם מבוגר על מה מרגיש/ה לגבי התקופה כאן", "staff": "מדבר/ת על התקופה כאן", "scale": ["עדיין מסתגר/ת", "אומר/ת מילה", "מדבר/ת כששואלים", "מדבר/ת מיוזמתו/ה", "מדבר/ת גם על מה שטוב"]}], "interventions": [{"id": "i1", "name": "לדבר על מה ידוע ומה לא (בהנחיית המטפלת)", "what": "שיחה כנה בימים הראשונים, ועדכון בכל פעם שיש מידע חדש.", "why": "מידע כן מחזיר מעט שליטה.", "freq": "בימים הראשונים ובכל עדכון", "approach": "ARC", "targets": ["t1"], "sentences": ["זה מה שידוע עכשיו", "את זה עוד לא יודעים", "כשיהיה מידע, נספר לך"], "avoid": "לא להבטיח תוצאה"}, {"id": "i2", "name": "לשמור על מה שנשאר", "what": "מזהים יחד מה אפשר לשמור (בית ספר, חוג, תחביב, מוזיקה) ועוזרים לשמור עליו.", "why": "רצף בחיים מחזיק בתקופה של משבר.", "freq": "בשבועות הראשונים", "approach": "ARC", "targets": ["t2"], "sentences": ["מה חשוב לך להמשיך?", "בוא/י נבדוק איך", "טוב שהמשכת"]}, {"id": "i3", "name": "להסביר את כללי הטלפון (בהנחיית המטפלת)", "what": "מסבירים בכנות את כללי הטלפון ואת הסדרי הקשר שנקבעו, ולמה.", "why": "כללים מובנים נשמרים יותר.", "freq": "בתחילה ובכל שינוי", "approach": "ARC", "targets": ["t3"], "sentences": ["אלה כללי הטלפון אצלנו", "ככה נקבע הקשר עם המשפחה", "יש שאלות?"], "avoid": "לא לקחת טלפון כעונש"}, {"id": "i4", "name": "לכבד עצמאות", "what": "נותנים מרחב, פרטיות ובחירות שמתאימות לגיל: שעת מקלחת, בגדים, זמן לבד.", "why": "כבוד לעצמאות הוא כבוד לנער/ה.", "freq": "תמיד", "approach": "TBRI", "targets": ["t4"], "sentences": ["מתי נוח לך?", "זה הזמן שלך", "אני סומך/ת עליך"]}, {"id": "i5", "name": "לשאול איך זה להיות כאן", "what": "שיחות קצרות ולא חוקרות: איך זה להיות פה? מה קשה? מה עוזר?", "why": "שאלה פתוחה מזמינה לדבר.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["איך זה להיות פה?", "מה הכי קשה?", "מה עוזר לך?"]}, {"id": "i6", "name": "להזמין לתרום", "what": "מציעים תפקיד אמיתי במרכז: לעזור לילד חדש, להוביל פעילות.", "why": "תפקיד נותן ערך גם בתקופה קשה.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t4", "t5"], "sentences": ["תוכל/י לעזור לילד החדש?", "יש לך ניסיון", "תודה, זה עזר"]}, {"id": "i7", "name": "לשמור על קשר עם המשפחה לפי מה שנקבע", "what": "עוזרים לקיים את הקשר שנקבע (שיחות, ביקורים), ולא מתנים אותו בהתנהגות.", "why": "קשר עם המשפחה הוא זכות, לא פרס.", "freq": "לפי הסדרי הקשר", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["השיחה עם המשפחה בשש", "זה שלך, לא קשור למה שהיה היום", "איך הייתה השיחה?"]}, {"id": "i8", "name": "לעדכן את המטפלת בשינויים", "what": "שינוי במצב הרוח, הסתגרות או דיבור על בריחה מעבירים למטפלת.", "why": "המשבר יכול להחמיר בשקט.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t5"], "sentences": ["אני רואה שקשה לך השבוע", "אכפת לי ממך", "נדבר גם עם המטפלת?"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'רחצה נעימה ובטוחה', 'להתרחץ בלי פחד, בקצב שלי', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['TBRI', 'ARC', 'ויסות חושי', 'NMT']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לרחוץ בכוח או ''רק מהר'', ולא לגעת בלי להסביר קודם", "strengths": ["אמון", "עצמאות", "שקט פנימי"], "skills": ["טיפול עצמי"], "main": "2-5", "also": [], "evidence": {"level": "derived", "note": "רחצה ומגע בגוף יכולים לעורר זיכרונות פגיעה. העקרונות (הסבר לפני מגע, בחירה, התאמה חושית) נגזרים מ-TIC ומוויסות חושי; התאמה יישומית שלא נבדקה."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "נכנס/ת לרחצה בלי סערה, אחרי שמסבירים מה יקרה", "staff": "נכנס/ת לרחצה בלי סערה", "scale": ["עדיין נבהל/ת ומתנגד/ת", "נכנס/ת עם הרבה הרגעה", "נכנס/ת אחרי הסבר", "נכנס/ת ברוגע", "מבקש/ת להתרחץ"]}, {"id": "t2", "text": "מסבן/ת ושוטף/ת בעצמו/ה חלקים שהוא/היא יכול/ה", "staff": "מסבן/ת לבד חלקים מהגוף", "scale": ["עדיין לא נוגע/ת בעצמו/ה", "מחזיק/ה את הספוג", "מסבן/ת חלק עם עזרה", "מסבן/ת רוב הגוף לבד", "מסבן/ת לבד ומבקש/ת עזרה רק בשיער"]}, {"id": "t3", "text": "אומר/ת או מראה ''לא'' או ''עצור'' כשמשהו לא נעים", "staff": "אומר/ת ''עצור'' כשלא נעים", "scale": ["עדיין קופא/ת או צורח/ת", "בוכה כשלא נעים", "מראה בתנועה", "אומר/ת עצור", "אומר/ת מה לא נעים"]}, {"id": "t4", "text": "בוחר/ת דבר אחד ברחצה (צעצוע, מגבת, סדר)", "staff": "בוחר/ת משהו ברחצה", "scale": ["עדיין לא בוחר/ת", "בוחר/ת בהצבעה", "בוחר/ת בין שניים", "בוחר/ת לבד", "מציע/ה בעצמו/ה"]}, {"id": "t5", "text": "נשאר/ת רגוע/ה כשמים נוגעים בפנים או בראש", "staff": "רגוע/ה כשמים בפנים או בראש", "scale": ["עדיין נבהל/ת מאוד", "נרגע/ת עם מגבת על הפנים", "נרגע/ת עם כוס שטיפה", "רגוע/ה ברוב הפעמים", "רגוע/ה ושוטף/ת לבד"]}], "interventions": [{"id": "i1", "name": "לספר לפני שנוגעים", "what": "מסבירים כל שלב לפני שעושים אותו ומחכים לתגובה.", "why": "מגע שמספרים עליו מראש מפחיד פחות.", "freq": "בכל רחצה", "approach": "TBRI", "targets": ["t1", "t3"], "sentences": ["עכשיו אני שופך/ת מים על הרגליים", "מוכן/ה?", "עוד מעט מסיימים"]}, {"id": "i2", "name": "לתת לילד/ה לעשות כמה שאפשר", "what": "הוא/היא מסבן/ת ושוטף/ת מה שיכול/ה, ובמיוחד את האיברים הפרטיים, והמבוגר מדריך.", "why": "מה שהילד עושה בעצמו שומר על גבולות הגוף.", "freq": "בכל רחצה", "approach": "ARC", "targets": ["t2"], "sentences": ["את זה אתה/את מסבן/ת", "ככה, יופי", "אני רק עוזר/ת בשיער"]}, {"id": "i3", "name": "להתאים לחושים", "what": "בודקים חום מים, שמים כוס לשטיפה, מגבת על הפנים, ומקצרים כשקשה.", "why": "מים נעימים מורידים את הפחד.", "freq": "בכל רחצה", "approach": "ויסות חושי", "targets": ["t5"], "sentences": ["המים חמים מדי?", "נשים מגבת על העיניים", "רק כוס אחת"]}, {"id": "i4", "name": "לכבד ''לא''", "what": "אם מסרב/ת, מוותרים על חלק, דוחים או מציעים חלופה (מגבת רטובה), בלי מאבק.", "why": "''לא'' שמכבדים מלמד שהגוף שלי שלי.", "freq": "בכל סירוב", "approach": "TBRI", "targets": ["t3"], "sentences": ["בסדר, את זה נעשה אחר כך", "אפשר עם מגבת רטובה", "תודה שאמרת לי"], "avoid": "לא לרחוץ בכוח"}, {"id": "i5", "name": "לתת בחירה קטנה", "what": "בוחרים צעצוע, מגבת או מה קודם.", "why": "בחירה מחזירה שליטה ברגע פגיע.", "freq": "בכל רחצה", "approach": "TBRI", "targets": ["t4"], "sentences": ["איזה צעצוע נכניס?", "קודם ידיים או רגליים?", "בחרת"]}, {"id": "i6", "name": "לשמור על אותו סדר", "what": "רחצה באותו סדר ובאותה שעה, עם שיר קבוע אם עוזר.", "why": "רחצה צפויה מפחידה פחות.", "freq": "בכל רחצה", "approach": "NMT", "targets": ["t1"], "sentences": ["כמו תמיד, קודם רגליים", "הנה השיר שלנו", "סיימנו, מגבת"]}, {"id": "i7", "name": "לגעת רק לפי מה שסוכם (בהנחיית המטפלת)", "what": "המטפלת קובעת איזה מגע מתאים ברחצה, ומי מהצוות רוחץ.", "why": "אצל ילדים שנפגעו, מגע לא מתאים מציף.", "freq": "תמיד", "approach": "TBRI", "targets": ["t3", "t1"], "sentences": ["אני רק מחזיק/ה את הספוג", "אתה/את עושה", "אני פה לידך"]}, {"id": "i8", "name": "לשים לב ולדווח", "what": "מדווחים למטפלת או לצוות הרפואי, לפי הנוהל, על חבלות, כאב או פחד קיצוני מאזור בגוף.", "why": "אלה יכולים להיות סימנים לפגיעה.", "freq": "בכל סימן", "approach": "ARC", "targets": ["t3"], "sentences": ["כואב לך פה?", "נבקש מהאחות לבדוק", "אתה/את בטוח/ה"], "avoid": "לא לחקור ולא לשאול שאלות מנחות"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הגוף שלי שלי', 'לדעת שמות לגוף, מה פרטי, ושמותר לומר ''לא''', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['ARC', 'TBRI', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לומר ''תן נשיקה לדודה'', לא להיעלב מ''לא'' לחיבוק, ולא לשאול שאלות מנחות", "strengths": ["אומץ", "ביטחון", "בקשת עזרה"], "skills": ["גבולות גוף"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "תוכניות מניעה ללימוד ילדים על גוף, פרטיות ובקשת עזרה נבדקו בסקירה שיטתית (Cochrane, 2015) ונמצאו משפרות ידע ונכונות לספר. ההתאמה למדריכים ולגיל הרך במסגרת היא יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "קורא/ת לחלקי הגוף בשמות, כולל האיברים הפרטיים", "staff": "יודע/ת שמות לחלקי הגוף", "scale": ["עדיין לא יודע/ת", "מצביע/ה כשאומרים שם", "אומר/ת חלק מהשמות", "אומר/ת את רוב השמות", "אומר/ת גם מה פרטי"]}, {"id": "t2", "text": "אומר/ת ''לא'' למגע שלא רוצה (חיבוק, הרמה)", "staff": "אומר/ת ''לא'' למגע שלא רוצה", "scale": ["עדיין לא אומר/ת", "מתרחק/ת בלי מילים", "מראה בתנועה", "אומר/ת לא", "אומר/ת לא גם למבוגר"]}, {"id": "t3", "text": "שומר/ת על פרטיות בשירותים ובהחלפת בגדים", "staff": "שומר/ת על פרטיות בשירותים ובבגדים", "scale": ["עדיין לא שם/ה לב", "שומר/ת עם תזכורת צמודה", "שומר/ת עם תזכורת", "שומר/ת לבד", "מזכיר/ה לחבר"]}, {"id": "t4", "text": "יודע/ת למי מהמבוגרים אפשר לספר", "staff": "יודע/ת למי לספר", "scale": ["עדיין לא", "מצביע/ה על אחד", "אומר/ת שם אחד", "אומר/ת כמה", "פונה כשצריך"]}, {"id": "t5", "text": "מבחין/ה בין סוד טוב (הפתעה) לסוד שצריך לספר", "staff": "יודע/ת איזה סוד מספרים", "scale": ["עדיין לא", "מקשיב/ה", "עונה נכון עם עזרה", "עונה נכון לבד", "מסביר/ה לחבר"]}], "interventions": [{"id": "i1", "name": "לקרוא ספרים ולשיר על הגוף", "what": "ספר או שיר על חלקי הגוף עם שמות נכונים, לפי חומרים שהמטפלת אישרה.", "why": "ילד שיודע שמות יכול לספר.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t1"], "sentences": ["אלה הידיים, אלה הרגליים", "יש חלקים פרטיים", "הגוף שלך שלך"]}, {"id": "i2", "name": "לכבד ''לא'' לחיבוק", "what": "כשאומר/ת לא לחיבוק, המבוגר מקבל בחום ומציע חלופה (כיף, נפנוף).", "why": "''לא'' שמכבדים מלמד שמותר לסרב.", "freq": "בכל פעם", "approach": "TBRI", "targets": ["t2"], "sentences": ["בסדר, לא מתחבקים", "רוצה כיף?", "טוב שאמרת"], "avoid": "לא להיעלב ולא לבקש ''תן נשיקה''"}, {"id": "i3", "name": "לשמור על פרטיות", "what": "מחיצה או דלת בשירותים ובהחלפת בגדים, ומבוגר מחכה בחוץ כשאפשר.", "why": "פרטיות קבועה מלמדת מה פרטי.", "freq": "תמיד", "approach": "TBRI", "targets": ["t3"], "sentences": ["סוגרים את הדלת", "אני מחכה בחוץ", "קרא/י לי אם צריך"]}, {"id": "i4", "name": "לצייר ''יד של מבוגרים''", "what": "ציור כף יד עם תמונות של מבוגרים בטוחים שאפשר לספר להם.", "why": "יד מוכרת מזכירה למי פונים.", "freq": "פעם אחת ומעדכנים", "approach": "מעגל הביטחון", "targets": ["t4"], "sentences": ["מי יהיה על האצבע הזו?", "ומי עוד?", "להם אפשר לספר"]}, {"id": "i5", "name": "להסביר סוד טוב וסוד רע", "what": "בנוסח שהמטפלת אישרה: הפתעה שמחה היא סוד טוב. סוד שמרגיש לא נעים, מספרים.", "why": "ההבחנה עוזרת לדעת מתי לספר.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t5"], "sentences": ["מתנה למסיבה זה סוד טוב", "סוד שמרגיש רע, מספרים", "תמיד אפשר לספר לי"]}, {"id": "i6", "name": "להגיב נכון כשמספר/ת על פגיעה", "what": "אם מספר/ת על נגיעה: מקשיבים ברוגע, אומרים תודה, ומעבירים מיד לפי הנוהל.", "why": "התגובה הראשונה קובעת אם ימשיך/תמשיך לספר.", "freq": "בכל גילוי", "approach": "ARC", "targets": ["t4"], "sentences": ["תודה שסיפרת לי", "עשית נכון", "אני אספר למי שיודע לשמור עליך"], "avoid": "לא לשאול שאלות מנחות ולא להראות בהלה"}, {"id": "i7", "name": "לשאול לפני שנוגעים", "what": "המבוגרים שואלים לפני מגע שאינו דחוף: אפשר לעזור לך עם המעיל?", "why": "שאלה לפני מגע היא הדוגמה הכי טובה.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2"], "sentences": ["אפשר לעזור לך?", "אפשר להחזיק לך יד?", "תודה שאמרת"]}, {"id": "i8", "name": "לשבח כשאמר/ה ''לא''", "what": "כשאמר/ה לא למגע, משבחים.", "why": "חיזוק ל''לא'' מחזק את הגבול.", "freq": "בכל פעם", "approach": "TBRI", "targets": ["t2"], "sentences": ["אמרת לא, וזה בסדר", "הגוף שלך שלך", "יפה ששמרת על עצמך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'אני דואג/ת לגוף שלי', 'ללמוד לשמור על ניקיון הגוף, בלי בושה', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['ARC', 'ויסות חושי', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעיר מול ילדים, לא להשתמש במילים כמו ''מסריח'', ולא לתלות טבלה ציבורית", "strengths": ["עצמאות", "התמדה", "אחריות"], "skills": ["טיפול עצמי"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "הזנחה פוגעת לעיתים קרובות בהרגלי טיפול עצמי. לימוד בצעדים (מודלינג, עשייה משותפת) נגזר מעקרונות לימוד מיומנויות ומ-ARC; התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "מתקלח/ת לפי השלבים, עם עזרה קטנה", "staff": "מתקלח/ת לפי השלבים", "scale": ["עדיין מסרב/ת או נמנע/ת", "מתקלח/ת עם מבוגר צמוד", "מתקלח/ת עם הדרכה", "מתקלח/ת לבד עם תזכורת", "מתקלח/ת לבד"]}, {"id": "t2", "text": "מצחצח/ת שיניים בבוקר ובערב", "staff": "מצחצח/ת שיניים", "scale": ["עדיין לא", "עם מבוגר", "עם תזכורת", "לבד ברוב הימים", "לבד תמיד"]}, {"id": "t3", "text": "מחליף/ה בגדים נקיים לפי הצורך", "staff": "מחליף/ה לבגדים נקיים", "scale": ["עדיין לובש/ת אותו דבר ימים", "מחליף/ה כשנותנים", "מחליף/ה עם תזכורת", "מחליף/ה לבד", "שם/ה לב בעצמו/ה מתי צריך"]}, {"id": "t4", "text": "אומר/ת כשמשהו ברחצה מפחיד או לא נוח", "staff": "אומר/ת מה מפחיד ברחצה", "scale": ["עדיין לא אומר/ת", "מראה בהתנהגות", "אומר/ת כששואלים", "אומר/ת מיוזמתו/ה", "מציע/ה מה יעזור"]}, {"id": "t5", "text": "מראה גאווה כשדאג/ה לעצמו/ה לבד", "staff": "גאה כשדאג/ה לעצמו/ה", "scale": ["עדיין לא מתעניין/ת", "מחייך/ת כשמשבחים", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מבקש/ת ללמוד עוד"]}], "interventions": [{"id": "i1", "name": "ללמד צעד אחר צעד", "what": "מדגימים, עושים יחד, ואז הוא/היא לבד. משבחים כל צעד ולא רק את התוצאה.", "why": "מיומנות שלא נלמדה בבית נלמדת בצעדים.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["קודם אני מראה", "עכשיו ביחד", "עכשיו אתה/את"], "avoid": "לא להעיר מול ילדים"}, {"id": "i2", "name": "להתאים לפחדים (בהנחיית המטפלת)", "what": "אם יש פחד ממקלחת, מים, מראה או דלת סגורה, מתאימים לפי המטפלת: דלת פתוחה מעט, ראש מקלחת ביד.", "why": "פחד שמכבדים מאפשר להתרחץ.", "freq": "לפי הצורך", "approach": "ויסות חושי", "targets": ["t4", "t1"], "sentences": ["מה הכי קשה במקלחת?", "נשאיר את הדלת קצת פתוחה", "ככה בסדר?"]}, {"id": "i3", "name": "לתת ערכה אישית", "what": "ערכה עם השם שלו/ה: מברשת, משחה, סבון, מסרק. זמינה תמיד.", "why": "דברים משלי מזמינים לדאוג לעצמי.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2", "t5"], "sentences": ["זו הערכה שלך", "בחרת צבע", "היא תמיד כאן"]}, {"id": "i4", "name": "לתלות רשימה בתמונות", "what": "רשימה קטנה בתמונות של שלבי המקלחת והצחצוח, במקום פרטי.", "why": "רשימה מחליפה תזכורות מביכות.", "freq": "תמיד", "approach": "ARC", "targets": ["t1", "t2"], "sentences": ["מה השלב הבא ברשימה?", "סיימת הכל?", "לבד, יופי"]}, {"id": "i5", "name": "להזכיר בשקט ובפרטיות", "what": "תזכורת אחת, שקטה ובפרטיות, בלי לומר מול אחרים.", "why": "תזכורת פרטית לא מביישת.", "freq": "לפי הצורך", "approach": "TBRI", "targets": ["t3"], "sentences": ["רגע לפני ארוחת ערב, מקלחת", "יש בגדים נקיים בארון", "רק בינינו"], "avoid": "לא להשתמש במילים כמו ''מסריח''"}, {"id": "i6", "name": "לרשום התקדמות אישית", "what": "רושמים מה עושה לבד, בלי השוואה לילדים אחרים, ומראים לו/ה.", "why": "התקדמות אישית מראה שאני מצליח/ה.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t5"], "sentences": ["תראה/תראי, עכשיו אתה/את עושה לבד", "לפני חודש עזרנו", "יפה מאוד"], "avoid": "לא לתלות טבלה ציבורית של ''מי התקלח''"}, {"id": "i7", "name": "לבחור בגדים יחד", "what": "בוחרים יחד בגדים בערב ומחליטים מתי מחליפים.", "why": "בחירה הופכת החלפה לשלו/ה.", "freq": "כל ערב", "approach": "TBRI", "targets": ["t3"], "sentences": ["מה נלבש מחר?", "את זה נכבס", "בחרת יפה"]}, {"id": "i8", "name": "לשבח דאגה לעצמו/ה", "what": "כשדאג/ה לעצמו/ה, משבחים בפרטיות.", "why": "שבח פרטי מחזק בלי לחשוף.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t5"], "sentences": ["ראיתי שהתקלחת לבד", "דאגת לעצמך", "כל הכבוד לך"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מקום שלי', 'שיהיה לי מקום משלי, ושיכבדו את הפרטיות שלי ושל אחרים', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['TBRI', 'סמכות חדשה', 'ARC', 'CPS']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לחפש כעונש או בלי הסבר, ולא לגעת בחפצים אישיים בלי לשאול", "strengths": ["כבוד", "אחריות", "אמון"], "skills": ["גבולות"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "חפצים אישיים ופרטיות קשורים לתחושת ביטחון וזהות במחקרי סידור חוץ־ביתי. ''דופקים לפני שנכנסים'' וחיפוש רק לפי נוהל הם עקרונות של מערכת מותאמת טראומה; התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "שומר/ת על המקום האישי שלו/ה ועל החפצים בו", "staff": "שומר/ת על המקום האישי", "scale": ["עדיין לא שומר/ת", "שומר/ת עם מבוגר", "שומר/ת עם תזכורת", "שומר/ת לבד", "מסדר/ת ומקשט/ת"]}, {"id": "t2", "text": "דופק/ת לפני שנכנס/ת לחדר של אחרים", "staff": "דופק/ת לפני שנכנס/ת", "scale": ["עדיין נכנס/ת בלי לדפוק", "דופק/ת כשמזכירים", "דופק/ת לפעמים", "דופק/ת ברוב הפעמים", "מזכיר/ה לאחרים"]}, {"id": "t3", "text": "לא לוקח/ת חפצים של אחרים, ומבקש/ת כשרוצה", "staff": "מבקש/ת במקום לקחת", "scale": ["עדיין לוקח/ת", "מחזיר/ה כשמבקשים", "מבקש/ת עם תזכורת", "מבקש/ת לבד", "שומר/ת גם על חפצים של אחרים"]}, {"id": "t4", "text": "אומר/ת כשמישהו נוגע בדברים שלו/ה, במילים", "staff": "אומר/ת כשנוגעים בדברים שלו/ה", "scale": ["עדיין מתפרץ/ת", "פונה למבוגר", "אומר/ת עם עזרה", "אומר/ת לבד ברוגע", "מסדר/ת את זה עם החבר"]}, {"id": "t5", "text": "מרגיש/ה שהמקום שלו/ה בטוח (ישן/ה, משאיר/ה דברים)", "staff": "משאיר/ה דברים במקום שלו/ה בביטחון", "scale": ["עדיין סוחב/ת הכל איתו/ה", "משאיר/ה דבר אחד", "משאיר/ה כמה", "משאיר/ה את רוב הדברים", "סומך/ת על המקום"]}], "interventions": [{"id": "i1", "name": "לתת מקום אישי וקבוע", "what": "מגירה או ארון אישיים (ננעלים, אם כללי המרכז מאפשרים), מדף לתמונות, ושלט עם השם על המיטה.", "why": "מקום משלי אומר: אני שייך/ת.", "freq": "תמיד", "approach": "TBRI", "targets": ["t1", "t5"], "sentences": ["זה המקום שלך", "אף אחד לא לוקח מכאן בלי לשאול", "מה תרצה/תרצי לתלות?"]}, {"id": "i2", "name": "לדפוק לפני שנכנסים", "what": "כלל לכל המרכז, גם לצוות. המבוגרים דופקים ומחכים.", "why": "מבוגר שדופק מלמד כבוד לפרטיות.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t2"], "sentences": ["טוק טוק, אפשר להיכנס?", "אצלנו דופקים", "תודה שדפקת"]}, {"id": "i3", "name": "לחפש רק לפי הנוהל", "what": "חיפוש בחדר רק לפי הנוהל, מסבירים למה, ובנוכחות הילד/ה כשאפשר.", "why": "חיפוש בלי הסבר פוגע באמון ובתחושת הביטחון.", "freq": "רק לפי הנוהל", "approach": "ARC", "targets": ["t5"], "sentences": ["אני צריך/ה לבדוק את החדר, כי יש דאגה שיש פה משהו מסוכן", "אתה/את יכול/ה להיות פה", "אני מחזיר/ה הכל למקום"], "avoid": "לא לחפש כעונש"}, {"id": "i4", "name": "לבקש לפני שלוקחים", "what": "מתרגלים לשאול לפני שלוקחים, וכשנלקח חפץ, מתקנים בשיחה ולא בעונש.", "why": "תיקון מלמד יותר מעונש.", "freq": "בכל פעם", "approach": "CPS", "targets": ["t3"], "sentences": ["אפשר לשאול: אפשר לקחת?", "בוא/י נחזיר את זה ביחד", "מה נעשה בפעם הבאה?"]}, {"id": "i5", "name": "לתרגל משפט שמירה", "what": "מתרגלים משפט כשמישהו נוגע בדברים: זה שלי, תשאל/י קודם.", "why": "משפט מוכן מחליף מכות.", "freq": "בזמן רגוע", "approach": "ARC", "targets": ["t4"], "sentences": ["אפשר לומר: זה שלי", "תשאל/י קודם", "ואם לא עוזר, קורא/ת לנו"]}, {"id": "i6", "name": "לא לגעת בחפצים בלי לשאול", "what": "גם הצוות שואל לפני שמזיז או מכבס חפץ אישי.", "why": "דוגמה של מבוגרים מלמדת יותר מכלל.", "freq": "תמיד", "approach": "TBRI", "targets": ["t5"], "sentences": ["אפשר לכבס את זה?", "זה יחזור אליך נקי", "זה שלך"]}, {"id": "i7", "name": "לקשט יחד", "what": "מקשטים את המקום האישי: תמונות, ציורים, דברים שהוא/היא אוהב/ת.", "why": "מקום שמראה אותי הוא פינה שלי בתוך המרכז.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t1"], "sentences": ["מה תרצה/תרצי לתלות?", "יפה פה", "זה מראה מי אתה/את"]}, {"id": "i8", "name": "לשבח שמירה על פרטיות", "what": "כשדפק/ה או שמר/ה על חפץ של אחר, משבחים.", "why": "חיזוק בונה הרגל.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["דפקת, יפה", "שמרת על הדברים שלו", "זה כבוד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'גוף שמשתנה', 'לעבור את ההתבגרות עם מידע, כבוד ומבוגר שאפשר לשאול', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['ARC', 'TBRI', 'סמכות חדשה']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לצחוק, לא להעיר מול אחרים, ולא להשתמש בחומרים שלא אושרו", "strengths": ["סקרנות", "כבוד", "ביטחון"], "skills": ["טיפול עצמי"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "חינוך מיני ולהתבגרות מותאם גיל נתמך במחקר ובהנחיות בינלאומיות (UNESCO). בילדים בסידור חוץ־ביתי, עם היסטוריה של פגיעה, ההתאמה נעשית בהנחיית המטפלת; זו התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "שואל/ת שאלות על הגוף ועל ההתבגרות את המבוגר שנבחר", "staff": "שואל/ת על התבגרות", "scale": ["עדיין לא שואל/ת", "שם/ה שאלה בקופסה", "שואל/ת בשקט", "שואל/ת ומקשיב/ה", "שואל/ת ברוגע כשצריך"]}, {"id": "t2", "text": "משתמש/ת במוצרי ההיגיינה שמתאימים לגיל (דאודורנט, תחבושות)", "staff": "משתמש/ת במוצרי היגיינה לגיל", "scale": ["עדיין לא", "משתמש/ת עם תזכורת", "משתמש/ת לפעמים", "משתמש/ת באופן קבוע", "יודע/ת מתי צריך עוד"]}, {"id": "t3", "text": "מדבר/ת על השינויים בגוף בלי בושה", "staff": "מדבר/ת על השינויים בלי בושה", "scale": ["עדיין מתבייש/ת מאוד", "מקשיב/ה", "אומר/ת מילה", "מדבר/ת ברוגע", "מדבר/ת ושואל/ת"]}, {"id": "t4", "text": "כשמקניטים על הגוף, פונה למבוגר או עונה במשפט", "staff": "מגיב/ה להקנטה על הגוף", "scale": ["עדיין מתפרץ/ת או מתכנס/ת", "בוכה ונרגע/ת", "פונה למבוגר", "עונה במשפט", "נשאר/ת רגוע/ה"]}, {"id": "t5", "text": "יודע/ת מה עושים במחזור ראשון או בשינוי מפתיע", "staff": "יודע/ת מה עושים בשינוי מפתיע", "scale": ["עדיין לא יודע/ת", "יודע/ת עם הסבר", "יודע/ת איפה הערכה", "יודע/ת מה לעשות", "מסביר/ה לחברים"]}], "interventions": [{"id": "i1", "name": "לבחור מבוגר לשיחה (בהנחיית המטפלת)", "what": "המטפלת קובעת מי מדבר עם הילד/ה על התבגרות, גבר או אישה, לפי מה שנוח לו/ה.", "why": "מבוגר אחד שבחרו עדיף על הרבה הערות.", "freq": "בתחילת המטרה", "approach": "ARC", "targets": ["t1"], "sentences": ["עם מי נוח לך לדבר על זה?", "אפשר לשאול את המבוגר שבחרת הכל", "אין שאלה מביכה"]}, {"id": "i2", "name": "להסביר ברוגע ובעובדות", "what": "בשפה פשוטה, בספרים או בסרטונים שאושרו.", "why": "מידע מדויק מוריד פחד.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t3", "t1"], "sentences": ["זה קורה לכולם בגיל הזה", "בוא/י נקרא על זה", "מה עוד מעניין אותך?"], "avoid": "לא לצחוק ולא להעיר מול אחרים"}, {"id": "i3", "name": "לתת ערכה אישית", "what": "מוצרים שזמינים בלי לבקש כל פעם (תחבושות, דאודורנט), במקום פרטי.", "why": "ערכה זמינה חוסכת מבוכה.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2"], "sentences": ["הערכה שלך פה", "כשנגמר, תגיד/י לי", "אף אחד לא צריך לדעת"]}, {"id": "i4", "name": "לתת קופסת שאלות", "what": "קופסה לשאלות בלי שם, והמטפלת או המבוגר שנבחר עונים.", "why": "שאלה בלי שם קלה יותר.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1"], "sentences": ["אפשר לשאול בפתק", "בלי שם", "נענה לכולם"]}, {"id": "i5", "name": "לעצור הקנטות על הגוף", "what": "עוצרים מיד כל הקנטה על גוף, מול הקבוצה, בלי לציין את מי.", "why": "גוף שמשתנה צריך מקום בטוח.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t4"], "sentences": ["אצלנו לא מעירים על גוף", "זה נגמר עכשיו", "כולנו משתנים"]}, {"id": "i6", "name": "להכין למחזור ראשון", "what": "הכנה מראש, ערכה בתיק בית הספר, ומבוגר זמין בטלפון לפי הנוהל.", "why": "מי שמוכן/ה לא נבהל/ת.", "freq": "לפני ובזמן", "approach": "ARC", "targets": ["t5"], "sentences": ["זה מה שעושים אם זה קורה", "הערכה בתיק", "אפשר להתקשר למרכז, תמיד יש מי שעונה"]}, {"id": "i7", "name": "לתרגל משפט מול הקנטה", "what": "מתרגלים משפט קצר להקנטה על גוף.", "why": "משפט מוכן נותן כוח.", "freq": "בזמן רגוע", "approach": "ARC", "targets": ["t4"], "sentences": ["אפשר לומר: הגוף שלי זה עניין שלי", "ולהמשיך הלאה", "ואם ממשיכים, אלינו"]}, {"id": "i8", "name": "לשים לב לבלבול ולמצוקה", "what": "שאלות או התנהגות שמדאיגות סביב מיניות, או מצוקה גדולה מהגוף, מעבירים למטפלת.", "why": "אצל ילדים שנפגעו, ההתבגרות יכולה לעורר קושי.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t3"], "sentences": ["זה נשמע מבלבל", "נדבר גם עם המטפלת", "אתה/את לא לבד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הגוף והמראה שלי', 'לדאוג לגוף שלי ולמראה שלי בדרך שלי', array['גוף, היגיינה ופרטיות']::text[], 'גוף, היגיינה ופרטיות', array['CPS', 'ARC', 'DDP/PACE', 'TBRI', 'סמכות חדשה']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להעיר על גוף, משקל, סגנון או תספורת, אלא בעניין בטיחות", "strengths": ["עצמאות", "כבוד", "יצירתיות"], "skills": ["טיפול עצמי"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "נגזר מעבודה על דימוי גוף אצל מתבגרים (בלי הערות על משקל) ומ-ARC (זהות). הזנחה פתאומית כסימן מצוקה מוכרת בספרות; התאמה יישומית."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "בוחר/ת וקונה מוצרי טיפוח ובגדים בתקציב קבוע", "staff": "בוחר/ת וקונה טיפוח ובגדים", "scale": ["עדיין לא מעורב/ת", "בוחר/ת עם מבוגר", "בוחר/ת בתקציב עם עזרה", "בוחר/ת וקונה לבד", "מתכנן/ת קנייה מראש"]}, {"id": "t2", "text": "שומר/ת על היגיינה אישית באופן עצמאי", "staff": "שומר/ת על היגיינה לבד", "scale": ["עדיין מזניח/ה", "עם הרבה תזכורות", "עם תזכורת", "לבד ברוב הימים", "לבד תמיד"]}, {"id": "t3", "text": "מבטא/ת את עצמו/ה במראה בלי להיפגע מהערות", "staff": "מבטא/ת את עצמו/ה במראה", "scale": ["עדיין מסתתר/ת או נפגע/ת מאוד", "מנסה דבר קטן", "מבטא/ת סגנון", "מבטא/ת ומרגיש/ה טוב", "מכבד/ת גם סגנון של אחרים"]}, {"id": "t4", "text": "מדבר/ת על הגוף בלי לבקר את עצמו/ה", "staff": "מדבר/ת על הגוף בלי לבקר", "scale": ["עדיין מבקר/ת קשות", "שותק/ת", "אומר/ת משפט פחות קשה", "מדבר/ת בלי שיפוט", "אומר/ת משהו טוב על הגוף"]}, {"id": "t5", "text": "כשקשה, ממשיך/ה לדאוג לעצמו/ה או מבקש/ת עזרה", "staff": "ממשיך/ה לדאוג לעצמו/ה גם כשקשה", "scale": ["עדיין מזניח/ה כשקשה", "מקבל/ת עזרה כשמציעים", "מבקש/ת עזרה", "ממשיך/ה ברוב הזמן", "ממשיך/ה ומספר/ת שקשה"]}], "interventions": [{"id": "i1", "name": "לתת תקציב ולקנות יחד", "what": "סכום קבוע לטיפוח ובגדים, וקנייה משותפת שבה הוא/היא בוחר/ת.", "why": "בחירה עצמאית במראה היא חלק מהזהות.", "freq": "באופן קבוע", "approach": "CPS", "targets": ["t1"], "sentences": ["כמה יש לך החודש?", "מה תרצה/תרצי?", "בחרת לבד"]}, {"id": "i2", "name": "לכבד בחירות מראה", "what": "לא מעירים על סגנון, תספורת או מראה, רק בעניין בטיחותי מוסכם.", "why": "הערות על מראה פוגעות בזהות.", "freq": "תמיד", "approach": "ARC", "targets": ["t3"], "sentences": ["זה הסגנון שלך", "מה אתה/את אוהב/ת בזה?", "נראה שזה מרגיש לך טוב"], "avoid": "לא להעיר על גוף, משקל או סגנון"}, {"id": "i3", "name": "לדבר על דימוי גוף", "what": "שיחה על השוואות, פילטרים והשפעת הרשת, בתיאום עם המטפלת.", "why": "מודעות מורידה את כוח ההשוואה.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t4"], "sentences": ["כמה מהתמונות ברשת אמיתיות?", "מה אתה/את מרגיש/ה כשמסתכל/ת?", "הגוף שלך עושה הרבה בשבילך"]}, {"id": "i4", "name": "לשמור על פרטיות בטיפוח", "what": "זמן ומקום פרטיים למקלחת וטיפוח, ומוצרים במקום אישי.", "why": "פרטיות היא תנאי לטיפוח בכבוד.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2"], "sentences": ["זה הזמן שלך במקלחת", "נכנסים רק אם יש דאגה לבטיחות", "הדברים שלך פה"]}, {"id": "i5", "name": "לשים לב להזנחה פתאומית", "what": "הזנחה חדשה ומתמשכת יכולה להעיד על מצוקה. מדווחים למטפלת.", "why": "הגוף מראה לפעמים את מה שלא נאמר.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t5"], "sentences": ["שמתי לב שקשה לך לאחרונה", "אכפת לי", "רוצה לדבר?"]}, {"id": "i6", "name": "לעצור הערות של אחרים", "what": "עוצרים מיד הערות של ילדים על גוף או מראה.", "why": "סביבה בלי הערות מאפשרת לבטא את עצמי.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t3", "t4"], "sentences": ["אצלנו לא מעירים על מראה", "כל אחד בסגנון שלו", "נגמר"]}, {"id": "i7", "name": "לשבח דאגה עצמית", "what": "כשדאג/ה לעצמו/ה גם ביום קשה, אומרים בקצרה ובפרטיות.", "why": "חיזוק פרטי מכבד בני נוער.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t5", "t2"], "sentences": ["ראיתי שדאגת לעצמך גם היום", "זה לא קל", "אכפת לי ממך"]}, {"id": "i8", "name": "לשאול מה מרגיש טוב", "what": "שואלים בסקרנות מה גורם לו/ה להרגיש טוב עם עצמו/ה.", "why": "שאלה על הטוב מחזקת דימוי חיובי.", "freq": "מדי פעם", "approach": "DDP/PACE", "targets": ["t4", "t3"], "sentences": ["מתי אתה/את מרגיש/ה הכי טוב עם עצמך?", "מה עוזר?", "נשמע טוב"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'צופים ביחד', 'זמן מסך קצר, מתוכנן ועם מבוגר לידי', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['ARC', 'DDP/PACE', 'ויסות חושי', 'מעגל הביטחון']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להשתמש במסך כבייביסיטר קבוע, ולא לספור שיחות וידאו עם המשפחה כזמן מסך", "strengths": ["סקרנות", "שיתוף", "הנאה"], "skills": ["ויסות"], "main": "2-5", "also": [], "evidence": {"level": "derived", "note": "הנחיות רפואת ילדים (AAP, WHO) ממליצות על זמן מסך קצר ומלווה בגיל הרך. ההתאמה למסגרת חירום, כולל הפרדה בין שיחות וידאו עם המשפחה לבין ''זמן מסך'', היא יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "צופה בתוכן מתאים לגיל, ליד מבוגר", "staff": "צופה בתוכן מתאים עם מבוגר", "scale": ["עדיין צופה לבד הרבה", "צופה עם מבוגר לפעמים", "צופה עם מבוגר ברוב הפעמים", "צופה עם מבוגר ומדבר/ת על מה שראה", "מבקש/ת לצפות ביחד"]}, {"id": "t2", "text": "מדבר/ת על מה שראה (מי, מה קרה, מה הרגיש)", "staff": "מדבר/ת על מה שראה", "scale": ["עדיין לא מדבר/ת", "מצביע/ה על דמות", "עונה כששואלים", "מספר/ת מיוזמתו/ה", "ממציא/ה המשך"]}, {"id": "t3", "text": "בוחר/ת במשחק או בפעילות גם כשיש מסך", "staff": "בוחר/ת גם בפעילות אחרת", "scale": ["עדיין רק מסך", "משחק/ת כשמבוגר מתחיל", "בוחר/ת לפעמים", "בוחר/ת ברוב הימים", "מציע/ה משחק בעצמו/ה"]}, {"id": "t4", "text": "נשאר/ת רגוע/ה אחרי הצפייה", "staff": "רגוע/ה אחרי הצפייה", "scale": ["עדיין מוצף/ת אחרי", "נרגע/ת עם הרבה עזרה", "נרגע/ת עם עזרה", "נרגע/ת מהר", "עובר/ת בקלות לדבר הבא"]}, {"id": "t5", "text": "נהנה/נהנית משיחת וידאו עם המשפחה, כשמתאפשרת", "staff": "משתתף/ת בשיחת וידאו עם המשפחה", "scale": ["עדיין מתקשה או בורח/ת", "מסתכל/ת על המסך", "אומר/ת מילה או מנפנף/ת", "משתתף/ת", "מספר/ת משהו מהיום"]}], "interventions": [{"id": "i1", "name": "לתכנן זמן מסך קצר", "what": "זמן מסך קצר ובשעה קבועה, ולא כפתרון לרגעים קשים.", "why": "מסך צפוי וקצר מרגש פחות.", "freq": "כל יום", "approach": "ARC", "targets": ["t4"], "sentences": ["אחרי הצהריים יש סרטון אחד", "ואז משחקים", "כמו כל יום"]}, {"id": "i2", "name": "לצפות ביחד ולדבר", "what": "מבוגר יושב לידו/ה, שואל ומגיב: מה הוא מרגיש? מה יקרה עכשיו?", "why": "צפייה משותפת הופכת מסך לשיחה.", "freq": "בכל צפייה", "approach": "DDP/PACE", "targets": ["t1", "t2"], "sentences": ["מה הוא מרגיש עכשיו?", "מה יקרה?", "גם אני הייתי מפחד/ת"]}, {"id": "i3", "name": "לבחור מרשימה מאושרת", "what": "רשימת תכנים שהמטפלת או ההנהלה אישרו, בלי תכנים מפחידים או אלימים.", "why": "תוכן מפחיד מציף ילדים אחרי טראומה.", "freq": "תמיד", "approach": "ARC", "targets": ["t1", "t4"], "sentences": ["מהרשימה שלנו, מה תרצה/תרצי?", "את זה בוחרים היום", "זה מתאים לך"]}, {"id": "i4", "name": "להציע חלופות זמינות", "what": "משחקים, ספרים ויצירה מוכנים ונגישים לפני ואחרי הצפייה.", "why": "כשיש חלופה מעניינת, המסך פחות מושך.", "freq": "תמיד", "approach": "ויסות חושי", "targets": ["t3"], "sentences": ["רוצה לבנות מגדל?", "בוא/י נצייר את הדמות", "מה נשחק?"]}, {"id": "i5", "name": "להמשיך את הסיפור במשחק", "what": "אחרי הצפייה משחקים את הסיפור עם בובות או מציירים.", "why": "משחק מעבד את מה שראו.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t2", "t3"], "sentences": ["מי תהיה הדמות?", "ומה קרה אחר כך?", "איזה סוף תרצה/תרצי?"]}, {"id": "i6", "name": "להפריד שיחות משפחה מזמן מסך", "what": "שיחת וידאו עם המשפחה, לפי ההסדר, היא קשר ולא ''זמן מסך''. היא לא נספרת ולא נלקחת.", "why": "קשר עם המשפחה הוא צורך, לא בידור.", "freq": "לפי ההסדר", "approach": "מעגל הביטחון", "targets": ["t5"], "sentences": ["עכשיו מדברים עם המשפחה", "רוצה להראות להם את הציור?", "אני פה לידך"], "avoid": "לא לקצר או לבטל שיחה כעונש"}, {"id": "i7", "name": "לעזור בשיחת וידאו", "what": "מבוגר יושב לידו/ה, מציע מה לספר או להראות, ועוזר לסיים בנעימות.", "why": "ילד קטן מתקשה לשוחח מול מסך לבד.", "freq": "בכל שיחה", "approach": "ARC", "targets": ["t5"], "sentences": ["ספר/י להם על הגן", "תראה/תראי להם את הבובה", "אומרים ביי ונשיקה באוויר"]}, {"id": "i8", "name": "לשים לב לתגובות", "what": "אם אחרי צפייה מופיעים פחד, סיוטים או משחק מטריד, מספרים למטפלת.", "why": "תגובה כזו יכולה לרמז שהתוכן עורר משהו.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t4"], "sentences": ["זה היה מפחיד?", "עכשיו אנחנו פה", "אתה/את בטוח/ה"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'מכבים בלי סערה', 'לסיים מסך בלי התפרצות, כי יודעים מה בא אחר כך', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['ARC', 'TBRI', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לכבות בבת אחת בלי התראה, ולא להשתמש במסך כפרס או כעונש", "strengths": ["גמישות", "שיתוף פעולה", "רוגע"], "skills": ["ויסות", "מעברים"], "main": "2-5", "also": ["6-9"], "evidence": {"level": "derived", "note": "התראה מוקדמת ומעבר צפוי מפחיתים התפרצויות במעברים, עיקרון שנבדק בעבודה על מעברים בגיל הרך. ההתאמה לכיבוי מסך היא יישומית."}, "ages": {"2-5": {"targets": [{"id": "t1", "text": "מסיים/ת צפייה כשהטיימר מצלצל", "staff": "מסיים/ת כשהטיימר מצלצל", "scale": ["עדיין מתנגד/ת בכל פעם", "מסיים/ת עם הרבה עזרה", "מסיים/ת עם עזרה", "מסיים/ת עם תזכורת", "מסיים/ת לבד"]}, {"id": "t2", "text": "עובר/ת לפעילות הבאה תוך זמן קצר", "staff": "עובר/ת מהר לפעילות הבאה", "scale": ["עדיין נשאר/ת תקוע/ה", "עובר/ת אחרי זמן ארוך", "עובר/ת עם עזרה", "עובר/ת מהר", "עובר/ת בשמחה"]}, {"id": "t3", "text": "אומר/ת במילים שהוא/היא עוד רוצה, במקום להתפרץ", "staff": "אומר/ת ''עוד'' במילים", "scale": ["עדיין מתפרץ/ת", "בוכה ונרגע/ת", "אומר/ת עם עזרה", "אומר/ת לבד", "אומר/ת ומקבל/ת את התשובה"]}, {"id": "t4", "text": "עוזר/ת לכבות או לסגור את המסך", "staff": "עוזר/ת לכבות", "scale": ["עדיין לא", "מסתכל/ת", "לוחץ/ת עם מבוגר", "מכבה לבד כשמבקשים", "מכבה מיוזמתו/ה"]}, {"id": "t5", "text": "נרגע/ת מהר אם בכל זאת כעס/ה", "staff": "נרגע/ת מהר אחרי כעס על המסך", "scale": ["עדיין זמן רב", "נרגע/ת עם הרבה עזרה", "נרגע/ת עם עזרה", "נרגע/ת מהר", "נרגע/ת לבד"]}], "interventions": [{"id": "i1", "name": "להתריע לפני הסוף", "what": "אומרים מראש: עוד פרק אחד ואז מקלחת, או מכוונים טיימר שהוא/היא רואה.", "why": "סוף צפוי קל יותר מסוף פתאומי.", "freq": "בכל צפייה", "approach": "ARC", "targets": ["t1"], "sentences": ["עוד פרק אחד ואז מקלחת", "הטיימר יצלצל", "עוד מעט"]}, {"id": "i2", "name": "לספר מה בא אחר כך", "what": "מראים בתמונה או במילה את הפעילות הבאה, ועדיף משהו נעים.", "why": "כשיודעים לאן הולכים, קל לעזוב.", "freq": "בכל סיום", "approach": "ARC", "targets": ["t2"], "sentences": ["אחרי זה בונים מגדל", "הנה התמונה", "בוא/י נלך"]}, {"id": "i3", "name": "לתת לו/ה לכבות", "what": "הילד/ה לוחץ/ת על הכפתור או סוגר/ת, לבד או עם המבוגר.", "why": "שליטה בסיום מורידה מאבק.", "freq": "בכל סיום", "approach": "TBRI", "targets": ["t4"], "sentences": ["אתה/את מכבה?", "לחיצה אחת", "יפה, כיבית"]}, {"id": "i4", "name": "לתת שם לרצון", "what": "אומרים בחום שרוצים עוד, ונשארים בגבול.", "why": "רצון שנשמע קל יותר לשחרר.", "freq": "בכל קושי", "approach": "DDP/PACE", "targets": ["t3"], "sentences": ["כל כך רצית עוד", "זה מבאס", "ומחר יש שוב"]}, {"id": "i5", "name": "לעזור להירגע", "what": "אם יש התפרצות: נשארים קרוב, קול שקט, בלי ויכוח ובלי להחזיר את המסך.", "why": "מבוגר רגוע לידו מרגיע מהר יותר מוויכוח.", "freq": "בכל התפרצות", "approach": "TBRI", "targets": ["t5"], "sentences": ["אני פה", "נושמים ביחד", "כשתהיה/תהיי מוכן/ה, נשחק"]}, {"id": "i6", "name": "מסך לא כפרס ולא כעונש", "what": "זמן המסך קבוע, ולא נוסף על התנהגות טובה ולא נלקח על רעה.", "why": "מסך כפרס הופך אותו לחשוב מדי וגורם למאבקים.", "freq": "תמיד", "approach": "TBRI", "targets": ["t1"], "sentences": ["זמן המסך הוא כמו תמיד", "זה לא קשור למה שקרה", "ועכשיו נדבר על מה שקרה"]}, {"id": "i7", "name": "לתרגל במשחק", "what": "משחקים ''טלוויזיה'' עם בובה שצריכה לכבות, ומתרגלים מה עושים.", "why": "תרגול במשחק מכין לרגע האמיתי.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t3", "t4"], "sentences": ["הדובי רוצה עוד", "מה הוא יכול להגיד?", "יפה, הוא כיבה"]}, {"id": "i8", "name": "לשבח סיום רגוע", "what": "כשסיים/ה בלי סערה, משבחים מיד.", "why": "חיזוק מגדיל את הסיכוי לפעם הבאה.", "freq": "בכל הצלחה", "approach": "TBRI", "targets": ["t1", "t2"], "sentences": ["כיבית לבד", "עברת מהר", "כל הכבוד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'תוכנית המסכים שלנו', 'לבנות יחד כללי מסך ברורים, ולשחק גם ביחד', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['CPS', 'סמכות חדשה', 'TBRI', 'מעגל הביטחון', 'ויסות חושי']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לשנות כללים לפי מצב רוח, ולא להשתמש במסך כפרס או כעונש", "strengths": ["שיתוף פעולה", "אחריות", "הוגנות"], "skills": ["ויסות", "פתרון בעיות"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "תוכנית מסכים משפחתית שנבנית עם הילדים מומלצת על ידי AAP (Family Media Plan). ההתאמה למסגרת, באישור ההנהלה, היא יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "משתתף/ת בבניית כללי המסכים", "staff": "משתתף/ת בבניית הכללים", "scale": ["עדיין לא משתתף/ת", "מקשיב/ה", "מציע/ה רעיון אחד", "משתתף/ת בדיון", "מסביר/ה את הכללים לאחרים"]}, {"id": "t2", "text": "שומר/ת על הזמנים המוסכמים", "staff": "שומר/ת על זמני המסך", "scale": ["עדיין לא", "שומר/ת עם הרבה תזכורות", "שומר/ת עם תזכורת", "שומר/ת לבד ברוב הימים", "שומר/ת לבד תמיד"]}, {"id": "t3", "text": "משחק/ת במשחק מחשב ביחד עם ילד או מבוגר, בתור", "staff": "משחק/ת במסך ביחד ובתור", "scale": ["עדיין לא נותן/ת", "נותן/ת תור עם מבוגר", "משחק/ת ביחד עם עזרה", "משחק/ת ביחד", "מלמד/ת חבר"]}, {"id": "t4", "text": "בוחר/ת בפעילות בלי מסך בזמן הפנוי", "staff": "בוחר/ת גם פעילות בלי מסך", "scale": ["עדיין רק מסך", "כשמבוגר מציע", "לפעמים", "ברוב הימים", "מציע/ה לחברים"]}, {"id": "t5", "text": "כשלא מסכים/ה עם כלל, מדבר/ת במקום לריב", "staff": "מדבר/ת על כלל שלא מסכים/ה איתו", "scale": ["עדיין רב/ה או מתפרץ/ת", "כועס/ת ונרגע/ת", "מדבר/ת עם עזרה", "מדבר/ת לבד", "מציע/ה פתרון"]}], "interventions": [{"id": "i1", "name": "לבנות את הכללים יחד", "what": "בפגישת ילדים בונים כללים: מתי, כמה, איפה ומה. ההנהלה מאשרת, ותולים בתמונות.", "why": "כללים שבנו יחד שומרים יותר.", "freq": "פעם אחת ומעדכנים", "approach": "CPS", "targets": ["t1"], "sentences": ["מה חשוב לך במסכים?", "מה הוגן לכולם?", "נכתוב ונתלה"]}, {"id": "i2", "name": "לשמור על אותם כללים", "what": "כל הצוות מקפיד על אותם כללים, בכל משמרת.", "why": "כלל שמשתנה מזמין מאבק.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t2"], "sentences": ["כמו שכתוב בכללים", "גם אתמול זה היה ככה", "וגם מחר"]}, {"id": "i3", "name": "לשחק ביחד", "what": "מבוגר משחק עם הילד/ה במשחק מחשב, או זוג ילדים בתור.", "why": "משחק משותף מלמד תור ומחבר.", "freq": "מדי פעם", "approach": "TBRI", "targets": ["t3"], "sentences": ["תלמד/י אותי לשחק?", "עכשיו התור שלי", "איזה מהלך יפה"]}, {"id": "i4", "name": "להפריד שיחות משפחה", "what": "שיחות עם המשפחה, לפי ההסדר, לא נספרות בזמן המסך ולא נלקחות.", "why": "קשר עם המשפחה הוא צורך, לא בידור.", "freq": "תמיד", "approach": "מעגל הביטחון", "targets": ["t2"], "sentences": ["השיחה עם המשפחה לא נספרת", "יש לך את הזמן שלך", "וזה בנפרד"]}, {"id": "i5", "name": "מסך לא כפרס ולא כעונש", "what": "זמן המסך קבוע, ולא נוסף או נלקח בגלל התנהגות.", "why": "מסך כפרס הופך כל ויכוח למאבק על המסך.", "freq": "תמיד", "approach": "TBRI", "targets": ["t2", "t5"], "sentences": ["זמן המסך לא קשור לזה", "את מה שקרה נפתור בנפרד", "בוא/י נדבר"]}, {"id": "i6", "name": "להציע חלופות", "what": "פעילויות קבוצתיות בזמן הפנוי (משחקי קופסה, חצר, יצירה).", "why": "חלופה טובה מחליפה מאבק.", "freq": "כל יום", "approach": "ויסות חושי", "targets": ["t4"], "sentences": ["יש משחק בחצר", "מי רוצה להצטרף?", "נחזור למסך בזמן שלו"]}, {"id": "i7", "name": "לפתור מחלוקות על כללים", "what": "כשלא מסכים/ה, מקשיבים, מחפשים פתרון, ומעלים לפגישת הילדים הבאה.", "why": "ילד שמקשיבים לו לומד לדבר במקום לריב.", "freq": "בכל מחלוקת", "approach": "CPS", "targets": ["t5"], "sentences": ["מה מפריע לך בכלל?", "ומה חשוב לנו?", "נעלה את זה בפגישה"]}, {"id": "i8", "name": "לשבח שמירה על כללים", "what": "כששמר/ה על הזמנים לבד, אומרים.", "why": "חיזוק בונה הרגל.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t2"], "sentences": ["סיימת בזמן", "שמרת על הכלל", "יפה מאוד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'משהו במסך הפחיד אותי', 'לספר למבוגר כשמשהו ברשת מפחיד או מבלבל', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['ARC', 'סמכות חדשה', 'DDP/PACE']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לכעוס, לא לקחת את המכשיר כשמספרים, ולא לבקש לראות או להעביר תמונות", "strengths": ["אומץ", "אמון", "בקשת עזרה"], "skills": ["בטיחות"], "main": "6-9", "also": ["10-12"], "evidence": {"level": "derived", "note": "תוכניות בטיחות ברשת לילדים מדגישות ידע ובקשת עזרה; הראיות לשינוי התנהגות מוגבלות. העיקרון ''לא בצרות כשמספרים'' נגזר מעבודה על גילוי של ילדים; התאמה יישומית."}, "ages": {"6-9": {"targets": [{"id": "t1", "text": "מספר/ת למבוגר כשמשהו במסך הפחיד או הביך", "staff": "מספר/ת כשמשהו במסך הפחיד", "scale": ["עדיין מסתיר/ה", "מראה בהתנהגות", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מספר/ת מיד"]}, {"id": "t2", "text": "מבחין/ה בין מישהו שמכיר/ה לבין זר ברשת", "staff": "מבחין/ה בין מכר לזר ברשת", "scale": ["עדיין לא", "מקשיב/ה", "עונה נכון עם עזרה", "עונה נכון לבד", "מסביר/ה לחבר"]}, {"id": "t3", "text": "לא נותן/ת פרטים אישיים ברשת (שם מלא, מקום, תמונה)", "staff": "שומר/ת פרטים אישיים ברשת", "scale": ["עדיין לא יודע/ת", "יודע/ת עם תזכורת", "שומר/ת לפעמים", "שומר/ת לבד", "מזכיר/ה לחבר"]}, {"id": "t4", "text": "סוגר/ת או מדלג/ת על תוכן מפחיד", "staff": "סוגר/ת תוכן מפחיד", "scale": ["עדיין ממשיך/ה לצפות", "קורא/ת למבוגר", "סוגר/ת עם עזרה", "סוגר/ת לבד", "סוגר/ת ומספר/ת"]}, {"id": "t5", "text": "נרגע/ת אחרי שראה/תה משהו מפחיד", "staff": "נרגע/ת אחרי תוכן מפחיד", "scale": ["עדיין מוצף/ת זמן רב", "נרגע/ת עם הרבה עזרה", "נרגע/ת עם עזרה", "נרגע/ת מהר", "מדבר/ת על זה ברוגע"]}], "interventions": [{"id": "i1", "name": "להבטיח שלא בצרות", "what": "אומרים שוב ושוב: מי שמספר/ת על משהו במסך לא נענש/ת ולא מאבד/ת את המסך.", "why": "ילד שפוחד מעונש מסתיר.", "freq": "באופן קבוע", "approach": "ARC", "targets": ["t1"], "sentences": ["אם משהו מפחיד, תספר/י לי", "לא תהיה/תהיי בצרות", "טוב שסיפרת"]}, {"id": "i2", "name": "להסביר מכר וזר", "what": "בשפה פשוטה: מי שלא פגשנו באמת הוא זר, גם אם הוא נחמד.", "why": "ילדים לא תמיד מבינים שחבר ברשת יכול להיות זר.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t2"], "sentences": ["פגשת אותו באמת?", "אז הוא זר ברשת", "זרים לא מקבלים פרטים"]}, {"id": "i3", "name": "ללמד מה שומרים לעצמנו", "what": "רשימה פשוטה: שם מלא, מקום, בית ספר ותמונות נשארים אצלנו.", "why": "כלל ברור קל לזכור.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t3"], "sentences": ["את השם המלא שומרים לעצמנו", "איפה אתה/את גר/ה, שומרים", "ואם שואלים, מספרים לנו"]}, {"id": "i4", "name": "מסכים במקום משותף", "what": "מכשירים בשימוש בחדר משותף ולא בחדר השינה, לפי כללי המרכז.", "why": "כשמבוגר קרוב, העזרה זמינה.", "freq": "תמיד", "approach": "סמכות חדשה", "targets": ["t4", "t1"], "sentences": ["משחקים פה בסלון", "אני קרוב/ה", "קרא/י לי אם צריך"]}, {"id": "i5", "name": "להגיב ברוגע כשמספר/ת", "what": "מקשיבים בשקט, מודים, ומעבירים לפי הנוהל אם יש חשש לפגיעה.", "why": "התגובה הראשונה קובעת אם יספר/תספר שוב.", "freq": "בכל גילוי", "approach": "ARC", "targets": ["t1"], "sentences": ["תודה שסיפרת לי", "עשית נכון", "אני אדאג לזה"], "avoid": "לא לכעוס, לא לבקש לראות או להעביר תמונות"}, {"id": "i6", "name": "לדבר אחרי תוכן מפחיד", "what": "שיחה קצרה: מה ראית, מה הרגשת, מה נכון ומה לא. ואז פעילות מרגיעה.", "why": "שיחה מסדרת את מה שהפחיד.", "freq": "אחרי כל מקרה", "approach": "DDP/PACE", "targets": ["t5"], "sentences": ["זה נראה ממש מפחיד", "עכשיו אתה/את פה, ואני לידך", "בוא/י נעשה משהו נעים"]}, {"id": "i7", "name": "לתרגל: סוגרים וקוראים", "what": "מתרגלים בזמן רגוע: רואים משהו מפחיד, סוגרים את המסך וקוראים למבוגר.", "why": "תרגול הופך את התגובה לאוטומטית.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t4"], "sentences": ["מה עושים אם משהו מפחיד?", "סוגרים וקוראים", "בדיוק"]}, {"id": "i8", "name": "לשים לב לשינויים", "what": "סודיות סביב מכשיר, פחד פתאומי או סיוטים מעבירים למטפלת.", "why": "אלה יכולים להיות סימנים למשהו שקרה ברשת.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t1", "t5"], "sentences": ["נראה שמשהו מטריד אותך", "אני פה", "תמיד אפשר לספר"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'הטלפון, המשפחה והפרטיות שלי', 'להבין את כללי הטלפון במרכז, לשמור על עצמי ברשת, ולדעת מה עושים בבריונות', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['ARC', 'CPS', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא לקחת את הטלפון כעונש, ולא להסביר הסדרי קשר בלי המטפלת", "strengths": ["אחריות", "אומץ", "שיקול דעת"], "skills": ["בטיחות", "פתרון בעיות"], "main": "10-12", "also": ["13-15"], "evidence": {"level": "derived", "note": "הדרכה על בריונות ברשת (צילום מסך, חסימה, דיווח) נתמכת בהנחיות מקצועיות. ההסבר על הסדרי קשר עם המשפחה נעשה בהנחיית המטפלת; התאמה יישומית."}, "ages": {"10-12": {"targets": [{"id": "t1", "text": "מבין/ה את כללי הטלפון במרכז ואת הסדרי הקשר עם המשפחה", "staff": "מבין/ה את כללי הטלפון והקשר", "scale": ["עדיין כועס/ת ולא מבין/ה", "מקשיב/ה להסבר", "חוזר/ת על הכללים", "מקבל/ת את רוב הכללים", "מבין/ה ושואל/ת כשלא ברור"]}, {"id": "t2", "text": "בבריונות ברשת: מצלם/ת מסך, חוסם/ת ומספר/ת", "staff": "יודע/ת מה עושים בבריונות ברשת", "scale": ["עדיין לא יודע/ת", "יודע/ת עם הסבר", "עושה חלק", "עושה הכל עם עזרה", "עושה הכל לבד"]}, {"id": "t3", "text": "שומר/ת על הגדרות פרטיות ולא מקבל/ת זרים", "staff": "שומר/ת הגדרות פרטיות", "scale": ["עדיין לא", "עם מבוגר", "עם תזכורת", "לבד", "מזכיר/ה לחבר"]}, {"id": "t4", "text": "מספר/ת על מתנות, כסף או בקשות מוזרות ממישהו ברשת", "staff": "מספר/ת על הצעות מוזרות ברשת", "scale": ["עדיין מסתיר/ה", "מספר/ת כששואלים", "מספר/ת אחרי זמן", "מספר/ת מיוזמתו/ה", "מספר/ת מיד"]}, {"id": "t5", "text": "מדבר/ת על כללי הטלפון בלי להתפרץ", "staff": "מדבר/ת על הכללים בלי להתפרץ", "scale": ["עדיין מתפרץ/ת", "כועס/ת ונרגע/ת", "מדבר/ת עם עזרה", "מדבר/ת לבד", "מציע/ה פתרון"]}], "interventions": [{"id": "i1", "name": "להסביר את הסדרי הקשר (בהנחיית המטפלת)", "what": "הסבר כן ופשוט מתי ועם מי אפשר לדבר, ולמה. המטפלת קובעת מה אומרים.", "why": "כלל שמבינים את הסיבה שלו קל יותר לקבל.", "freq": "בתחילת המטרה ובכל שינוי", "approach": "ARC", "targets": ["t1"], "sentences": ["ככה זה עובד עכשיו", "אלה הזמנים שנקבעו, והמטפלת יכולה להסביר למה", "מה עוד לא ברור?"]}, {"id": "i2", "name": "ללמד מה עושים בבריונות", "what": "שלושה צעדים: מצלמים מסך, חוסמים, מספרים למבוגר. לא עונים בחזרה.", "why": "צעדים ברורים נותנים כוח במקום חוסר אונים.", "freq": "מדי פעם", "approach": "ARC", "targets": ["t2"], "sentences": ["מצלמים, חוסמים, מספרים", "לא עונים לו", "אני אעזור"]}, {"id": "i3", "name": "לסדר הגדרות פרטיות יחד", "what": "בטלפון שהוא/היא משתמש/ת בו, אישי או של המרכז לפי כללי המרכז, יושבים יחד ומגדירים פרטיות, ומדברים למה.", "why": "עשייה משותפת מלמדת יותר מהסבר.", "freq": "פעם אחת ובודקים מדי פעם", "approach": "CPS", "targets": ["t3"], "sentences": ["מי יכול לראות את התמונות שלך?", "בוא/י נשנה", "עכשיו רק חברים"]}, {"id": "i4", "name": "הטלפון לא נלקח כעונש", "what": "הגבלות טלפון רק לפי כללי המרכז או בעניין בטיחות, לא כעונש על התנהגות.", "why": "טלפון שנלקח כעונש מלמד להסתיר.", "freq": "תמיד", "approach": "TBRI", "targets": ["t4", "t5"], "sentences": ["הטלפון לא קשור למה שקרה", "את זה נפתור בשיחה", "אני רוצה שתספר/י לי דברים"]}, {"id": "i5", "name": "לשים לב לסימני סכנה", "what": "על טלפון חדש, מתנות, כסף או ''חבר'' חדש ומבוגר מדווחים מיד לפי הנוהל.", "why": "אלה סימנים מוכרים לפיתוי ברשת.", "freq": "לפי הצורך", "approach": "ARC", "targets": ["t4"], "sentences": ["מאיפה הטלפון החדש?", "אני שואל/ת כי אכפת לי", "אתה/את לא בצרות"]}, {"id": "i6", "name": "להגיב ברוגע כשמספר/ת", "what": "מקשיבים, מודים, ומעבירים לפי הנוהל, בלי לכעוס ובלי לקחת את המכשיר.", "why": "תגובה רגועה שומרת על הרצון לספר.", "freq": "בכל גילוי", "approach": "ARC", "targets": ["t4", "t2"], "sentences": ["תודה שסיפרת", "אתה/את לא בצרות", "אני מטפל/ת בזה"], "avoid": "לא לבקש לראות או להעביר תמונות"}, {"id": "i7", "name": "לדבר כשכועס/ת על כלל", "what": "מקשיבים לכעס, מסבירים שוב, ומחפשים יחד מה אפשר לשנות.", "why": "כעס שמקשיבים לו נרגע.", "freq": "בכל כעס", "approach": "CPS", "targets": ["t5"], "sentences": ["אתה/את כועס/ת על הכלל", "מה הכי קשה בו?", "מה כן אפשר?"]}, {"id": "i8", "name": "לשבח שמירה ופנייה", "what": "כשחסם/ה, סיפר/ה או שמר/ה על פרטיות, משבחים.", "why": "חיזוק בונה הרגל בטוח.", "freq": "בהזדמנות", "approach": "TBRI", "targets": ["t2", "t3"], "sentences": ["חסמת וסיפרת", "עשית בדיוק נכון", "יפה מאוד"]}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;
insert into public.mercury_library (scope, kind, title, description, themes, category, methods, content, draft) values ('mercury', 'goal', 'חיים דיגיטליים בטוחים', 'לזהות פיתוי ולחץ ברשת, ולדעת שאפשר לפנות גם אם כבר קרה משהו', array['מסכים וחיים דיגיטליים']::text[], 'מסכים וחיים דיגיטליים', array['ARC', 'CPS', 'DDP/PACE', 'TBRI']::text[], '{"v": 2, "bank": 3, "review": 3, "avoid": "לא להאשים, לא לבייש, לא לבקש לראות או להעביר תמונות, ולא לקחת את הטלפון כעונש", "strengths": ["שיקול דעת", "אומץ", "עצמאות"], "skills": ["בטיחות"], "main": "13-15", "also": [], "evidence": {"level": "derived", "note": "ידע על פיתוי ברשת וסחיטה מינית, והמסר ''זה לא באשמתך'', מופיעים בהנחיות של גופי הגנה על ילדים. אין ראיות חזקות לתוכנית מסוימת; ההתאמה בהנחיית המטפלת."}, "ages": {"13-15": {"targets": [{"id": "t1", "text": "מזהה סימנים של פיתוי ברשת (מחמאות, סודות, מתנות, בידוד)", "staff": "מזהה סימני פיתוי ברשת", "scale": ["עדיין לא מזהה", "מזהה עם הסבר", "מזהה חלק", "מזהה רוב הסימנים", "מזהה ומזהיר/ה חבר"]}, {"id": "t2", "text": "פונה למבוגר גם כשמשהו כבר קרה (תמונה, סחיטה)", "staff": "פונה למבוגר גם אחרי שקרה משהו", "scale": ["עדיין מסתיר/ה", "פונה אחרי זמן רב", "פונה כשמבוגר שואל", "פונה מיוזמתו/ה", "פונה מיד"]}, {"id": "t3", "text": "שומר/ת על כללי הטלפון בלילה שבנו יחד", "staff": "שומר/ת על כללי הלילה", "scale": ["עדיין לא", "עם הרבה תזכורות", "עם תזכורת", "לבד ברוב הלילות", "לבד תמיד"]}, {"id": "t4", "text": "אומר/ת ''לא'' ללחץ לשלוח תמונות או להיפגש", "staff": "אומר/ת לא ללחץ ברשת", "scale": ["עדיין נענה/נענית", "מהסס/ת ומספר/ת", "אומר/ת לא עם עזרה", "אומר/ת לא לבד", "חוסם/ת ומספר/ת"]}, {"id": "t5", "text": "מדבר/ת עם מבוגר על מה שקורה ברשת", "staff": "מדבר/ת על מה שקורה ברשת", "scale": ["עדיין לא מדבר/ת", "עונה בקצרה", "מספר/ת כששואלים", "מספר/ת מיוזמתו/ה", "מתייעץ/ת לפני שמחליט/ה"]}], "interventions": [{"id": "i1", "name": "לדבר על סימני פיתוי (בהנחיית המטפלת)", "what": "שיחה על איך נראה פיתוי: הרבה מחמאות, ''רק אני מבין אותך'', סודות, מתנות, בקשה לעבור לאפליקציה אחרת.", "why": "מי